	["A 32 px button that fades until the mouse is on it."] = "Eine Schaltfläche mit 32 px, die verblasst, bis die Maus darauf ist.",
	["A 36 px button with rune counts; the list closes after a cast."] = "Eine Schaltfläche mit 36 px mit Runenanzahl; die Liste schließt sich nach dem Wirken.",
	["A 3D portrait in its own box, a name bar with race and class, a thick health bar, and level and class badges. Pairs with the Boxed party frames."] = "Ein 3D-Porträt in eigenem Feld, eine Namensleiste mit Volk und Klasse, eine dicke Gesundheitsleiste sowie Abzeichen für Stufe und Klasse. Passt zu den Gruppenrahmen im Stil Kasten.",
	["A 46 px button with rune counts, easy to hit."] = "Eine Schaltfläche mit 46 px mit Runenanzahl, leicht zu treffen.",
	["A Pin button in the Loot Guide's Crafting details, and Alt-click on a recipe in the Alts window's Professions tab."] = "Eine Schaltfläche „Anheften“ in den Herstellungsdetails des Loot Guide und Alt-Klick auf ein Rezept im Reiter Berufe des Twink-Fensters.",
	["A Pin button on the game's profession window, next to the selected recipe."] = "Eine Schaltfläche „Anheften“ im Berufsfenster des Spiels, neben dem gewählten Rezept.",
	["A Training tab under Blizzard's spellbook that lays this list over the spellbook pages."] = "Ein Reiter „Training“ unter Blizzards Zauberbuch, der diese Liste über die Seiten des Zauberbuchs legt.",
	["A bar under the browse page: role needed, level fits, not full, friends or guild, a name filter and dismissed listings."] = "Eine Leiste unter der Suchseite: Rolle gesucht, Stufe passt, nicht voll, Freunde oder Gilde, ein Namensfilter und verworfene Einträge.",
	["A bar with ready check, role check, pull countdown, world markers, target icons and group tools for leaders and assists."] = "Eine Leiste mit Bereitschaftscheck, Rollenabfrage, Pull-Countdown, Weltmarkierungen, Zielsymbolen und Gruppenwerkzeugen für Leiter und Assistenten.",
	["A box above the friends list. Rows that don't match what you type fade out; nothing is filtered away. The social window keeps its own search bar."] = "Ein Feld über der Freundesliste. Zeilen, die nicht zu Eurer Eingabe passen, verblassen; nichts wird weggefiltert. Das soziale Fenster behält seine eigene Suchleiste.",
	["A bright line at the end of the fill."] = "Eine helle Linie am Ende der Füllung.",
	["A button (and key) for the item of the super-tracked quest, or of the first tracked quest that has one. Move it with /eui move."] = "Eine Schaltfläche (und Taste) für den Gegenstand der hervorgehobenen Quest oder der ersten verfolgten Quest, die einen hat. Verschiebt sie mit /eui move.",
	["A button at vendors that sell items on your list. It buys what's missing, after the confirm question."] = "Eine Schaltfläche bei Händlern, die Gegenstände Eurer Liste verkaufen. Sie kauft, was fehlt, nach der Bestätigungsfrage.",
	["A button that casts Feed Pet on the chosen food."] = "Eine Schaltfläche, die „Tier füttern“ auf das gewählte Futter wirkt.",
	["A button that puts the preview's weapons away or draws them."] = "Eine Schaltfläche, die die Waffen der Vorschau wegsteckt oder zieht.",
	["A button that removes all world markers (and all target icons on the icon row)."] = "Eine Schaltfläche, die alle Weltmarkierungen entfernt (und alle Zielsymbole in der Symbolreihe).",
	["A button that sends the summary line to party or raid chat when you click it."] = "Eine Schaltfläche, die die Zusammenfassung per Klick in den Gruppen- oder Schlachtzugschat sendet.",
	["A button with your tracked quest's item. Bind a key to it to use the item with your key press. It changes only out of combat."] = "Eine Schaltfläche mit dem Gegenstand Eurer verfolgten Quest. Legt eine Taste darauf, um den Gegenstand per Tastendruck zu benutzen. Sie wechselt nur außerhalb des Kampfes.",
	["A card at each level-up: how long the level took and the difference to your reference."] = "Eine Karte bei jedem Stufenaufstieg: wie lange die Stufe gedauert hat und der Unterschied zu Eurer Referenz.",
	["A card left of the top center. Click it to target the rare; right-click or x closes it. In combat it waits until combat ends."] = "Eine Karte links der oberen Mitte. Klickt darauf, um den raren Gegner anzuvisieren; Rechtsklick oder x schließt sie. Im Kampf wartet sie, bis der Kampf endet.",
	["A card when the game marks a treasure or chest on the minimap. Click it to set a waypoint."] = "Eine Karte, wenn das Spiel einen Schatz oder eine Truhe auf der Minikarte markiert. Klickt darauf, um einen Wegpunkt zu setzen.",
	["A card when the game marks an event on the minimap. Click it to set a waypoint."] = "Eine Karte, wenn das Spiel ein Ereignis auf der Minikarte markiert. Klickt darauf, um einen Wegpunkt zu setzen.",
	["A carved statue stands on the outer side of each orb, left of health and right of power. Only skins that draw statues show them, such as Infernal Stone."] = "An der Außenseite jeder Kugel steht eine gemeißelte Statue, links der Gesundheit und rechts der Ressource. Nur Skins, die Statuen zeichnen, zeigen sie, etwa Infernal Stone.",
	["A character"] = "Ein Charakter",
	["A chat line when a guild member comes online or goes offline."] = "Eine Chatzeile, wenn ein Gildenmitglied online oder offline geht.",
	["A chat line when a profession reaches the top of its rank, such as First Aid at 75/75, naming the rank to train. Also a card in the EldoUI alert lane when that lane is on."] = "Eine Chatzeile, wenn ein Beruf das Ende seines Rangs erreicht, etwa Erste Hilfe bei 75/75, mit dem Rang, den Ihr als Nächstes erlernen könnt. Zusätzlich eine Karte in der EldoUI-Warnspalte, wenn diese Spalte an ist.",
	["A chat line when a waypoint is added, removed or reached."] = "Eine Chatzeile, wenn ein Wegpunkt hinzugefügt, entfernt oder erreicht wird.",
	["A check box on every letter and a bar under the mailbox: open the checked letters, or return them to their senders (asks first)."] = "Ein Kontrollkästchen auf jedem Brief und eine Leiste unter dem Briefkasten: die angehakten Briefe öffnen oder an ihre Absender zurückschicken (fragt vorher).",
	["A check mark instead of the count once you have enough of a reagent."] = "Ein Häkchen statt der Anzahl, sobald Ihr genug von einem Reagenz habt.",
	["A check mark on what is done; nothing is hidden."] = "Ein Häkchen bei Erledigtem; nichts wird ausgeblendet.",
	["A class buff with less time left than this shows as running out (yellow)."] = "Ein Klassen-Stärkungszauber mit weniger Restzeit als diesem Wert gilt als auslaufend (gelb).",
	["A class or role icon on the frame's edge. Round in the Blizzard and Classic skins, square in Modern (Layout and style > Appearance)."] = "Ein Klassen- oder Rollensymbol am Rand des Rahmens. Rund in den Skins Blizzard und Classic, eckig in Modern (Layout und Stil > Erscheinungsbild).",
	["A clear EldoUI prompt with who, where and a countdown. You still click Accept; nothing is accepted for you."] = "Eine klare EldoUI-Abfrage mit wer, wo und einem Countdown. Ihr klickt weiterhin selbst auf Annehmen; nichts wird für Euch angenommen.",
	["A click puts it on %s."] = "Ein Klick legt ihn auf %s.",
	["A column of gear slots on the preview showing what it wears; click one to take just that piece off."] = "Eine Spalte mit Ausrüstungsplätzen an der Vorschau, die zeigt, was sie trägt; klickt einen an, um nur dieses Teil abzulegen.",
	["A column with each member's answer to the ready check: ready, not ready or waiting."] = "Eine Spalte mit der Antwort jedes Mitglieds auf den Bereitschaftscheck: bereit, nicht bereit oder wartend.",
	["A column with the class buffs a member is missing."] = "Eine Spalte mit den Klassen-Stärkungszaubern, die einem Mitglied fehlen.",
	["A compact 7 x 2 block with the bags on top."] = "Ein kompakter Block mit 7 x 2 und den Taschen oben.",
	["A consumable buff or weapon enchant with less time left than this shows (yellow)."] = "Ein Stärkungszauber durch Verbrauchsgüter oder eine Waffenverzauberung mit weniger Restzeit als diesem Wert wird angezeigt (gelb).",
	["A copy of the active scale that you can rename and tune."] = "Eine Kopie der aktiven Gewichtung, die Ihr umbenennen und anpassen könnt.",
	["A countdown bar when the group finder says your dungeon is ready."] = "Eine Countdownleiste, wenn die Gruppensuche meldet, dass Euer Dungeon bereit ist.",
	["A countdown on the ready check and battleground pop-up."] = "Ein Countdown beim Bereitschaftscheck und beim Schlachtfeld-Fenster.",
	["A cutscene or movie you already watched (on any character) is skipped. /eui cutscenes forget plays them again. Off by default."] = "Eine Zwischensequenz oder ein Film, den Ihr schon gesehen habt (mit einem beliebigen Charakter), wird übersprungen. /eui cutscenes forget spielt sie wieder ab. Standardmäßig aus.",
	["A dark overlay over the bar that keeps the name readable."] = "Eine dunkle Überlagerung auf der Leiste, die den Namen lesbar hält.",
	["A demon you did not allow is out"] = "Ein Dämon, den Ihr nicht erlaubt habt, ist beschworen",
	["A different health bar texture."] = "Eine andere Textur für die Gesundheitsleiste.",
	["A dungeon or battleground invite brings the interface back at once, so you can answer it."] = "Eine Einladung in einen Dungeon oder auf ein Schlachtfeld holt die Oberfläche sofort zurück, damit Ihr antworten könnt.",
	["A faint shadow around the panel so it lifts off bright zones."] = "Ein schwacher Schatten um das Panel, damit es sich von hellen Gebieten abhebt.",
	["A faint tint on every other row of the sent log."] = "Eine schwache Tönung auf jeder zweiten Zeile des Versandprotokolls.",
	["A faint tint on every other row."] = "Eine schwache Tönung auf jeder zweiten Zeile.",
	["A flat EldoUI box behind every alert; no glow and shine flash."] = "Ein flaches EldoUI-Feld hinter jeder Warnung; kein Leuchten und kein Glanzblitz.",
	["A flat Ignore tab next to Friends / Recent Allies (under the social window) that opens Blizzard's ignore list (also in the Contacts menu)."] = "Ein flacher Reiter „Ignorieren“ neben Freunde / Kürzliche Verbündete (unter dem sozialen Fenster), der Blizzards Ignorierliste öffnet (auch im Kontaktmenü).",
	["A full panel with the art style's frame line, bronze under WoW Forever."] = "Ein volles Panel mit der Rahmenlinie des Grafikstils, bronzen unter WoW Forever.",
	["A glow on the shield or an imbue while it is missing. The shield's glow shows out of combat only: the game hides your auras from addons in combat (the faded icon still shows)."] = "Ein Leuchten auf dem Schild oder einer Waffenverzauberung, solange sie fehlt. Das Leuchten des Schilds erscheint nur außerhalb des Kampfes: Das Spiel verbirgt Eure Auren im Kampf vor Addons (das verblasste Symbol bleibt sichtbar).",
	["A glow round this frame while its unit is your target (look: the Glows page, \"Unit frames: your target\")."] = "Ein Leuchten um diesen Rahmen, solange seine Einheit Euer Ziel ist (Optik: Seite „Leuchteffekte“, „Einheitenrahmen: Euer Ziel“).",
	["A gold fill shows the XP waiting in finished quests you have not handed in yet."] = "Eine goldene Füllung zeigt die EP, die in abgeschlossenen, noch nicht abgegebenen Quests warten.",
	["A green arrow with the gain in the tooltip's info area. Its visibility (Always / Shift ...) is set on the Tooltip page."] = "Ein grüner Pfeil mit dem Zugewinn im Infobereich des Tooltips. Seine Sichtbarkeit (Immer / Umschalt ...) wird auf der Seite Tooltip eingestellt.",
	["A green arrow with the gain when an item beats what you wear, by your active scale."] = "Ein grüner Pfeil mit dem Zugewinn, wenn ein Gegenstand nach Eurer aktiven Gewichtung besser ist als das Getragene.",
	["A grip in the bottom-right corner; the size is remembered."] = "Ein Griff in der unteren rechten Ecke; die Größe wird gespeichert.",
	["A harmless pop-up to check the look and the position. It does nothing."] = "Ein harmloses Fenster, um Optik und Position zu prüfen. Es bewirkt nichts.",
	["A large icon when a class buff, gathering tracking or a chosen consumable is missing or running out."] = "Ein großes Symbol, wenn ein Klassen-Stärkungszauber, das Aufspüren für Sammelberufe oder ein gewähltes Verbrauchsgut fehlt oder ausläuft.",
	["A leveling timer that races your own best: time on this level, the difference to your best character, a card at each level-up and a Splits tab in the Characters window."] = "Ein Leveltimer, der gegen Eure eigene Bestzeit läuft: Zeit auf dieser Stufe, der Unterschied zu Eurem besten Charakter, eine Karte bei jedem Stufenaufstieg und ein Reiter „Splits“ im Twink-Fenster.",
	["A light sheen on your target's bar."] = "Ein leichter Glanz auf der Leiste Eures Ziels.",
	["A lighter fill shows how far your rested bonus reaches."] = "Eine hellere Füllung zeigt, wie weit Euer Erholungsbonus reicht.",
	["A line in the quest window, the quest log and the dialog view that says where a quest sits in its chain, like Part 2 of 5 and the next step. On by default."] = "Eine Zeile im Questfenster, im Questlog und in der Dialogansicht, die zeigt, wo eine Quest in ihrer Questreihe steht, etwa Teil 2 von 5 und der nächste Schritt. Standardmäßig an.",
	["A line in your chat each time the layer you are on changes."] = "Eine Zeile in Eurem Chat bei jedem Wechsel Eures Layers.",
	["A line under the click-binding window: whether EldoUI shows these bindings on party and raid tooltips, with a button to its settings."] = "Eine Zeile unter dem Klickbelegungsfenster: ob EldoUI diese Belegungen in Gruppen- und Schlachtzugstooltips zeigt, mit einer Schaltfläche zu den Einstellungen.",
	["A line with the place and a map link in your own chat frame. Nothing is sent to others. Off by default: the card and the sound already tell you."] = "Eine Zeile mit dem Ort und einem Kartenlink in Eurem eigenen Chatfenster. Nichts wird an andere gesendet. Standardmäßig aus: Karte und Ton sagen es Euch bereits.",
	["A list beside the trainer with everything it teaches, now and at later levels, with rank, level and cost. With Training on, class trainers show that window instead."] = "Eine Liste neben dem Lehrer mit allem, was er lehrt, jetzt und auf späteren Stufen, mit Rang, Stufe und Kosten. Ist Training an, zeigen Klassenlehrer stattdessen dieses Fenster.",
	["A loadout is a saved set of four totems. Right-click Drop All to switch, save, rename, share or delete. A switch waits for out of combat."] = "Eine Zusammenstellung ist ein gespeicherter Satz aus vier Totems. Rechtsklick auf „Alle aufstellen“ zum Wechseln, Speichern, Umbenennen, Teilen oder Löschen. Ein Wechsel wartet bis nach dem Kampf.",
	["A lower spell rank: %s changes only the rank number."] = "Ein niedrigerer Zauberrang: %s ändert nur die Rangnummer.",
	["A menu holds up to %d entries."] = "Ein Menü fasst bis zu %d Einträge.",
	["A message when your pet's happiness drops to content or unhappy."] = "Eine Nachricht, wenn die Zufriedenheit Eures Tiers auf zufrieden oder unglücklich sinkt.",
	["A mono font with colors and line numbers, like a code editor."] = "Eine Festbreitenschrift mit Farben und Zeilennummern, wie in einem Code-Editor.",
	["A name for the rule list."] = "Ein Name für die Regelliste.",
	["A new route shows the time so far with \"learning\"; the next flight on it shows the full time. Times come from your flights only."] = "Eine neue Route zeigt die bisherige Zeit mit „wird erfasst“; der nächste Flug darauf zeigt die volle Zeit. Die Zeiten stammen nur aus Euren eigenen Flügen.",
	["A note when a weapon imbue is running out or gone: in the Combat Text notification lane in combat, an alert card out of combat."] = "Ein Hinweis, wenn eine Waffenverzauberung ausläuft oder weg ist: im Kampf in der Hinweisspalte des Kampftexts, außerhalb des Kampfes als Hinweiskarte.",
	["A note when fewer than %d of the chosen food are left. It comes again after you restock."] = "Ein Hinweis, wenn weniger als %d vom gewählten Futter übrig sind. Er kommt nach dem Auffüllen erneut.",
	["A note while your pet is set to passive."] = "Ein Hinweis, solange Euer Tier auf passiv steht.",
	["A panel behind the buttons."] = "Ein Panel hinter den Schaltflächen.",
	["A panel behind the timer; off shows the text alone."] = "Ein Panel hinter dem Timer; aus zeigt nur den Text.",
	["A panel behind the tracker in the EldoUI art style. None keeps Blizzard's background (opacity from Edit Mode)."] = "Ein Panel hinter der Zielverfolgung im EldoUI-Grafikstil. Keins behält Blizzards Hintergrund (Deckkraft aus dem Bearbeitungsmodus).",
	["A panel in the EldoUI art style. Off keeps Blizzard's border."] = "Ein Panel im EldoUI-Grafikstil. Aus behält Blizzards Rand.",
	["A plan that starts with the talents you have now."] = "Ein Plan, der mit Euren jetzigen Talenten beginnt.",
	["A plate near the middle of the screen that follows your settings as you change them."] = "Eine Plakette nahe der Bildschirmmitte, die Euren Einstellungen folgt, während Ihr sie ändert.",
	["A plate of the test plate's type, in its size, text size and cast bar."] = "Eine Plakette vom Typ der Testplakette, in deren Größe, Textgröße und Zauberleiste.",
	["A player on another layer invites you; you accept in the game's popup and leave the group once your layer changes. Each step is a click."] = "Ein Spieler auf einem anderen Layer lädt Euch ein; Ihr nehmt im Fenster des Spiels an und verlasst die Gruppe, sobald Euer Layer gewechselt hat. Jeder Schritt ist ein Klick.",
	["A player..."] = "Ein Spieler...",
	["A pulsing note above the reminders during a ready check when your own mana is low. Out of combat only."] = "Ein pulsierender Hinweis über den Erinnerungen während eines Bereitschaftschecks, wenn Euer eigenes Mana niedrig ist. Nur außerhalb des Kampfes.",
	["A quest icon on mobs the game marks for one of your active quests."] = "Ein Questsymbol auf Gegnern, die das Spiel für eine Eurer aktiven Quests markiert.",
	["A quiet sighting shows"] = "Eine stille Sichtung zeigt",
	["A rare you know of yells or emotes nearby."] = "Ein rarer Gegner, den Ihr kennt, ruft oder emotet in der Nähe.",
	["A rare's nameplate appears. Enemy nameplates must be on."] = "Die Namensplakette eines raren Gegners erscheint. Feindliche Namensplaketten müssen an sein.",
	["A ready icon for this spell, once you know it."] = "Ein Bereit-Symbol für diesen Zauber, sobald Ihr ihn kennt.",
	["A reagent you can craft (a bar, a leather, a thread) shows its own reagents under it, two steps deep."] = "Ein herstellbares Reagenz (ein Barren, ein Leder, ein Faden) zeigt seine eigenen Reagenzien darunter, zwei Stufen tief.",
	["A red zone at the end of your casts, as long as your current latency."] = "Eine rote Zone am Ende Eurer Zauber, so lang wie Eure aktuelle Latenz.",
	["A restore adds what is missing but never empties a slot."] = "Eine Wiederherstellung ergänzt, was fehlt, leert aber nie einen Platz.",
	["A restore starts with only the Edit Mode layout checked."] = "Eine Wiederherstellung beginnt mit nur dem Layout des Bearbeitungsmodus angehakt.",
	["A restore starts with only the action bars checked."] = "Eine Wiederherstellung beginnt mit nur den Aktionsleisten angehakt.",
	["A restore starts with only the key bindings checked."] = "Eine Wiederherstellung beginnt mit nur den Tastenbelegungen angehakt.",
	["A riding trainer teaches it, next to the mount vendor of each race. The cost is the one a trainer asked, once you have opened one."] = "Ein Reitlehrer bringt es Euch bei, neben dem Reittierhändler jedes Volkes. Als Preis gilt der, den ein Lehrer verlangt hat, sobald Ihr einmal einen geöffnet habt.",
	["A row (left to right) or a column (top to bottom)."] = "Eine Reihe (von links nach rechts) oder eine Spalte (von oben nach unten).",
	["A row across or a column down."] = "Eine Reihe quer oder eine Spalte nach unten.",
	["A sample card of the EldoUI alert lane in its width and icon size."] = "Eine Beispielkarte der EldoUI-Warnspalte in deren Breite und Symbolgröße.",
	["A sample map in its shape, with the zone name and clock as set on the Text tab."] = "Eine Beispiel-Minikarte in ihrer Form, mit Gebietsname und Uhr wie im Reiter Text eingestellt.",
	["A sample tooltip of your character in your text sizes, opacity and colors."] = "Ein Beispieltooltip Eures Charakters in Euren Textgrößen, Eurer Deckkraft und Euren Farben.",
	["A scale gives each stat a value; an item's score is the sum. Starter scales are rough; tune one for your spec or paste a friend's."] = "Eine Gewichtung gibt jedem Wert eine Zahl; die Punktzahl eines Gegenstands ist die Summe. Die Startgewichtungen sind grob; passt eine an Eure Spezialisierung an oder fügt die eines Freundes ein.",
	["A second bar with your shield, weapon imbues and shaman cooldowns. Click an icon to cast it."] = "Eine zweite Leiste mit Eurem Schild, Waffenverzauberungen und Schamanen-Abklingzeiten. Klickt ein Symbol an, um es zu wirken.",
	["A second row that puts skull, cross and the other icons on your target."] = "Eine zweite Reihe, die Totenschädel, Kreuz und die anderen Symbole auf Euer Ziel setzt.",
	["A see-through EldoUI panel behind the tracker."] = "Ein durchscheinendes EldoUI-Panel hinter der Zielverfolgung.",
	["A see-through background in your art style behind the line under each roll."] = "Ein durchscheinender Hintergrund in Eurem Grafikstil hinter der Zeile unter jedem Wurf.",
	["A see-through compact list with buffs and the ready answer only."] = "Eine durchscheinende kompakte Liste nur mit Stärkungszaubern und der Bereitschaftsantwort.",
	["A see-through panel behind the rows."] = "Ein durchscheinendes Panel hinter den Zeilen.",
	["A see-through panel behind the top-center widgets while any show."] = "Ein durchscheinendes Panel hinter den Widgets oben in der Mitte, solange welche angezeigt werden.",
	["A see-through window over the game."] = "Ein durchscheinendes Fenster über dem Spiel.",
	["A short flash over the bar when a cast ends (needs animations on, General)."] = "Ein kurzes Aufblitzen über der Leiste, wenn ein Zauber endet (braucht eingeschaltete Animationen, Allgemein).",
	["A short message when you enter and leave combat."] = "Eine kurze Nachricht, wenn Ihr den Kampf beginnt und verlasst.",
	["A short note when someone you marked Avoid joins your group."] = "Ein kurzer Hinweis, wenn jemand, den Ihr mit Meiden markiert habt, Eurer Gruppe beitritt.",
	["A short popup when a member finishes an objective or the whole of a quest you share."] = "Ein kurzes Pop-up, wenn ein Mitglied ein Ziel oder eine ganze Quest abschließt, die Ihr teilt.",
	["A short pulse on your gamepad for each alert, a longer one for a rare with a mount, pet, toy or set piece you don't own. Only while you play with a gamepad; quiet sightings don't pulse."] = "Ein kurzes Vibrieren Eures Gamepads bei jeder Warnung, ein längeres bei einem raren Gegner mit Reittier, Begleiter, Spielzeug oder Setteil, das Ihr nicht besitzt. Nur, solange Ihr mit Gamepad spielt; stille Sichtungen vibrieren nicht.",
	["A short sound with each toast."] = "Ein kurzer Ton bei jedem Hinweis.",
	["A short strip when a cast is interrupted."] = "Ein kurzer Streifen, wenn ein Zauber unterbrochen wird.",
	["A slider under the trees that shows your plan as it stands at any level."] = "Ein Schieberegler unter den Bäumen, der Euren Plan so zeigt, wie er auf einer beliebigen Stufe aussieht.",
	["A slow glow. Its look is on the Glows page (Nameplates: target)."] = "Ein langsames Leuchten. Seine Optik steht auf der Seite „Leuchteffekte“ (Namensplaketten: Ziel).",
	["A small +/- button on the quest tracker's top row to fold it away; /eui tracker does the same. Remembered per character."] = "Eine kleine +/--Schaltfläche in der obersten Zeile der Questverfolgung, um sie einzuklappen; /eui tracker tut dasselbe. Wird pro Charakter gespeichert.",
	["A small box on the edge of an item tooltip with the Danish word for what the item is, such as Le on a scythe. The English name stays. Names never get a box."] = "Ein kleines Feld am Rand eines Gegenstandstooltips mit dem dänischen Wort für den Gegenstand, etwa Le bei einer Sense. Der englische Name bleibt. Namen bekommen nie ein Feld.",
	["A small box with your map coordinates. Click it to type coordinates and add a waypoint; right-click for more. Move it in move mode (Waypoint Coordinates)."] = "Ein kleines Feld mit Euren Kartenkoordinaten. Klickt darauf, um Koordinaten einzugeben und einen Wegpunkt hinzuzufügen; Rechtsklick für mehr. Verschiebt es im Verschiebemodus (Wegpunktkoordinaten).",
	["A small button at the top right of the world map: click for the groups, Shift-click to show or hide everything."] = "Eine kleine Schaltfläche oben rechts an der Weltkarte: Klick für die Gruppen, Umschaltklick, um alles anzuzeigen oder auszublenden.",
	["A small icon before each reagent."] = "Ein kleines Symbol vor jedem Reagenz.",
	["A small label: minimap, nameplate, target, group or yell."] = "Eine kleine Beschriftung: Minikarte, Namensplakette, Ziel, Gruppe oder Schreien.",
	["A small list beside the rare cards with this session's sightings. Click a line to set a waypoint, Shift-click to share it, right-click to remove it."] = "Eine kleine Liste neben den Karten der raren Gegner mit den Sichtungen dieser Sitzung. Klickt eine Zeile an, um einen Wegpunkt zu setzen, Umschaltklick zum Teilen, Rechtsklick zum Entfernen.",
	["A small list of the pings you receive: time, sender and what they pinged. Place it with the \"Ping Feed\" mover (/eui move)."] = "Eine kleine Liste der Pings, die Ihr erhaltet: Zeit, Absender und was gepingt wurde. Platziert sie mit dem Rahmen „Ping-Ticker“ (/eui move).",
	["A small number on each talent of your plan: which of the plan's points takes it first. The talent's tooltip lists every point. Also shown on Blizzard's talent window while Show my plan is on."] = "Eine kleine Zahl auf jedem Talent Eures Plans: welcher Punkt des Plans es zuerst nimmt. Der Tooltip des Talents listet jeden Punkt auf. Auch in Blizzards Talentfenster zu sehen, solange „Meinen Plan anzeigen“ an ist.",
	["A small one-line panel toast and a short tooltip without dungeons."] = "Ein kleiner einzeiliger Hinweis im Panel und ein kurzer Tooltip ohne Dungeons.",
	["A small panel with a master volume slider (mouse wheel works too). /eui volume shows or hides it; move it with /eui move."] = "Ein kleines Panel mit einem Regler für die Gesamtlautstärke (das Mausrad geht auch). /eui volume zeigt es an oder blendet es aus; verschiebt es mit /eui move.",
	["A small panel with only the counts: who misses what, without member rows."] = "Ein kleines Panel nur mit den Zahlen: wem was fehlt, ohne Zeilen für die Mitglieder.",
	["A small paw by pets and guardians."] = "Eine kleine Pfote bei Begleitern und Wächtern.",
	["A small spell icon before each ability."] = "Ein kleines Zaubersymbol vor jeder Fähigkeit.",
	["A small square on party frames per running buff totem: filled when the member has it, hollow when not, ? in combat (the game hides it then)."] = "Ein kleines Quadrat auf Gruppenrahmen für jedes aktive Totem mit Stärkungseffekt: gefüllt, wenn das Mitglied den Effekt hat, hohl, wenn nicht, ? im Kampf (dann verbirgt das Spiel ihn).",
	["A small window with the numbers behind each bar: level or standing, progress, remaining, rested XP and finished quests, in foldable sections. Shift-click a bar opens it too."] = "Ein kleines Fenster mit den Zahlen hinter jeder Leiste: Stufe oder Rufstufe, Fortschritt, Rest, Erholungsbonus und abgeschlossene Quests, in einklappbaren Abschnitten. Ein Umschaltklick auf eine Leiste öffnet es ebenfalls.",
	["A snapshot holds your action slots, macros, key bindings and Edit Mode layout. Restore shows each change first and can be undone."] = "Ein Schnappschuss enthält Eure Aktionsplätze, Makros, Tastenbelegungen und das Layout des Bearbeitungsmodus. Wiederherstellen zeigt jede Änderung vorher und lässt sich rückgängig machen.",
	["A soft blue tint everywhere and no tag in the quest window."] = "Überall eine sanfte blaue Tönung und kein Tag im Questfenster.",
	["A sound for ready checks, role polls and battleground or dungeon ready, once per pop-up. It plays on the Master channel, so you hear it with game sound effects off."] = "Ein Ton bei Bereitschaftschecks, Rollenabfragen und bereiten Schlachtfeldern oder Dungeons, einmal pro Pop-up. Er spielt über den Hauptkanal, sodass Ihr ihn auch bei ausgeschalteten Soundeffekten des Spiels hört.",
	["A sound when a new reminder appears (at most every 3 seconds)."] = "Ein Ton, wenn eine neue Erinnerung erscheint (höchstens alle 3 Sekunden).",
	["A sound when you arrive. None for silence."] = "Ein Ton bei der Ankunft. Keiner für Stille.",
	["A spell name or spell ID, or item: and an item ID (item:6948). Empty: the key does nothing."] = "Ein Zaubername oder eine Zauber-ID, oder item: und eine Gegenstands-ID (item:6948). Leer: Die Taste bewirkt nichts.",
	["A status mark after the name in place of Blizzard's icon: green online, yellow away, red busy, gray offline. With shape marks on, it also has a shape."] = "Eine Statusmarke hinter dem Namen statt Blizzards Symbol: grün online, gelb abwesend, rot beschäftigt, grau offline. Mit eingeschalteten Formmarken hat sie auch eine Form.",
	["A strip under the bars or a name bar over them, for extra texts (Texts tab: attach a text to the info panel)."] = "Ein Streifen unter den Leisten oder eine Namensleiste darüber, für zusätzliche Texte (Reiter Texte: einen Text an das Infopanel hängen).",
	["A tab next to the friends tabs with the last 50 players you grouped with, your Player Notes mark and note on each, and an Add friend button. Needs the Player Notes module. On by default."] = "Ein Reiter neben den Freundesreitern mit den letzten 50 Spielern, mit denen Ihr in einer Gruppe wart, jeweils mit Eurer Markierung und Notiz aus den Spielernotizen, und einer Schaltfläche „Freund hinzufügen“. Braucht das Modul Spielernotizen. Standardmäßig an.",
	["A talent loadout keeps only the final ranks: the plan takes lower rows first. Reorder it in the planner."] = "Eine Talentkonfiguration behält nur die endgültigen Ränge: Der Plan nimmt niedrigere Reihen zuerst. Ordnet ihn im Planer neu.",
	["A talent path EldoUI suggests for your class."] = "Ein Talentpfad, den EldoUI für Eure Klasse vorschlägt.",
	["A test quest"] = "Eine Testquest",
	["A text string of the plan to copy and share (!EUT1!)."] = "Ein Text-String des Plans zum Kopieren und Teilen (!EUT1!).",
	["A text string with every rule, to share or keep."] = "Ein Text-String mit jeder Regel, zum Teilen oder Aufbewahren.",
	["A thin bar across the bottom edge of the screen that frames the interface."] = "Eine dünne Leiste am unteren Bildschirmrand, die die Oberfläche einrahmt.",
	["A thin bar across the top edge of the screen that frames the interface."] = "Eine dünne Leiste am oberen Bildschirmrand, die die Oberfläche einrahmt.",
	["A thin bar under each button that empties as its totem runs out."] = "Eine dünne Leiste unter jeder Schaltfläche, die sich leert, während ihr Totem abläuft.",
	["A thin bar under each card with your own progress on the quest."] = "Eine dünne Leiste unter jeder Karte mit Eurem eigenen Fortschritt in der Quest.",
	["A thin bar with the unit's mana, rage or energy under the health bar."] = "Eine dünne Leiste mit Mana, Wut oder Energie der Einheit unter der Gesundheitsleiste.",
	["A thin edge in the element's color under each button: green earth, orange fire, blue water, light blue air."] = "Ein dünner Rand in der Farbe des Elements unter jeder Schaltfläche: grün Erde, orange Feuer, blau Wasser, hellblau Luft.",
	["A thin line along the XP bar while an XP bonus runs, such as XP food or an event. The tooltip names each bonus and its time left either way."] = "Eine dünne Linie entlang der EP-Leiste, solange ein EP-Bonus läuft, etwa durch EP-Essen oder ein Ereignis. Der Tooltip nennt in jedem Fall jeden Bonus und seine verbleibende Zeit.",
	["A thin line between the game's text and the info area."] = "Eine dünne Linie zwischen dem Text des Spiels und dem Infobereich.",
	["A thin line in your accent color on the inner edge of each panel."] = "Eine dünne Linie in Eurer Akzentfarbe am Innenrand jedes Panels.",
	["A thin timer bar under each button instead of countdown numbers."] = "Eine dünne Timerleiste unter jeder Schaltfläche statt Countdown-Zahlen.",
	["A third row for running the group. Each button is one click; nothing happens on its own."] = "Eine dritte Reihe zum Leiten der Gruppe. Jede Schaltfläche ist ein Klick; nichts passiert von selbst.",
	["A tick on each zone header tracks or untracks every quest in that zone."] = "Ein Häkchen an jeder Gebietsüberschrift verfolgt alle Quests dieses Gebiets oder beendet ihre Verfolgung.",
	["A totem bar for shamans: one button per element drops your pick, pointing at it lists its totems, and Drop All drops the whole set."] = "Eine Totemleiste für Schamanen: Eine Schaltfläche pro Element stellt Eure Wahl auf, Zeigen darauf listet ihre Totems auf, und „Alle aufstellen“ stellt den ganzen Satz auf.",
	["A totem bar with a picker per element, Drop All and timers, a cooldown bar for shields, imbues and shaman cooldowns, totem loadouts and totem buff squares on group frames. Shamans only."] = "Eine Totemleiste mit einer Auswahl pro Element, „Alle aufstellen“ und Timern, eine Abklingzeitleiste für Schilde, Waffenverzauberungen und Schamanen-Abklingzeiten, Totem-Zusammenstellungen und Quadrate für Totemeffekte auf Gruppenrahmen. Nur für Schamanen.",
	["A whisper you send from the main chat opens that conversation's window."] = "Ein Flüstern, das Ihr aus dem Hauptchat sendet, öffnet das Fenster dieser Unterhaltung.",
	["A wide see-through banner with a large zone name and an accent line."] = "Ein breites, durchscheinendes Banner mit großem Gebietsnamen und einer Akzentlinie.",
	["A wide sent log for long subjects and many items."] = "Ein breites Versandprotokoll für lange Betreffzeilen und viele Gegenstände.",
	["A wider macro editor next to Blizzard's macro window: a syntax check with hints, a condition builder and an icon search by spell or item name. Saving happens out of combat."] = "Ein breiterer Makroeditor neben Blizzards Makrofenster: eine Syntaxprüfung mit Hinweisen, ein Baukasten für Bedingungen und eine Symbolsuche nach Zauber- oder Gegenstandsname. Gespeichert wird außerhalb des Kampfes.",
	["A yellow note when a priest, mage, druid or paladin is in your group and you lack their buff. Information only. Off by default."] = "Ein gelber Hinweis, wenn ein Priester, Magier, Druide oder Paladin in Eurer Gruppe ist und Euch sein Stärkungszauber fehlt. Nur zur Information. Standardmäßig aus.",
	["A zone to travel to or from: below are its transport stops with where each goes, and the boats, zeppelins, tram and portals that arrive there."] = "Ein Gebiet als Reiseziel oder Startpunkt: Darunter stehen seine Verkehrsstationen mit ihren Zielen sowie die Schiffe, Zeppeline, die Tiefenbahn und die Portale, die dort ankommen.",
	["AH %s"] = "AH %s",
	["Abilities before \"more\""] = "Fähigkeiten vor „mehr“",
	["Abilities seen"] = "Gesehene Fähigkeiten",
	["Ability log"] = "Fähigkeitenprotokoll",
	["Ability marks"] = "Fähigkeitsmarken",
	["Ability, spell and item cooldown messages."] = "Abklingzeitmeldungen für Fähigkeiten, Zauber und Gegenstände.",
	["Above the Cooldown Manager"] = "Über dem Abklingzeitenmanager",
	["Above the cast bar"] = "Über der Zauberleiste",
	["Above the frame"] = "Über dem Rahmen",
	["Above the map"] = "Über der Karte",
	["Above the window"] = "Über dem Fenster",
	["Absorb shields"] = "Absorptionsschilde",
	["Accent border"] = "Akzentrand",
	["Accent border: on."] = "Akzentrand: an.",
	["Accent line"] = "Akzentlinie",
	["Accent senders, 24 px toolbar, roomy log."] = "Absender in Akzentfarbe, Werkzeugleiste mit 24 px, geräumiges Protokoll.",
	["Accent-colored headers"] = "Überschriften in Akzentfarbe",
	["Accept"] = "Annehmen",
	["Accept quests automatically"] = "Quests automatisch annehmen",
	["Accepts quests from NPCs when their window opens. Quests shared by other players are never accepted. Off by default."] = "Nimmt Quests von NSCs an, wenn sich ihr Fenster öffnet. Von anderen Spielern geteilte Quests werden nie angenommen. Standardmäßig aus.",
	["Achievement"] = "Erfolg",
	["Achievement name, points and icon. Click opens it in the achievement window."] = "Name, Punkte und Symbol des Erfolgs. Ein Klick öffnet ihn im Erfolgsfenster.",
	["Achievements and challenges"] = "Erfolge und Herausforderungen",
	["Achievements, criteria and Legacy challenge alerts."] = "Hinweise zu Erfolgen, Kriterien und Vermächtnis-Herausforderungen.",
	["Across"] = "Quer",
	["Across the whole screen width with numbers always shown, like the old Blizzard bar."] = "Über die ganze Bildschirmbreite mit stets sichtbaren Zahlen, wie die alte Blizzard-Leiste.",
	["Acting for you"] = "Handelt für Euch",
	["Acting for you (off by default)"] = "Handelt für Euch (standardmäßig aus)",
	["Action slots that change (%d)"] = "Aktionsplätze, die sich ändern (%d)",
	["ActionCam"] = "ActionCam",
	["ActionCam is off: the game's camera settings were put back."] = "ActionCam ist aus: Die Kameraeinstellungen des Spiels wurden zurückgesetzt.",
	["Active scale (this class)"] = "Aktive Gewichtung (diese Klasse)",
	["Acts for you when turned on: repairs all gear when you open a vendor who can repair, guild bank first if you choose it, then your own gold. Off until you pick it here or in the setup."] = "Handelt für Euch, wenn eingeschaltet: repariert die gesamte Ausrüstung, wenn Ihr einen Händler öffnet, der reparieren kann, zuerst über die Gildenbank, wenn Ihr das wählt, dann mit Eurem eigenen Gold. Aus, bis Ihr es hier oder in der Einrichtung wählt.",
	["Acts for you when turned on: sells gray items and items on your Always sell list in batches of 12 at vendors. Retries refused sales if the sale limit is off. Off by default."] = "Handelt für Euch, wenn eingeschaltet: verkauft bei Händlern graue Gegenstände und Gegenstände auf Eurer Liste Immer verkaufen in Schüben von je 12. Versucht abgelehnte Verkäufe erneut, wenn die Verkaufsgrenze aus ist. Standardmäßig aus.",
	["Acts for you. Accept and turn in quests (never picks a reward) and skip plain vendor chat. Hold Shift to pause."] = "Handelt für Euch. Quests annehmen und abgeben (wählt nie eine Belohnung) und einfache Händlergespräche überspringen. Haltet Umschalt zum Pausieren.",
	["Acts for you. Strangers' duels, invites, join requests and shared quests declined; duel and drunk spam hidden."] = "Handelt für Euch. Duelle, Einladungen, Beitrittsanfragen und geteilte Quests von Fremden werden abgelehnt; Duell- und Betrunken-Spam wird ausgeblendet.",
	["Acts for you: a click on a reminder casts the missing buff or uses the consumable, one cast per click and never by itself."] = "Handelt für Euch: Ein Klick auf eine Erinnerung wirkt den fehlenden Stärkungszauber oder benutzt das Verbrauchsgut, ein Wirken pro Klick und nie von selbst.",
	["Acts for you: accepts quests from NPCs when their window opens, never quests other players share."] = "Handelt für Euch: nimmt Quests von NSCs an, wenn sich ihr Fenster öffnet, nie Quests, die andere Spieler teilen.",
	["Acts for you: asks to buy what your restock list is missing when you open a vendor who sells it, and buys only after you say yes."] = "Handelt für Euch: fragt, ob Ihr kaufen wollt, was Eurer Auffüllliste fehlt, wenn Ihr einen Händler öffnet, der es verkauft, und kauft erst, wenn Ihr Ja sagt.",
	["Acts for you: asks to fill your quiver or ammo pouch when you open a vendor who sells your ammo, and buys only after you say yes."] = "Handelt für Euch: fragt, ob Euer Köcher oder Munitionsbeutel gefüllt werden soll, wenn Ihr einen Händler öffnet, der Eure Munition verkauft, und kauft erst, wenn Ihr Ja sagt.",
	["Acts for you: confirms Bind on Pickup items when you loot alone. Group loot and other confirmations still ask. Change this in Loot settings."] = "Handelt für Euch: bestätigt Gegenstände, die beim Aufheben gebunden werden, wenn Ihr allein plündert. Gruppenbeute und andere Bestätigungen fragen weiterhin. Änderbar in den Beute-Einstellungen.",
	["Acts for you: declines duel requests from people who aren't your friends, out of combat."] = "Handelt für Euch: lehnt außerhalb des Kampfes Duellanfragen von Leuten ab, die nicht Eure Freunde sind.",
	["Acts for you: declines group invites from people who aren't your friends, out of combat."] = "Handelt für Euch: lehnt außerhalb des Kampfes Gruppeneinladungen von Leuten ab, die nicht Eure Freunde sind.",
	["Acts for you: declines guild invites from anyone but your friends, out of combat."] = "Handelt für Euch: lehnt außerhalb des Kampfes Gildeneinladungen von allen außer Euren Freunden ab.",
	["Acts for you: declines quests shared by people who aren't your friends, out of combat."] = "Handelt für Euch: lehnt außerhalb des Kampfes Quests ab, die Leute teilen, die nicht Eure Freunde sind.",
	["Acts for you: declines requests to join your group from people who aren't your friends, out of combat."] = "Handelt für Euch: lehnt außerhalb des Kampfes Beitrittsanfragen für Eure Gruppe von Leuten ab, die nicht Eure Freunde sind.",
	["Acts for you: hands in finished quests and stops when there is a reward to choose, so you always pick it."] = "Handelt für Euch: gibt abgeschlossene Quests ab und hält an, wenn eine Belohnung zu wählen ist, damit Ihr sie immer selbst wählt.",
	["Acts for you: repairs all gear when you open a vendor who can repair."] = "Handelt für Euch: repariert die gesamte Ausrüstung, wenn Ihr einen Händler öffnet, der reparieren kann.",
	["Acts for you: sells gray items when you open a vendor, in batches of 12. Only the last 12 sold stacks stay in the buyback tab."] = "Handelt für Euch: verkauft graue Gegenstände, wenn Ihr einen Händler öffnet, in Schüben von je 12. Nur die letzten 12 verkauften Stapel bleiben im Rückkauf-Reiter.",
	["Acts for you: skips a cutscene or movie you already watched on any character."] = "Handelt für Euch: überspringt eine Zwischensequenz oder einen Film, den Ihr schon mit einem beliebigen Charakter gesehen habt.",
	["Acts for you: the word the game asks for before you destroy a rare item or a quest item is typed in. You still press Yes yourself."] = "Handelt für Euch: Das Wort, das das Spiel verlangt, bevor Ihr einen raren Gegenstand oder einen Questgegenstand zerstört, wird eingetragen. Auf Ja drückt Ihr weiterhin selbst.",
	["Acts for you: when an NPC only has a shop and no quest for you, the shop opens at once."] = "Handelt für Euch: Hat ein NSC nur einen Laden und keine Quest für Euch, öffnet sich der Laden sofort.",
	["Acts for you: when you enter the world, a dungeon, a raid or a battleground, the totem bar switches to the loadout you picked for it, out of combat."] = "Handelt für Euch: Wenn Ihr die Welt, einen Dungeon, einen Schlachtzug oder ein Schlachtfeld betretet, wechselt die Totemleiste außerhalb des Kampfes zu der Zusammenstellung, die Ihr dafür gewählt habt.",
	["Add"] = "Hinzufügen",
	["Add a button by name"] = "Schaltfläche nach Name hinzufügen",
	["Add a cut..."] = "Abzug hinzufügen...",
	["Add a player..."] = "Spieler hinzufügen...",
	["Add a spell ID"] = "Zauber-ID hinzufügen",
	["Add a waypoint"] = "Wegpunkt hinzufügen",
	["Add a waypoint with /way 45 63 Goldshire or Ctrl-right-click on the world map. /way list opens the Waypoints window."] = "Fügt einen Wegpunkt mit /way 45 63 Goldhain oder Strg-Rechtsklick auf die Weltkarte hinzu. /way list öffnet das Fenster Wegpunkte.",
	["Add all"] = "Alle hinzufügen",
	["Add an empty rule at the end of the list."] = "Eine leere Regel am Ende der Liste hinzufügen.",
	["Add an entry"] = "Eintrag hinzufügen",
	["Add an extra text to this frame and edit it below."] = "Diesem Rahmen einen zusätzlichen Text hinzufügen und ihn unten bearbeiten.",
	["Add each sale above: the item, who bought it and for how much gold."] = "Tragt oben jeden Verkauf ein: den Gegenstand, wer ihn gekauft hat und für wie viel Gold.",
	["Add friend"] = "Freund hinzufügen",
	["Add friends after combat."] = "Freunde nach dem Kampf hinzufügen.",
	["Add missing macros"] = "Fehlende Makros hinzufügen",
	["Add note"] = "Notiz hinzufügen",
	["Add note and mark entries to a player's right-click menu."] = "Einträge für Notiz und Markierung zum Rechtsklickmenü eines Spielers hinzufügen.",
	["Add one with /way 45 63 or Ctrl+right-click on the world map."] = "Fügt einen mit /way 45 63 oder Strg+Rechtsklick auf die Weltkarte hinzu.",
	["Add sale"] = "Verkauf hinzufügen",
	["Add text"] = "Text hinzufügen",
	["Add the same checks to the world map's own filter menu. Needs the World Map element switch (Blizzard UI page)."] = "Dieselben Häkchen auch dem eigenen Filtermenü der Weltkarte hinzufügen. Braucht den Elementschalter Weltkarte (Seite Blizzard-UI).",
	["Add the tag under a new quest's link, and tint new quests' titles where a tooltip lists them (quest mobs). Follows the Tooltips Blizzard UI setting."] = "Den Tag unter den Link einer neuen Quest setzen und die Titel neuer Quests einfärben, wo ein Tooltip sie auflistet (Questgegner). Folgt der Blizzard-UI-Einstellung Tooltips.",
	["Add this ready-made rule at the end of the list. Change it like any other rule."] = "Diese fertige Regel am Ende der Liste hinzufügen. Ändert sie wie jede andere Regel.",
	["Add to bench"] = "Auf die Ersatzbank setzen",
	["Add to priority list"] = "Zur Prioritätsliste hinzufügen",
	["Add to the ledger"] = "Ins Kassenbuch eintragen",
	["Add to this menu"] = "Zu diesem Menü hinzufügen",
	["Add your current standing with the faction."] = "Euren aktuellen Ruf bei der Fraktion hinzufügen.",
	["Added by a plugin through the unit frames."] = "Von einem Plugin über die Einheitenrahmen hinzugefügt.",
	["Addon button bin"] = "Addon-Knopfsammler",
	["Addon buttons"] = "Addon-Schaltflächen",
	["Addon buttons per row in the bin."] = "Addon-Schaltflächen pro Reihe im Sammler.",
	["Addon compartment"] = "Addon-Fach",
	["Addon menu entry"] = "Eintrag im Addon-Menü",
	["Address book"] = "Adressbuch",
	["Address book button"] = "Schaltfläche Adressbuch",
	["Adds Guild invite when you can invite the player, and Who to look up their character by name."] = "Fügt den Eintrag In Gilde einladen hinzu, wenn Ihr den Spieler einladen könnt, und den Eintrag Wer, um seinen Charakter nach Namen nachzuschlagen.",
	["Adds Planner, Import build and, for classes with suggested paths, Recommended build to Blizzard's talent page. They only save plans; nothing is learned."] = "Fügt Blizzards Talentseite Planer, Build-Import und für Klassen mit vorgeschlagenen Pfaden Empfohlener Build hinzu. Sie speichern nur Pläne; nichts wird erlernt.",
	["Adds a Share mine button that sends your lowest durability and EldoUI version to the group once per ready check, for their report. Nothing is sent without your click."] = "Fügt eine Schaltfläche „Meine teilen“ hinzu, die Eure niedrigste Haltbarkeit und EldoUI-Version einmal pro Bereitschaftscheck für deren Bericht an die Gruppe sendet. Ohne Euren Klick wird nichts gesendet.",
	["Adds a ready-made rule at the end of the list: enemy totems show as an orange name above other plates. It stands down in dungeons and raids."] = "Fügt am Ende der Liste eine fertige Regel hinzu: Feindliche Totems erscheinen als orangefarbener Name über anderen Plaketten. Sie pausiert in Dungeons und Schlachtzügen.",
	["Adds a ready-made rule at the end of the list: your group's totems show as a small name. Needs friendly minion plates (Game settings tab); stands down in instances."] = "Fügt am Ende der Liste eine fertige Regel hinzu: Die Totems Eurer Gruppe erscheinen als kleiner Name. Braucht Plaketten für freundliche Diener (Reiter Spieleinstellungen); pausiert in Instanzen.",
	["Adds damage or healing per second and per mana under a spell's tooltip, read from the tooltip's own text. English and German clients."] = "Fügt unter dem Tooltip eines Zaubers Schaden oder Heilung pro Sekunde und pro Mana hinzu, gelesen aus dem Text des Tooltips selbst. Englische und deutsche Clients.",
	["Adds missing reagents for the selected number of crafts to the Profession Planner shopping list. Nothing is bought or crafted."] = "Setzt die fehlenden Reagenzien für die gewählte Anzahl an Herstellungen auf die Einkaufsliste des Berufsplaners. Nichts wird gekauft oder hergestellt.",
	["Adds the SR and TMB lines to item tooltips. The Tooltip module's section list can also turn them off."] = "Fügt Gegenstandstooltips die Zeilen SR und TMB hinzu. Die Abschnittsliste des Tooltip-Moduls kann sie ebenfalls ausschalten.",
	["Adds the character macro EldoUI Rares that presses the targeting key, to put on an action bar. Your own macros are never changed."] = "Fügt das Charaktermakro EldoUI Rares hinzu, das die Zieltaste drückt, zum Ablegen auf einer Aktionsleiste. Eure eigenen Makros werden nie verändert.",
	["Adds the item, the buyer and the price to the ledger."] = "Trägt Gegenstand, Käufer und Preis ins Kassenbuch ein.",
	["Adds the items' worth at your saved auction prices (needs the Auction House module). \"+?\" means some items have no saved price."] = "Fügt den Wert der Gegenstände nach Euren gespeicherten Auktionspreisen hinzu (braucht das Modul Auktionshaus). „+?“ bedeutet, dass einige Gegenstände keinen gespeicherten Preis haben.",
	["Adds the line under each group loot roll, on EldoUI's roll bars and on Blizzard's roll frames."] = "Fügt die Zeile unter jedem Gruppenwurf hinzu, auf EldoUIs Würfelleisten und auf Blizzards Würfelfenstern.",
	["Adds the realm after characters from another realm."] = "Fügt bei Charakteren von einem anderen Realm den Realm an.",
	["Adds the spell ID to spell tooltips in the spellbook and talents. The Tooltip module's own Spell ID line takes over when it shows one."] = "Fügt Zaubertooltips im Zauberbuch und bei den Talenten die Zauber-ID hinzu. Die eigene Zeile Zauber-ID des Tooltip-Moduls übernimmt, wenn sie eine anzeigt.",
	["Adds the zone you are in now to the quiet zones. The card menu offers it for the rare's zone too."] = "Fügt das Gebiet, in dem Ihr gerade seid, zu den stillen Gebieten hinzu. Das Kartenmenü bietet das auch für das Gebiet des raren Gegners an.",
	["Adds this player to your WoW friends list."] = "Fügt diesen Spieler Eurer WoW-Freundesliste hinzu.",
	["Adds this recipe to the Profession Planner's shopping list with a number of crafts. Nothing is crafted."] = "Setzt dieses Rezept mit einer Anzahl an Herstellungen auf die Einkaufsliste des Berufsplaners. Nichts wird hergestellt.",
	["Adds three sample rows to the feed (/eui notify test pings)."] = "Fügt dem Ticker drei Beispielzeilen hinzu (/eui notify test pings).",
	["Advanced"] = "Erweitert",
	["Advanced settings"] = "Erweiterte Einstellungen",
	["Adventure guide"] = "Abenteuerführer",
	["Adventurer"] = "Abenteurer",
	["Affordable only"] = "Nur bezahlbare",
	["After a ready check, one line in chat with who wasn't ready or didn't answer."] = "Nach einem Bereitschaftscheck eine Chatzeile, wer nicht bereit war oder nicht geantwortet hat.",
	["After a ready check, one line in your own chat window with who is ready, who said not ready, who never answered and who is offline. Only you see it; Post to group sends it."] = "Nach einem Bereitschaftscheck eine Zeile in Eurem eigenen Chatfenster: wer bereit ist, wer nicht bereit gemeldet hat, wer nie geantwortet hat und wer offline ist. Nur Ihr seht sie; An Gruppe posten sendet sie.",
	["After a trade that moved gold, one line in chat (only you see it), such as \"Gave 5g to Name\", with a link to the log."] = "Nach einem Handel, bei dem Gold bewegt wurde, eine Chatzeile (nur für Euch sichtbar), etwa „5g an Name gegeben“, mit einem Link zum Protokoll.",
	["After arriving or removing one, the arrow points at the closest waypoint left."] = "Nach dem Erreichen oder Entfernen eines Wegpunkts zeigt der Pfeil auf den nächstgelegenen verbleibenden.",
	["After combat."] = "Nach dem Kampf.",
	["After the helper takes one quest from an NPC, their other quests wait until you talk to them again."] = "Nachdem der Helfer eine Quest von einem NSC angenommen hat, warten dessen andere Quests, bis Ihr erneut mit ihm sprecht.",
	["After you release your spirit, a waypoint on your corpse (the arrow points there). It goes away when you are alive again."] = "Nachdem Ihr Euren Geist freigelassen habt, ein Wegpunkt auf Eurer Leiche (der Pfeil zeigt dorthin). Er verschwindet, sobald Ihr wieder lebt.",
	["After you zoom with the mouse wheel, the map zooms back out after this many seconds. 0 keeps your zoom."] = "Nach dem Zoomen mit dem Mausrad zoomt die Karte nach so vielen Sekunden wieder heraus. 0 behält Euren Zoom.",
	["Air"] = "Luft",
	["Alert Lane"] = "Warnspalte",
	["Alert again after"] = "Erneut warnen nach",
	["Alert again for all %d ignored rares?"] = "Wieder für alle %d ignorierten raren Gegner warnen?",
	["Alert again for every rare you chose to ignore (card menu: Ignore this rare)."] = "Wieder für jeden raren Gegner warnen, den Ihr ignorieren wolltet (Kartenmenü: Diesen raren Gegner ignorieren).",
	["Alert lane"] = "Warnspalte",
	["Alert outdoors when you see an opposing player after three confirmed kills in either direction. Off by default."] = "Warnt im Freien, wenn Ihr einen gegnerischen Spieler seht, den Ihr dreimal bestätigt getötet habt oder der Euch dreimal getötet hat. Standardmäßig aus.",
	["Alerts"] = "Hinweise",
	["Alerts and Banners"] = "Hinweise und Banner",
	["Alerts grow up from their mover, for a lane near the bottom of the screen."] = "Warnungen wachsen von ihrem Rahmen nach oben, für eine Spalte nahe dem unteren Bildschirmrand.",
	["Alerts growing down, normal sizes and times."] = "Warnungen wachsen nach unten, normale Größen und Zeiten.",
	["Alerts sit on the \"Alert Lane\" mover, level-up toasts and boss banners on \"Banners\", Battle.net toasts and the GM ticket on \"Battle.net Toasts\"."] = "Warnungen sitzen auf dem Rahmen „Warnspalte“, Stufenaufstiegs-Hinweise und Bossbanner auf „Banner“, Battle.net-Hinweise und das GM-Ticket auf „Battle.net-Hinweise“.",
	["Alias removed."] = "Alias entfernt.",
	["Alias, e.g. Healer friend"] = "Alias, z. B. Heilerfreund",
	["Aliases"] = "Aliase",
	["Aliases in place of real character names on EldoUI's frames, tooltips and chat while you stream or record."] = "Aliase statt echter Charakternamen auf EldoUIs Rahmen, Tooltips und im Chat, während Ihr streamt oder aufnehmt.",
	["Alignment"] = "Ausrichtung",
	["All buttons in one column."] = "Alle Schaltflächen in einer Spalte.",
	["All buttons in one row, bags above them."] = "Alle Schaltflächen in einer Reihe, Taschen darüber.",
	["All buttons in one row."] = "Alle Schaltflächen in einer Reihe.",
	["All categories"] = "Alle Kategorien",
	["All channels"] = "Alle Kanäle",
	["All eight and clear"] = "Alle acht und Entfernen",
	["All game settings"] = "Alle Spieleinstellungen",
	["All guild ranks"] = "Alle Gildenränge",
	["All items"] = "Alle Gegenstände",
	["All later levels"] = "Alle späteren Stufen",
	["All other lines."] = "Alle anderen Zeilen.",
	["All settings"] = "Alle Einstellungen",
	["All slots"] = "Alle Plätze",
	["All social windows"] = "Alle sozialen Fenster",
	["All tooltips"] = "Alle Tooltips",
	["All totems"] = "Alle Totems",
	["All values in one line; off gives each value its own row."] = "Alle Werte in einer Zeile; aus gibt jedem Wert eine eigene Zeile.",
	["All zone text, or only the subzone (the zone name still shows when you enter a new zone)."] = "Der gesamte Gebietstext oder nur das Untergebiet (der Gebietsname erscheint weiterhin, wenn Ihr ein neues Gebiet betretet).",
	["Alliance, Horde or free-for-all badge by the name."] = "Abzeichen für Allianz, Horde oder Jeder gegen jeden beim Namen.",
	["Allow posting"] = "Posten erlauben",
	["Allow this demon. With it off, having it out counts as the wrong demon; the first allowed demon is the one a click summons."] = "Diesen Dämon erlauben. Ist es aus, zählt er als falscher Dämon; der erste erlaubte Dämon ist der, den ein Klick beschwört.",
	["Already done"] = "Bereits erledigt",
	["Already known"] = "Bereits bekannt",
	["Also /eui in chat."] = "Auch /eui im Chat.",
	["Also alert for a rare that is already dead."] = "Auch bei einem raren Gegner warnen, der schon tot ist.",
	["Also alert for world bosses such as Azuregos."] = "Auch bei Weltbossen wie Azuregos warnen.",
	["Also alert inside instances. Most names are hidden there, so few rares show."] = "Auch in Instanzen warnen. Dort sind die meisten Namen verborgen, daher erscheinen nur wenige rare Gegner.",
	["Also alert while you are on a flight path."] = "Auch warnen, während Ihr auf einer Flugroute seid.",
	["Also counts the reagent on your other characters, from the Bags module's inventory list."] = "Zählt das Reagenz auch auf Euren anderen Charakteren, aus der Inventarliste des Moduls Taschen.",
	["Also debug and GM settings, and the ones the game locks or shows read-only."] = "Auch Debug- und GM-Einstellungen sowie solche, die das Spiel sperrt oder nur lesbar zeigt.",
	["Also from nameplates"] = "Auch von Namensplaketten",
	["Also in combat"] = "Auch im Kampf",
	["Also in parties"] = "Auch in Gruppen",
	["Also list skills you have already learned."] = "Auch bereits erlernte Fertigkeiten auflisten.",
	["Also offer the item of a quest that is ready to turn in."] = "Auch den Gegenstand einer Quest anbieten, die abgabebereit ist.",
	["Also on continent maps"] = "Auch auf Kontinentkarten",
	["Also on the focus cast bar"] = "Auch auf der Fokus-Zauberleiste",
	["Also opens the window with /wt, unless another addon uses /wt."] = "Öffnet das Fenster auch mit /wt, außer ein anderes Addon nutzt /wt.",
	["Also remember casts of mobs that only show a nameplate."] = "Auch Zauber von Gegnern merken, die nur eine Namensplakette zeigen.",
	["Also seen here"] = "Auch hier gesehen",
	["Also set the game's own map pin and tracking on the waypoint the arrow points at."] = "Auch die eigene Kartenmarkierung und Verfolgung des Spiels auf den Wegpunkt setzen, auf den der Pfeil zeigt.",
	["Also show flight masters you have not talked to, grayed, so you can go and learn them."] = "Auch Flugmeister zeigen, mit denen Ihr noch nicht gesprochen habt, ausgegraut, damit Ihr hingehen und die Route lernen könnt.",
	["Also show this note on the continent map (Kalimdor, Eastern Kingdoms)."] = "Diese Notiz auch auf der Kontinentkarte zeigen (Kalimdor, Östliche Königreiche).",
	["Also show while"] = "Auch zeigen, während",
	["Also sliders for effects, music, ambience and dialog."] = "Auch Regler für Effekte, Musik, Umgebung und Dialog.",
	["Also turns off the game's full-screen glow setting. On by default when Disable screen effects is on."] = "Schaltet auch die Spieleinstellung für das Vollbild-Leuchten aus. Standardmäßig an, solange Bildschirmeffekte deaktivieren eingeschaltet ist.",
	["Also watch for these names"] = "Auch auf diese Namen achten",
	["Alt+Shift"] = "Alt+Umschalt",
	["Alt+Shift-click attaches every stack of that item."] = "Alt+Umschaltklick hängt jeden Stapel dieses Gegenstands an.",
	["Alt+right-click adds a note"] = "Alt+Rechtsklick fügt eine Notiz hinzu",
	["Alt-click a bag item to attach it"] = "Alt-Klick auf einen Taschengegenstand hängt ihn an",
	["Alt-click a vendor item to add it"] = "Alt-Klick auf einen Händlergegenstand fügt ihn hinzu",
	["Alt-click an item in the merchant window to put it on the restock list with one stack."] = "Alt-Klick auf einen Gegenstand im Händlerfenster setzt ihn mit einem Stapel auf die Auffüllliste.",
	["Always compare items"] = "Gegenstände immer vergleichen",
	["Always gray"] = "Immer grau",
	["Always sell"] = "Immer verkaufen",
	["Always sharpen"] = "Immer schärfen",
	["Always show plates"] = "Plaketten immer anzeigen",
	["Always the faction"] = "Immer die Fraktion",
	["Always, or only while the mouse is over the bars."] = "Immer oder nur, solange die Maus über den Leisten ist.",
	["Ambience"] = "Umgebung",
	["Ammo (hunters)"] = "Munition (Jäger)",
	["Ammo without a quiver"] = "Munition ohne Köcher",
	["An \"Abilities seen\" row on a hostile mob's tooltip, from what the log remembered. Hold Shift to see all of them."] = "Eine Zeile „Gesehene Fähigkeiten“ im Tooltip eines feindlichen Gegners, aus dem, was das Protokoll gespeichert hat. Haltet Umschalt, um alle zu sehen.",
	["An EldoUI button in the game menu: click opens the EldoUI settings, right-click starts move mode. With Blizzard UI > Game menu (Esc) on, it sits right above AddOns."] = "Eine EldoUI-Schaltfläche im Spielmenü: Klick öffnet die EldoUI-Einstellungen, Rechtsklick startet den Verschiebemodus. Ist Blizzard-UI > Spielmenü (Esc) an, sitzt sie direkt über AddOns.",
	["An alert card when your shield is running out or gone. The game doesn't tell addons about your auras in combat, so this one waits until the fight ends."] = "Eine Hinweiskarte, wenn Euer Schild ausläuft oder weg ist. Das Spiel verrät Addons im Kampf nichts über Eure Auren, daher wartet diese bis zum Ende des Kampfes.",
	["An anvil when your most worn item reaches Worn gear on the General page (yellow), red once it is low, so you repair in time. Shown in rest areas too."] = "Ein Amboss, wenn Euer am stärksten abgenutzter Gegenstand die Schwelle „Abgenutzt ab“ auf der Seite Allgemein erreicht (gelb), rot, sobald sie niedrig ist, damit Ihr rechtzeitig repariert. Auch in Erholungsgebieten zu sehen.",
	["An arrow that points at the current waypoint, with its distance and arrival time."] = "Ein Pfeil, der auf den aktuellen Wegpunkt zeigt, mit Entfernung und Ankunftszeit.",
	["An entry in the addon compartment menu by the minimap that opens the window."] = "Ein Eintrag im Addon-Fach an der Minikarte, der das Fenster öffnet.",
	["An icon over the object or character you would interact with next (game setting SoftTargetIconInteract)."] = "Ein Symbol über dem Objekt oder Charakter, mit dem Ihr als Nächstes interagieren würdet (Spieleinstellung SoftTargetIconInteract).",
	["An icon when this unit is in another phase."] = "Ein Symbol, wenn diese Einheit in einer anderen Phase ist.",
	["An icon while a resurrection is on its way to this unit."] = "Ein Symbol, solange eine Wiederbelebung zu dieser Einheit unterwegs ist.",
	["An item's enchant adds its plain stats (+7 Agility) to its score. Off compares items bare, as a new item would be before you enchant it. Procs are never counted."] = "Die Verzauberung eines Gegenstands fügt seiner Punktzahl ihre einfachen Werte (+7 Beweglichkeit) hinzu. Aus vergleicht Gegenstände ohne Verzauberung, so wie ein neuer Gegenstand wäre, bevor Ihr ihn verzaubert. Procs werden nie gezählt.",
	["An objective's count (3/8) sits at the right end of its line in the accent color. Lines too long for both keep Blizzard's text."] = "Der Zähler eines Questziels (3/8) steht in der Akzentfarbe am rechten Ende seiner Zeile. Zeilen, die für beides zu lang sind, behalten Blizzards Text.",
	["An over-the-shoulder view. It uses the game's experimental camera settings: the game asks you once to confirm them, and Disable there turns ActionCam off. Off puts your own values back."] = "Eine Ansicht über die Schulter. Sie nutzt die experimentellen Kameraeinstellungen des Spiels: Das Spiel bittet Euch einmal, sie zu bestätigen, und Deaktivieren dort schaltet ActionCam aus. Aus stellt Eure eigenen Werte wieder her.",
	["An upright column of large buttons."] = "Eine aufrechte Spalte großer Schaltflächen.",
	["Animation"] = "Animation",
	["Ankh %d"] = "Ankh %d",
	["Anonymous"] = "Anonym",
	["Another action in progress"] = "Eine andere Aktion ist im Gange",
	["Another addon gathers the minimap buttons: %s."] = "Ein anderes Addon sammelt die Minikartenschaltflächen: %s.",
	["Another character, or Best of all: the best time per level over all your other characters."] = "Ein anderer Charakter oder Beste von allen: die beste Zeit pro Stufe über alle Eure anderen Charaktere.",
	["Answers hop requests from your guild and, while you are in the layer network, from its players. Each request shows a card: Invite or Not now. Never in combat or in an instance."] = "Beantwortet Wechselanfragen aus Eurer Gilde und, solange Ihr im Layer-Netzwerk seid, von dessen Spielern. Jede Anfrage zeigt eine Karte: Einladen oder Jetzt nicht. Nie im Kampf oder in einer Instanz.",
	["Answers in chat"] = "Antworten im Chat",
	["Any alert type not listed here."] = "Jede Art von Warnung, die hier nicht aufgeführt ist.",
	["Any buff by spell ID: the reminder shows while no rank of it is on you. A tooltip addon or database site shows spell IDs."] = "Jeder Stärkungszauber per Zauber-ID: Die Erinnerung erscheint, solange kein Rang davon auf Euch liegt. Ein Tooltip-Addon oder eine Datenbankseite zeigt Zauber-IDs.",
	["Any number of extra texts made of tags, placed anywhere on the frame."] = "Beliebig viele zusätzliche Texte aus Tags, überall auf dem Rahmen platziert.",
	["Any paladin blessing, single or greater."] = "Jeder Paladinsegen, einfach oder groß.",
	["Any quality"] = "Jede Qualität",
	["Appearance unavailable"] = "Aussehen nicht verfügbar",
	["Apply the nameplate style your layout names (Layouts page). Your other settings stay."] = "Den Namensplakettenstil anwenden, den Euer Layout nennt (Seite Layouts). Eure anderen Einstellungen bleiben.",
	["Arcane Intellect or Arcane Brilliance."] = "Arkane Intelligenz oder Arkane Brillanz.",
	["Area %s"] = "Gebiet %s",
	["Arenas"] = "Arenen",
	["Armory link"] = "Armory-Link",
	["Arrival distance"] = "Ankunftsentfernung",
	["Arrival only"] = "Nur Ankunft",
	["Arrival sound"] = "Ankunftston",
	["Arrival time"] = "Ankunftszeit",
	["Arrived"] = "Angekommen",
	["Arrived at %s."] = "Angekommen bei %s.",
	["Arriving"] = "Ankunft",
	["Arrow"] = "Pfeil",
	["Arrow in the theme's accent color instead of heading colors."] = "Pfeil in der Akzentfarbe des Themas statt in Richtungsfarben.",
	["Arrow size"] = "Pfeilgröße",
	["Arrows"] = "Pfeile",
	["Arrows and the best-choice mark on quest rewards."] = "Pfeile und die Markierung für die beste Wahl bei Questbelohnungen.",
	["Arrows on icons"] = "Pfeile auf Symbolen",
	["Arrows on icons and quest rewards, nothing in tooltips."] = "Pfeile auf Symbolen und Questbelohnungen, nichts in Tooltips.",
	["Arrows on upgrade rewards and a green outline on the best choice in the quest dialogs, and in the quest log while World map and quest log has Improve on."] = "Pfeile auf Belohnungen, die eine Verbesserung sind, und eine grüne Kontur um die beste Wahl in den Questdialogen sowie im Questlog, solange bei Weltkarte und Questlog Verbessern an ist.",
	["Art style"] = "Grafikstil",
	["Art style follows EldoUI's art style. Game icons always use the game's map icons. Dots are small dots in the loot's quality color. Loot icons show the best drop."] = "Grafikstil folgt dem Grafikstil von EldoUI. Spielsymbole nutzen immer die Kartensymbole des Spiels. Punkte sind kleine Punkte in der Qualitätsfarbe der Beute. Beutesymbole zeigen die beste Beute.",
	["As a new loadout"] = "Als neue Zusammenstellung",
	["As leader or assist (any party)"] = "Als Leiter oder Assistent (jede Gruppe)",
	["As on the Effects tab"] = "Wie im Reiter Effekte",
	["As the UI"] = "Wie die Oberfläche",
	["As worn"] = "Wie getragen",
	["Ask before a new tree"] = "Vor einem neuen Baum fragen",
	["Ask before buying"] = "Vor dem Kauf fragen",
	["Asked %s to invite you."] = "%s um eine Einladung gebeten.",
	["Asked %s to share %s."] = "%s gebeten, %s zu teilen.",
	["Asking for a hop..."] = "Bitte um Layerwechsel...",
	["Asks everyone in the group whether they are ready."] = "Fragt alle in der Gruppe, ob sie bereit sind.",
	["Asks everyone to confirm tank, healer or damage."] = "Bittet alle, Tank, Heiler oder Schaden zu bestätigen.",
	["Asks everyone to confirm their role."] = "Bittet alle, ihre Rolle zu bestätigen.",
	["Asks first, then you leave the group."] = "Fragt zuerst, dann verlasst Ihr die Gruppe.",
	["Asks once more when Learn would put your first point into a tree you have no points in."] = "Fragt noch einmal nach, wenn Erlernen Euren ersten Punkt in einen Baum setzen würde, in dem Ihr noch keine Punkte habt.",
	["Asks the game who this player is: level, race, class, guild and zone show in chat."] = "Fragt das Spiel, wer dieser Spieler ist: Stufe, Volk, Klasse, Gilde und Gebiet erscheinen im Chat.",
	["Asks the group whether everyone is ready."] = "Fragt die Gruppe, ob alle bereit sind.",
	["Asks to buy what's missing as soon as you open a vendor that sells it. Always asks first. Off by default."] = "Fragt, ob Ihr das Fehlende kaufen wollt, sobald Ihr einen Händler öffnet, der es verkauft. Fragt immer zuerst. Standardmäßig aus.",
	["Asks to fill your quiver as soon as you open a vendor that sells your ammo. Off by default."] = "Fragt, ob Euer Köcher gefüllt werden soll, sobald Ihr einen Händler öffnet, der Eure Munition verkauft. Standardmäßig aus.",
	["Aspect"] = "Aspekt",
	["At Never the card stays until you close it. It also stays while the mouse is over it."] = "Bei Nie bleibt die Karte, bis Ihr sie schließt. Sie bleibt auch, solange die Maus darüber ist.",
	["At a vendor that sells your equipped ammo: fills your quiver or ammo pouch, after the confirm question."] = "Bei einem Händler, der Eure angelegte Munition verkauft: füllt Euren Köcher oder Munitionsbeutel nach der Bestätigungsfrage.",
	["At login"] = "Beim Einloggen",
	["At login, a reminder when you have unspent points and your plan says where they go."] = "Beim Einloggen eine Erinnerung, wenn Ihr unverteilte Punkte habt und Euer Plan sagt, wohin sie gehören.",
	["At login, deletes saved messages older than this many days and removes empty conversations. Off keeps messages of any age."] = "Löscht beim Einloggen gespeicherte Nachrichten, die älter als so viele Tage sind, und entfernt leere Unterhaltungen. Aus behält Nachrichten jeden Alters.",
	["At login, when your bars are empty, your key bindings differ or your Edit Mode layout is gone, offers to review a restore. Nothing is restored without your click."] = "Wenn beim Einloggen Eure Leisten leer sind, Eure Tastenbelegungen abweichen oder Euer Layout des Bearbeitungsmodus fehlt, wird angeboten, eine Wiederherstellung zu prüfen. Ohne Euren Klick wird nichts wiederhergestellt.",
	["At most this many buffs."] = "Höchstens so viele Stärkungszauber.",
	["At most this many debuffs."] = "Höchstens so viele Schwächungszauber.",
	["At the cursor"] = "Am Mauszeiger",
	["At the cursor, use on release, medium icons, no labels."] = "Am Mauszeiger, beim Loslassen benutzen, mittlere Symbole, keine Beschriftungen.",
	["At the mouse"] = "An der Maus",
	["Attack"] = "Angriff",
	["Attacks every %s seconds"] = "Greift alle %s Sekunden an",
	["Attendance"] = "Anwesenheit",
	["Attendance options"] = "Anwesenheitsoptionen",
	["Attunement steps also show on continent maps."] = "Einstimmungsschritte erscheinen auch auf Kontinentkarten.",
	["Auction value"] = "Auktionswert",
	["Auction value: %s. Profit: %s"] = "Auktionswert: %s. Gewinn: %s",
	["Auctioneer"] = "Auktionator",
	["Auctioneers."] = "Auktionatoren.",
	["Auto self-cast"] = "Automatisch selbst wirken",
	["Auto: the icon of the macro's spell"] = "Automatisch: das Symbol des Makrozaubers",
	["Automatic"] = "Automatisch",
	["Automatic (follows preset)"] = "Automatisch (folgt der Vorlage)",
	["Automatic (the one you cast last)"] = "Automatisch (der zuletzt gewirkte)",
	["Automatic picks the theme that fits your layout preset, in its accent color. Panel draws the windows like every other EldoUI window, in your art style."] = "Automatisch wählt das Thema, das zur Vorlage Eures Layouts passt, in deren Akzentfarbe. Panel zeichnet die Fenster wie jedes andere EldoUI-Fenster, in Eurem Grafikstil.",
	["Automatic snapshots at login and logout (10 kept) and a restore offer when the game resets your setup."] = "Automatische Schnappschüsse beim Ein- und Ausloggen (10 werden behalten) und ein Angebot zur Wiederherstellung, wenn das Spiel Eure Einrichtung zurücksetzt.",
	["Automatic snapshots kept"] = "Behaltene automatische Schnappschüsse",
	["Available now"] = "Jetzt verfügbar",
	["Average"] = "Durchschnitt",
	["Avg. money"] = "Ø Geld",
	["Away"] = "Abwesend",
	["Back to Blizzard's size."] = "Zurück auf Blizzards Größe.",
	["Back to my class"] = "Zurück zu meiner Klasse",
	["Back to the saved macro."] = "Zurück zum gespeicherten Makro.",
	["Background color"] = "Hintergrundfarbe",
	["Backpack last"] = "Rucksack zuletzt",
	["Badge shows"] = "Abzeichen zeigt",
	["Badges"] = "Abzeichen",
	["Bag items the game marks in red (wrong armor type, level too high) get a faint red tint. EldoUI's own bag window follows its \"Red icon on items you can't use\" switch instead."] = "Taschengegenstände, die das Spiel rot markiert (falscher Rüstungstyp, Stufe zu hoch), bekommen eine schwache rote Tönung. Das eigene Taschenfenster von EldoUI folgt stattdessen seinem Schalter „Rotes Symbol auf Gegenständen, die Ihr nicht benutzen könnt“.",
	["Bankers"] = "Bankiers",
	["Banner"] = "Banner",
	["Banner scale"] = "Bannerskalierung",
	["Banners and Level-up"] = "Banner und Stufenaufstieg",
	["Bar %d · %d"] = "Leiste %d · %d",
	["Bar Snapshots"] = "Leistenschnappschüsse",
	["Bar color"] = "Leistenfarbe",
	["Bar color after a cast that went off."] = "Leistenfarbe nach einem erfolgreich gewirkten Zauber.",
	["Bar color after a failed or interrupted cast."] = "Leistenfarbe nach einem fehlgeschlagenen oder unterbrochenen Zauber.",
	["Bar color for elite mobs."] = "Leistenfarbe für Elitegegner.",
	["Bar color for rare elite mobs."] = "Leistenfarbe für rare Elitegegner.",
	["Bar color for rare mobs."] = "Leistenfarbe für rare Gegner.",
	["Bar color of lieutenants."] = "Leistenfarbe von Leutnants.",
	["Bar details window"] = "Fenster mit Leistendetails",
