	["Big grid"] = "Großes Raster",
	["Big talents, easy to read."] = "Große Talente, gut lesbar.",
	["Bigger bar with rested XP and the remaining XP always in view."] = "Größere Leiste mit Erholungsbonus und den restlichen EP stets im Blick.",
	["Bigger battlefield map at 85% opacity, top-center scores a bit larger."] = "Größere Schlachtfeldkarte mit 85 % Deckkraft, Punktestände oben in der Mitte etwas größer.",
