	["Bigger icons with their names, for menus you use now and then."] = "Größere Symbole mit Namen, für Menüs, die Ihr ab und zu nutzt.",
	["Bigger pins for big screens and ultrawides."] = "Größere Markierungen für große Bildschirme und Ultrawide.",
	["Bigger text and a wider tracker."] = "Größerer Text und eine breitere Verfolgung.",
	["Bigger text and rows, easy to read."] = "Größerer Text und größere Zeilen, gut lesbar.",
	["Bigger text for a high resolution or a far screen."] = "Größerer Text für eine hohe Auflösung oder einen weit entfernten Bildschirm.",
	["Bigger text in a mono font that reads well from a distance."] = "Größerer Text in einer Festbreitenschrift, die sich auch aus der Ferne gut liest.",
	["Bigger text in a taller info strip, easy to read."] = "Größerer Text in einem höheren Infostreifen, gut lesbar.",
	["Bigger text, easy to read from a distance."] = "Größerer Text, auch aus der Ferne gut lesbar.",
	["Bigger windows in the EldoUI theme; a new whisper opens its window (after the fight in combat)."] = "Größere Fenster im EldoUI-Thema; ein neues Flüstern öffnet sein Fenster (im Kampf erst danach).",
	["Bin button size"] = "Schaltflächengröße im Sammler",
