	["EldoUI look only: no extra buttons, strips or tags."] = "Nur die EldoUI-Optik: keine zusätzlichen Schaltflächen, Streifen oder Markierungen.",
	["EldoUI look, pop-ups a little bigger for high resolutions and easy reading. Window sizes are on the Move windows page."] = "EldoUI-Optik, Pop-ups etwas größer für hohe Auflösungen und leichtes Lesen. Fenstergrößen stehen auf der Seite Fenster verschieben.",
	["EldoUI look, pop-ups a little smaller for small screens. Window sizes are on the Move windows page."] = "EldoUI-Optik, Pop-ups etwas kleiner für kleine Bildschirme. Fenstergrößen stehen auf der Seite Fenster verschieben.",
	["EldoUI map notes"] = "EldoUI-Kartennotizen",
	["EldoUI note"] = "EldoUI-Notiz",
	["EldoUI panel, font and colors instead of the parchment art."] = "EldoUI-Panel, -Schrift und -Farben statt der Pergamentgrafik.",
	["EldoUI plates draw EldoUI's own bar, set per unit type in the next tabs. Blizzard plates keep their layout with EldoUI's texture and font."] = "EldoUI-Plaketten zeichnen EldoUIs eigene Leiste, pro Einheitentyp in den nächsten Reitern eingestellt. Blizzard-Plaketten behalten ihr Layout mit EldoUIs Textur und Schrift.",
	["EldoUI plates for this type"] = "EldoUI-Plaketten für diesen Typ",
	["EldoUI rules"] = "EldoUI-Regeln",
	["EldoUI sets how far the camera can zoom out. Off puts your own value back."] = "EldoUI legt fest, wie weit die Kamera herauszoomen kann. Aus stellt Euren eigenen Wert wieder her.",
	["EldoUI sets how fast the camera zooms with the mouse wheel. Off puts your own value back."] = "EldoUI legt fest, wie schnell die Kamera mit dem Mausrad zoomt. Aus stellt Euren eigenen Wert wieder her.",
	["EldoUI sets the screenshot settings below. Off puts your own values back."] = "EldoUI legt die Screenshot-Einstellungen unten fest. Aus stellt Eure eigenen Werte wieder her.",
	["EldoUI test pop-up. This is how pop-ups look and where they appear."] = "EldoUI-Test-Pop-up. So sehen Pop-ups aus, und hier erscheinen sie.",
	["EldoUI test raid warning"] = "EldoUI-Test: Schlachtzugswarnung",
	["EldoUI test: red error text"] = "EldoUI-Test: roter Fehlertext",
	["EldoUI test: the Alliance has taken the flag!"] = "EldoUI-Test: Die Allianz hat die Flagge erobert!",
	["EldoUI version"] = "EldoUI-Version",
	["EldoUI windows with Blizzard's own row colors, status icons and calendar day art."] = "EldoUI-Fenster mit Blizzards eigenen Zeilenfarben, Statussymbolen und Kalendertagsgrafiken.",
	["EldoUI's Open all takes gold and items from every letter, skips cash-on-delivery mail and stops before your bags are full."] = "EldoUIs Alle öffnen nimmt Gold und Gegenstände aus jedem Brief, überspringt Nachnahmepost und hört auf, bevor Eure Taschen voll sind.",
	["EldoUI's bars show by themselves. Blizzard's XP and reputation bars follow \"XP, reputation and honor bars\" in Blizzard UI."] = "EldoUIs Leisten werden eigenständig angezeigt. Blizzards EP- und Rufleisten folgen „EP-, Ruf- und Ehreleisten“ unter Blizzard-UI.",
	["EldoUI's clock text. Click opens the calendar, right-click the alarm and stopwatch."] = "EldoUIs Uhrtext. Klick öffnet den Kalender, Rechtsklick Wecker und Stoppuhr.",
	["EldoUI's extra rows sit in one block at the bottom of the tooltip; pick when each shows. Other addons' lines stay below it."] = "EldoUIs zusätzliche Zeilen stehen in einem Block am unteren Rand des Tooltips; wählt, wann jede angezeigt wird. Zeilen anderer Addons bleiben darunter.",
	["EldoUI's key sets in a strip under the window. Each opens a preview of every key before anything changes."] = "EldoUIs Tastensätze in einem Streifen unter dem Fenster. Jeder öffnet eine Vorschau aller Tasten, bevor sich etwas ändert.",
	["EldoUI's own minimap button: click for Move frames, right-click for keybind mode. It leads the addon button bin; while the bin is off it sits on the map's edge, and you can drag it around the map."] = "EldoUIs eigene Minikartenschaltfläche: Klick für Rahmen verschieben, Rechtsklick für den Tastenbelegungsmodus. Sie führt den Knopfsammler an; ist der Sammler aus, sitzt sie am Kartenrand, und Ihr könnt sie um die Karte herumziehen.",
	["EldoUI's own toasts for achievements, level-up, quest complete and more. Blizzard's version of each type you tick is hidden."] = "EldoUIs eigene Hinweise für Erfolge, Stufenaufstieg, abgeschlossene Quests und mehr. Blizzards Version jedes angehakten Typs wird ausgeblendet.",
	["EldoUI's sounds, the game's or a SharedMedia pack's."] = "EldoUIs Klänge, die des Spiels oder die eines SharedMedia-Pakets.",
	["EldoUI's unit frames, group frames and nameplates, and every [name] text tag."] = "EldoUIs Einheitenrahmen, Gruppenrahmen und Namensplaketten sowie jedes Text-Tag [name].",
	["EldoUI: %s"] = "EldoUI: %s",
	["EldoUI: %s is off while this addon is loaded, so the two never fight over the same frames."] = "EldoUI: %s ist aus, solange dieses Addon geladen ist, damit die beiden nie um dieselben Rahmen streiten.",
	["EldoUI: %s turns off while this addon is loaded, so the two never fight over the same frames."] = "EldoUI: %s schaltet sich aus, solange dieses Addon geladen ist, damit die beiden nie um dieselben Rahmen streiten.",
	["EldoUI: keeps %d module off"] = "EldoUI: hält %d Modul ausgeschaltet",
	["EldoUI: keeps %d modules off"] = "EldoUI: hält %d Module ausgeschaltet",
