	["Endgame"] = "Endgame",
	["Enemies that are not fighting fade to this opacity. 0 turns it off. Uses the game's combat flag only."] = "Gegner, die nicht kämpfen, verblassen auf diese Deckkraft. 0 schaltet es aus. Nutzt nur die Kampfmarkierung des Spiels.",
