	["Error text"] = "Fehlertext",
	["Esc > Options > AddOns > EldoUI is EldoUI's launcher page; it is always there."] = "Esc > Optionen > AddOns > EldoUI ist EldoUIs Startseite; sie ist immer da.",
	["Esc skips at once"] = "Esc überspringt sofort",
	["Esc skips at once; optional skipping of cutscenes you've seen."] = "Esc überspringt sofort; wahlweise werden bereits gesehene Zwischensequenzen übersprungen.",
	["Event"] = "Ereignis",
	["Event %s"] = "Ereignis %s",
	["Event button"] = "Ereignisschaltfläche",
	["Event windows"] = "Ereignisfenster",
	["Event: %s"] = "Ereignis: %s",
	["Events are quiet everywhere."] = "Ereignisse sind überall stumm.",
	["Every \"not enough\" power message."] = "Jede Ressourcenmeldung „Nicht genug“.",
	["Every action slot is already the same as in this snapshot."] = "Jeder Aktionsplatz entspricht bereits diesem Schnappschuss.",
	["Every auto-attack number"] = "Zahl für jeden automatischen Angriff",
	["Every checked buff is up."] = "Jeder angehakte Stärkungszauber ist aktiv.",
