	["Flash the taskbar"] = "Taskleiste blinken lassen",
	["Flashes the game in the taskbar when a prompt appears, so you notice it while tabbed out."] = "Lässt das Spiel in der Taskleiste blinken, wenn eine Abfrage erscheint, damit Ihr sie auch bemerkt, während Ihr ausgetabbt seid.",
	["Flask"] = "Fläschchen",
