	["Flight Timer"] = "Flugtimer",
	["Flight master"] = "Flugmeister",
	["Flight masters"] = "Flugmeister",
	["Flight masters on the world map, from the game. The tooltip lists where each flies once you opened its flight map."] = "Flugmeister auf der Weltkarte, aus dem Spiel. Der Tooltip listet, wohin jeder fliegt, sobald Ihr seine Flugkarte geöffnet habt.",
	["Flight masters you don't know yet"] = "Flugmeister, die Ihr noch nicht kennt",
	["Flight masters, boats, zeppelins, the tram and portals also show on continent maps. Needs Transport Maps."] = "Flugmeister, Schiffe, Zeppeline, die Tiefenbahn und Portale erscheinen auch auf Kontinentkarten. Braucht Transportkarten.",
	["Flight masters, boats, zeppelins, the tram and portals on the map, shown with the other EldoUI pins. Right-click a pin for a waypoint."] = "Flugmeister, Schiffe, Zeppeline, die Tiefenbahn und Portale auf der Karte, zusammen mit den anderen EldoUI-Markierungen. Rechtsklick auf eine Markierung setzt einen Wegpunkt.",
	["Flight masters, boats, zeppelins, the tram and portals on the world map, with where each one goes."] = "Flugmeister, Schiffe, Zeppeline, die Tiefenbahn und Portale auf der Weltkarte, jeweils mit ihrem Ziel.",
	["Flight masters. While Transport Maps shows flight masters, they come from there instead, so each shows once."] = "Flugmeister. Solange Transportkarten Flugmeister zeigt, kommen sie stattdessen von dort, damit jeder nur einmal erscheint.",
	["Flight path"] = "Flugroute",
	["Flight path not learned"] = "Flugroute nicht entdeckt",
