	["Flight timer"] = "Flugtimer",
	["Flight timer bar settings"] = "Einstellungen der Flugtimerleiste",
	["Flight times in tooltips"] = "Flugzeiten in Tooltips",
	["Flight view"] = "Flugansicht",
	["Flight view preview"] = "Vorschau der Flugansicht",
	["Floating combat text moves as it did in the original game instead of the modern way."] = "Schwebender Kampftext bewegt sich wie im ursprünglichen Spiel statt auf die moderne Art.",
	["Flying to"] = "Flug nach",
