	["Forget seen cutscenes"] = "Gesehene Zwischensequenzen vergessen",
	["Forget the ability log"] = "Fähigkeitenprotokoll vergessen",
	["Forget the group journal"] = "Gruppentagebuch vergessen",
	["Forget this rare"] = "Diesen raren Gegner vergessen",
	["Forget this session's sightings. Nothing is kept after you log out anyway."] = "Die Sichtungen dieser Sitzung vergessen. Nach dem Ausloggen wird ohnehin nichts behalten.",
	["Forgets every logged letter for this realm."] = "Vergisst jeden protokollierten Brief für diesen Realm.",
	["Fortitude"] = "Seelenstärke",
	["Four key bindings that each ping one spell or item through Blizzard's /pingspell and /pingitem. Bind them in the game's Key Bindings (AddOns > EldoUI Pings). One key press, one ping."] = "Vier Tastenbelegungen, die je einen Zauber oder Gegenstand über Blizzards /pingspell und /pingitem pingen. Belegt sie in der Tastenbelegung des Spiels (AddOns > EldoUI: Pings). Ein Tastendruck, ein Ping.",
