	["Friendly totems: small name"] = "Freundliche Totems: kleiner Name",
	["Friendly units as names only (class and reaction colors) with NPC titles, enemies as slim EldoUI plates that fade while not fighting. Effects: Subtle."] = "Freundliche Einheiten nur als Namen (Klassen- und Reaktionsfarben) mit NSC-Titeln, Gegner als schmale EldoUI-Plaketten, die verblassen, solange sie nicht kämpfen. Effekte: Dezent.",
	["Friendly units, with own colors for nameplates."] = "Freundliche Einheiten, mit eigenen Farben für Namensplaketten.",
	["Friends and Social"] = "Freunde und Soziales",
	["Friends, guild, calendar, group finder and PvP windows in the EldoUI look, with class colors, a friends search and movable windows."] = "Freundes-, Gilden-, Kalender-, Gruppensuche- und PvP-Fenster in der EldoUI-Optik, mit Klassenfarben, einer Freundessuche und verschiebbaren Fenstern.",
	["From %d to %d: %s"] = "Von %d bis %d: %s",
	["From My Adventure: when you first came to the zone and at what level, the time you spent there, and your runs in its dungeons."] = "Aus Mein Abenteuer: wann Ihr das Gebiet zum ersten Mal betreten habt und mit welcher Stufe, die Zeit, die Ihr dort verbracht habt, und Eure Durchläufe in seinen Dungeons.",
	["From a class quest in %s"] = "Aus einer Klassenquest in %s",
	["From level 20, once you know a poison: a reminder when this hand has no poison or it runs low (the off hand only while it holds a weapon). Right-click the icon to pick the poison; a click puts it on."] = "Ab Stufe 20, sobald Ihr ein Gift kennt: eine Erinnerung, wenn diese Hand kein Gift hat oder es zur Neige geht (die Schildhand nur, solange sie eine Waffe hält). Rechtsklick auf das Symbol wählt das Gift; ein Klick trägt es auf.",
	["From the position"] = "Nach Position",
	["Frost resistance"] = "Frostwiderstand",
	["Full offset from"] = "Voller Versatz ab",
	["Fully shown while this unit casts (for the player: while you cast)."] = "Voll sichtbar, während diese Einheit zaubert (beim Spieler: während Ihr zaubert).",
	["Fully shown while you have a focus target."] = "Voll sichtbar, während Ihr ein Fokusziel habt.",
	["Fully shown while you rest in an inn or city."] = "Voll sichtbar, während Ihr in einem Gasthaus oder einer Stadt rastet.",
	["GDKP %s: pot %s, %d players, %s each"] = "GDKP %s: Topf %s, %d Spieler, je %s",
	["GDKP Ledger"] = "GDKP-Kassenbuch",
	["GDKP ledger"] = "GDKP-Kassenbuch",
	["GDKP ledger: %s"] = "GDKP-Kassenbuch: %s",
	["Gains as score points instead of percent, for tuning scales."] = "Zugewinne als Wertungspunkte statt in Prozent, zum Feinabstimmen von Gewichtungen.",
	["Gains below this are not marked."] = "Zugewinne darunter werden nicht markiert.",
	["Game Settings"] = "Spieleinstellungen",
	["Game icon"] = "Spielsymbol",
	["Game icons"] = "Spielsymbole",
	["Game menu, Settings, AddOn list, keybinds, macros and pop-ups in the EldoUI look, with a few safe extras."] = "Spielmenü, Einstellungen, AddOn-Liste, Tastenbelegungen, Makros und Pop-ups in der EldoUI-Optik, mit ein paar sicheren Extras.",
	["Game setting (now %s)"] = "Spieleinstellung (jetzt %s)",
	["Game settings change out of combat."] = "Spieleinstellungen ändern sich außerhalb des Kampfes.",
	["Game toast settings"] = "Einstellungen der Spielhinweise",
	["Gap"] = "Abstand",
	["Gap below the health bar"] = "Abstand unter der Gesundheitsleiste",
	["Gap between addon buttons."] = "Abstand zwischen Addon-Schaltflächen.",
	["Gap between alerts in the lane."] = "Abstand zwischen den Hinweisen in der Spur.",
	["Gap between bag buttons."] = "Abstand zwischen Taschenschaltflächen.",
	["Gap between bars"] = "Abstand zwischen Leisten",
	["Gap between buff icons."] = "Abstand zwischen den Symbolen der Stärkungszauber.",
	["Gap between buttons."] = "Abstand zwischen Schaltflächen.",
	["Gap between debuff icons."] = "Abstand zwischen den Symbolen der Schwächungszauber.",
	["Gap between entries (a ring grows with it)."] = "Abstand zwischen Einträgen (ein Ring wächst mit).",
	["Gap between icons or bars."] = "Abstand zwischen Symbolen oder Leisten.",
	["Gap between icons."] = "Abstand zwischen Symbolen.",
	["Gap between the frames of this group (boss 1-5, party pets, party targets)."] = "Abstand zwischen den Rahmen dieser Gruppe (Boss 1-5, Gruppenbegleiter, Gruppenziele).",
	["Gap to the Cooldown Manager"] = "Abstand zum Abklingzeitenmanager",
	["Gap under the minimap"] = "Abstand unter der Minikarte",
	["Gather every button again"] = "Alle Schaltflächen wieder sammeln",
	["Gathered by %s"] = "Gesammelt von %s",
	["Gatherer"] = "Sammler",
	["Gathering nodes also show on continent maps."] = "Vorkommen erscheinen auch auf Kontinentkarten.",
	["Gathering skill"] = "Sammelfertigkeit",
	["Gathering tracking"] = "Rohstoffsuche",
	["Gathers addon minimap buttons in a strip, on the side rail, or in a drawer behind one button. A button its addon hides stays hidden. Needs Replace for \"Minimap buttons\"."] = "Sammelt die Minikartenschaltflächen von Addons in einem Streifen, an der Seitenschiene oder in einer Schublade hinter einer Schaltfläche. Eine Schaltfläche, die ihr Addon ausblendet, bleibt ausgeblendet. Braucht Ersetzen für „Minikartenschaltflächen“.",
	["Gave %s to %s and received %s."] = "%s an %s gegeben und %s erhalten.",
	["Gave %s to %s."] = "%s an %s gegeben.",
	["Gear slots"] = "Ausrüstungsplätze",
	["Gear you can wear now: %s."] = "Ausrüstung, die Ihr jetzt tragen könnt: %s.",
	["Gems and enchants"] = "Edelsteine und Verzauberungen",
	["Gems and enchants count, so the score is what each item gives you right now."] = "Edelsteine und Verzauberungen zählen mit, sodass die Wertung zeigt, was jeder Gegenstand Euch gerade jetzt bringt.",
	["Gems in an item add their stats to its score; their sockets no longer count as empty. Off: every socket counts as empty, valued by the socket weights below."] = "Edelsteine in einem Gegenstand fügen ihre Werte seiner Wertung hinzu; ihre Sockel zählen nicht mehr als leer. Aus: Jeder Sockel zählt als leer und wird nach den Sockelgewichten unten bewertet.",
	["Give a group channel a window first."] = "Gebt zuerst einem Gruppenkanal ein Fenster.",
	["Give a group channel its own window. The messenger never posts by itself: a line goes out only when you press Enter in the window."] = "Gebt einem Gruppenkanal ein eigenes Fenster. Der Messenger postet nie von selbst: Eine Zeile geht nur hinaus, wenn Ihr im Fenster die Eingabetaste drückt.",
	["Give a quest ID, or open a quest first."] = "Gebt eine Quest-ID an oder öffnet zuerst eine Quest.",
	["Give coordinates, like /way 45.2 63.8 or /way Elwynn Forest 45 63 Goldshire."] = "Gebt Koordinaten an, etwa /way 45.2 63.8 oder /way Wald von Elwynn 45 63 Goldhain.",
	["Give the chosen snapshot a name, so it is easy to find in the list."] = "Gebt dem gewählten Schnappschuss einen Namen, damit er in der Liste leicht zu finden ist.",
	["Give the health bar the color below."] = "Der Gesundheitsleiste die Farbe unten geben.",
	["Give the name the color below."] = "Dem Namen die Farbe unten geben.",
	["Give the plate border the color below (the target highlight still wins)."] = "Dem Plakettenrand die Farbe unten geben (die Zielhervorhebung hat weiterhin Vorrang).",
	["Give the tooltip shadow its own strength and size. Off follows Frame shadows on Global settings > Textures."] = "Dem Tooltipschatten eine eigene Stärke und Größe geben. Aus folgt Rahmenschatten unter Globale Einstellungen > Texturen.",
	["Give this frame its own frame art. Like all frames uses the Unit-frame graphics row at the top of this tab. Frames lower than 40 pixels get a thin edge in place of the full border."] = "Diesem Rahmen eine eigene Rahmengrafik geben. Die Einstellung Wie alle Rahmen nutzt die Zeile Einheitenrahmen-Grafiken oben auf diesem Reiter. Rahmen unter 40 Pixel Höhe erhalten statt des vollen Rands eine dünne Kante.",
	["Gives every raid member assistant rights, or takes them back (raid leader). The border turns accent while it is on."] = "Gibt jedem Schlachtzugsmitglied Assistentenrechte oder nimmt sie wieder (Schlachtzugsleiter). Der Rand nimmt die Akzentfarbe an, solange es an ist.",
	["Gives every raid member assistant rights, or takes them back."] = "Gibt jedem Schlachtzugsmitglied Assistentenrechte oder nimmt sie wieder.",
	["Gives the active scale the name above."] = "Gibt der aktiven Gewichtung den Namen oben.",
	["Gives the plan another name."] = "Gibt dem Plan einen anderen Namen.",
	["Glass (see-through)"] = "Glas (durchscheinend)",
	["Glow (Glows page)"] = "Leuchten (Seite Leuchteffekte)",
	["Glow on a new item"] = "Leuchten bei neuem Gegenstand",
	["Glow when missing"] = "Leuchten, wenn fehlend",
	["Glow when targeted"] = "Leuchten, wenn im Ziel",
	["Glows round a unit frame (boss, focus, party pet ...) while that unit is your target."] = "Leuchtet um einen Einheitenrahmen (Boss, Fokus, Gruppenbegleiter ...), solange diese Einheit Euer Ziel ist.",
	["Gold \"New\""] = "Goldenes „Neu“",
	["Gold %s"] = "Gold %s",
	["Gold and honor reward alerts."] = "Hinweise zu Gold- und Ehrebelohnungen.",
	["Gold dragon for elites and bosses, silver for rare elites, a star for rares."] = "Goldener Drache für Elitegegner und Bosse, silberner für rare Elitegegner, ein Stern für rare Gegner.",
	["Gold dragon for elites and bosses, silver for rares."] = "Goldener Drache für Elitegegner und Bosse, silberner für rare Gegner.",
	["Gold line in chat"] = "Goldzeile im Chat",
	["Gold sent"] = "Gesendetes Gold",
	["Gold titles and a short \"New\" tag everywhere."] = "Goldene Titel und überall eine kurze Markierung „Neu“.",
	["Gold trade log"] = "Gold-Handelsprotokoll",
	["Graphics"] = "Grafik",
	["Graphics for this frame"] = "Grafik für diesen Rahmen",
	["Graphics quality"] = "Grafikqualität",
	["Gray out others'"] = "Fremde ausgrauen",
	["Gray weapons and armor that aren't bound stay in your bags, e.g. for transmog or selling to players."] = "Graue Waffen und Rüstungen, die nicht gebunden sind, bleiben in Euren Taschen, z. B. für Transmogrifikation oder den Verkauf an Spieler.",
	["Gray when dead or offline"] = "Grau, wenn tot oder offline",
	["Gray: the unexplored areas in gray, so they stand apart from the explored map. Map colors: the map's own colors, only fainter."] = "Grau: die unerkundeten Bereiche in Grau, damit sie sich von der erkundeten Karte abheben. Kartenfarben: die eigenen Farben der Karte, nur blasser.",
	["Grayed out"] = "Ausgegraut",
	["Grayed out: unknown spells, items you don't carry and entries on cooldown or out of mana are gray. Left out: spells you don't know and items you don't have are not in the menu at all."] = "Ausgegraut: Unbekannte Zauber, Gegenstände, die Ihr nicht dabeihabt, und Einträge mit Abklingzeit oder ohne Mana sind grau. Weggelassen: Zauber, die Ihr nicht kennt, und Gegenstände, die Ihr nicht habt, stehen gar nicht im Menü.",
	["Green border on upgrades"] = "Grüner Rand bei Verbesserungen",
	["Green when you face the waypoint, yellow when it is to your side, red when it is behind you. Off uses the accent color."] = "Grün, wenn Ihr zum Wegpunkt blickt, gelb, wenn er seitlich liegt, rot, wenn er hinter Euch ist. Aus nutzt die Akzentfarbe.",
	["Green: the first character was faster."] = "Grün: Der erste Charakter war schneller.",
	["Grid (cells)"] = "Raster (Zellen)",
	["Grid columns"] = "Rasterspalten",
	["Grid of tiles"] = "Kachelraster",
	["Grid rows"] = "Rasterzeilen",
	["Grid shows missing buffs as icons, Compact list as names, Summary only shows the counts without rows."] = "Raster zeigt fehlende Stärkungszauber als Symbole, Kompakte Liste als Namen, Zusammenfassung nur die Anzahlen ohne Zeilen.",
	["Grid with icons"] = "Raster mit Symbolen",
	["Group Finder Eye"] = "Auge der Gruppensuche",
	["Group finder eye"] = "Auge der Gruppensuche",
	["Group invites from people who aren't friends are declined. Off by default."] = "Gruppeneinladungen von Leuten, die keine Freunde sind, werden abgelehnt. Standardmäßig aus.",
	["Group journal"] = "Gruppentagebuch",
