	["Group summary"] = "Gruppenübersicht",
	["Group titles in the game's colors: green for available now, blue for upcoming, gray for known. Off uses your accent color."] = "Gruppentitel in den Farben des Spiels: grün für jetzt verfügbar, blau für demnächst, grau für bekannt. Aus nutzt Eure Akzentfarbe.",
