	["Icon picked. Save to keep it."] = "Symbol gewählt. Speichert, um es zu behalten.",
	["Icon placement"] = "Symbolplatzierung",
	["Icon side"] = "Symbolseite",
	["Icon size of the private auras."] = "Symbolgröße der privaten Auren.",
	["Icons and names, five before more, times seen in the Shift list, your standing on tokens."] = "Symbole und Namen, fünf vor weiteren, Sichtungen in der Umschalt-Liste, Euer Rufstand bei Marken.",
	["Icons for key spells, lit while they are off cooldown and dim while it runs. Off by default."] = "Symbole für wichtige Zauber, hell, solange sie keine Abklingzeit haben, und gedimmt, während sie läuft. Standardmäßig aus.",
	["Icons in one row before the next row starts."] = "Symbole in einer Reihe, bevor die nächste Reihe beginnt.",
	["Icons over things you can use"] = "Symbole über benutzbaren Dingen",
	["Icons with a countdown, or one timer bar per aura with its name."] = "Symbole mit Countdown oder eine Timerleiste pro Aura mit ihrem Namen.",
	["Icons, colored group titles, striped rows."] = "Symbole, farbige Gruppentitel, gestreifte Zeilen.",
	["Icons: the game's flight master art and a shape per kind. Colored dots: small dots. High contrast: large outlined shapes. Forever bronze: bronze shapes. Minimal: faint dots."] = "Symbole: die Flugmeistergrafik des Spiels und eine Form pro Art. Farbige Punkte: kleine Punkte. Hoher Kontrast: große Formen mit Kontur. Forever-Bronze: bronzene Formen. Minimal: blasse Punkte.",
	["If an invite appears, accept it in the game's popup."] = "Erscheint eine Einladung, nehmt sie im Fenster des Spiels an.",
	["If your gold is short, the repair happens when you get the money while the vendor is still open."] = "Reicht Euer Gold nicht, wird repariert, sobald Ihr das Geld habt, solange der Händler noch offen ist.",
