	["Keep group lines in the history too. Off keeps only whispers."] = "Gruppenzeilen ebenfalls im Verlauf behalten. Aus behält nur Flüsternachrichten.",
	["Keep rares you already did quiet"] = "Bereits erledigte rare Gegner stumm lassen",
	["Keep showing the reminders from before the fight while in combat, frozen (the game does not let addons read auras in combat, so they update when combat ends). Off: reminders hide in combat."] = "Die Erinnerungen von vor dem Kampf im Kampf eingefroren weiter anzeigen (das Spiel lässt Addons im Kampf keine Auren lesen, daher aktualisieren sie sich nach dem Kampf). Aus: Erinnerungen werden im Kampf ausgeblendet.",
	["Keep the book and talent art"] = "Buch- und Talentgrafik behalten",
	["Keep the game's totem timers next to the player frame anyway."] = "Die Totemtimer des Spiels trotzdem neben dem Spielerrahmen behalten.",
	["Keep the plate texture"] = "Plakettentextur behalten",
	["Keep unbound gray gear"] = "Ungebundene graue Ausrüstung behalten",
	["Keep your own name white"] = "Euren eigenen Namen weiß lassen",
	["Keeps Blizzard's book pages and talent tree background inside the skinned window."] = "Behält Blizzards Buchseiten und den Talentbaumhintergrund im Fenster mit Skin.",
	["Keeps the game's nameplates and gives them EldoUI's texture, border, font and extra icons."] = "Behält die Namensplaketten des Spiels und gibt ihnen Textur, Rand, Schrift und Zusatzsymbole von EldoUI.",
	["Keeps the raid roster after successful boss fights and when the raid forms or ends. Off by default."] = "Speichert die Mitgliederliste des Schlachtzugs nach erfolgreichen Bosskämpfen sowie beim Bilden und Auflösen des Schlachtzugs. Standardmäßig aus.",
	["Kept %d items your quests or recipes need."] = { one = "%d Gegenstand behalten, den Eure Quests oder Rezepte brauchen.", other = "%d Gegenstände behalten, die Eure Quests oder Rezepte brauchen." },
	["Kept %d trees. /reload or log out to write them to the SavedVariables file."] = { one = "%d Baum behalten. /reload oder ausloggen, um ihn in die SavedVariables-Datei zu schreiben.", other = "%d Bäume behalten. /reload oder ausloggen, um sie in die SavedVariables-Datei zu schreiben." },
