	["Learn first: %s"] = "Zuerst erlernen: %s",
	["Learn it on a %s: the planner offers it at login."] = "Erlernt ihn mit einem Charakter der Klasse %s: Der Planer bietet ihn beim Einloggen an.",
	["Learn next"] = "Nächsten erlernen",
	["Learn next and Learn to my level are the only buttons that spend points, and only when you click them. Plans are saved per character and talent group."] = "Nächsten erlernen und Bis zu meiner Stufe erlernen sind die einzigen Schaltflächen, die Punkte ausgeben, und nur, wenn Ihr sie anklickt. Pläne werden pro Charakter und Talentgruppe gespeichert.",
	["Learn spends one point on the next rank in your talent plan. EldoUI never spends a point unless you click, also not when you level up."] = "Erlernen gibt einen Punkt für den nächsten Rang in Eurem Talentplan aus. EldoUI gibt nie einen Punkt aus, ohne dass Ihr klickt, auch nicht beim Stufenaufstieg.",
	["Learn to my level"] = "Bis zu meiner Stufe erlernen",
	["Learn to my level (%d)"] = "Bis zu meiner Stufe erlernen (%d)",
	["Learned"] = "Erlernt",
