	["Learned by you"] = "Von Euch erlernt",
	["Learned flight time in tooltips"] = "Gelernte Flugzeit in Tooltips",
	["Learned: %s."] = "Erlernt: %s.",
	["Learning"] = "Erlernen",
	["Learns every rank your plan has up to your level, as far as your unspent points go, in one go."] = "Erlernt auf einmal jeden Rang Eures Plans bis zu Eurer Stufe, soweit Eure freien Punkte reichen.",
	["Learns how long each route takes from your own flights. While you fly, the route shows with its stops, the time left and the arrival time; Maps shows the times on the flight map."] = "Lernt aus Euren eigenen Flügen, wie lange jede Route dauert. Während Ihr fliegt, wird die Route mit ihren Zwischenstopps, der Restzeit und der Ankunftszeit angezeigt; Karten zeigt die Zeiten auf der Flugkarte.",
	["Learns the next rank of your plan. One click, one rank; nothing else is spent."] = "Erlernt den nächsten Rang Eures Plans. Ein Klick, ein Rang; sonst wird nichts ausgegeben.",
	["Learns this one rank now. Nothing else is spent."] = "Erlernt jetzt diesen einen Rang. Sonst wird nichts ausgegeben.",
	["Leave"] = "Verlassen",
	["Leave as it is"] = "Unverändert lassen",
	["Leave gray quests alone"] = "Graue Quests auslassen",
