	["Leave out ignored spells"] = "Ignorierte Zauber weglassen",
	["Leave out the herbalism, mining, skinning and fishing lines of professions you have not learned."] = "Die Zeilen zu Kräuterkunde, Bergbau, Kürschnerei und Angeln für Berufe weglassen, die Ihr nicht erlernt habt.",
	["Leave repeatable quests to you"] = "Wiederholbare Quests Euch überlassen",
