	["Leave them"] = "Belassen",
	["Leave your group?"] = "Eure Gruppe verlassen?",
	["Leaves the group after you confirm. There is no disband button: removing everyone at once would be many actions from one click."] = "Verlässt die Gruppe, nachdem Ihr bestätigt habt. Eine Schaltfläche zum Auflösen gibt es nicht: Alle auf einmal zu entfernen wären viele Aktionen aus einem Klick.",
