	["Panel height"] = "Panelhöhe",
	["Panel, buttons, set list and side preview."] = "Panel, Schaltflächen, Setliste und Seitenvorschau.",
	["Panel, flat rows, skill bar, filter and Train button."] = "Panel, flache Zeilen, Fertigkeitsleiste, Filter und Schaltfläche „Trainieren“.",
