	["Panel, tabs and buttons."] = "Panel, Reiter und Schaltflächen.",
	["Panels in your art style; whispers also stay in the main chat."] = "Panels in Eurem Grafikstil; Flüstern bleibt auch im Hauptchat.",
	["Parchment"] = "Pergament",
