	["Partner and values below the window, coin icons."] = "Partner und Werte unter dem Fenster, Münzsymbole.",
	["Partner only"] = "Nur Partner",
	["Party / raid"] = "Gruppe / Schlachtzug",
	["Party 1-4, Raid 1-40"] = "Gruppe 1-4, Schlachtzug 1-40",
	["Party Pets"] = "Gruppenbegleiter",
	["Party Quests"] = "Gruppenquests",
	["Party Quests panel off."] = "Panel Gruppenquests aus.",
	["Party Quests panel on. It shows while you are in a group."] = "Panel Gruppenquests an. Es erscheint, solange Ihr in einer Gruppe seid.",
	["Party Targets"] = "Gruppenziele",
	["Party and raid members already show in class colors on Blizzard's map. The zone tick in the quest log is part of Quality of Life."] = "Gruppen- und Schlachtzugsmitglieder erscheinen auf Blizzards Karte bereits in Klassenfarben. Das Gebietshäkchen im Questlog gehört zu Komfortfunktionen.",
	["Party and raid numbers for your group; other players keep their names."] = "Gruppen- und Schlachtzugsnummern für Eure Gruppe; andere Spieler behalten ihre Namen.",
	["Party and raid numbers, Adventurer for everyone else, on frames, tooltips and chat."] = "Gruppen- und Schlachtzugsnummern, „Abenteurer“ für alle anderen, auf Rahmen, Tooltips und im Chat.",
	["Party chat in its own window."] = "Gruppenchat in einem eigenen Fenster.",
	["Party numbers"] = "Gruppennummern",
	["Passive"] = "Passiv",
	["Paste"] = "Einfügen",
	["Paste a That's My BiS CSV or JSON export."] = "Fügt einen CSV- oder JSON-Export von That's My BiS ein.",
	["Paste a That's My BiS CSV or JSON export. Prio and wishlist rows are kept, received loot is left out."] = "Fügt einen CSV- oder JSON-Export von That's My BiS ein. Prio- und Wunschlistenzeilen bleiben erhalten, erhaltene Beute wird ausgelassen.",
	["Paste a scale"] = "Skala einfügen",
	["Paste a scale (Ctrl+V): EldoUI scale \"Name\": Strength=1, Agility=0.5 ... or a Pawn string ( Pawn: v1: \"Name\": ... ), and click Save."] = "Fügt eine Skala ein (Strg+V): EldoUI scale \"Name\": Strength=1, Agility=0.5 ... oder einen Pawn-String ( Pawn: v1: \"Name\": ... ) und klickt auf „Speichern“.",
	["Paste a softres.it CSV or JSON export."] = "Fügt einen CSV- oder JSON-Export von softres.it ein.",
	["Paste a softres.it CSV or JSON export. It replaces the soft reserves you imported before."] = "Fügt einen CSV- oder JSON-Export von softres.it ein. Er ersetzt die Soft-Reserves, die Ihr zuvor importiert habt.",
	["Paste a style filter string (Ctrl+V) and click Save."] = "Fügt einen Stilfilter-String ein (Strg+V) und klickt auf „Speichern“.",
	["Paste a style filter string. Its rules are added after yours; nothing is overwritten."] = "Fügt einen Stilfilter-String ein. Seine Regeln werden nach Euren angefügt; nichts wird überschrieben.",
	["Paste a talent calculator link, a talent string or a plan string to save it as a plan."] = "Fügt einen Talentrechner-Link, einen Talent-String oder einen Plan-String ein, um ihn als Plan zu speichern.",
	["Paste a talent calculator link, a talent string, a talent loadout string or an EldoUI plan string. You see what it holds before it is saved as a plan; nothing is learned."] = "Fügt einen Talentrechner-Link, einen Talent-String, einen Talentzusammenstellungs-String oder einen EldoUI-Plan-String ein. Ihr seht, was er enthält, bevor er als Plan gespeichert wird; nichts wird erlernt.",
	["Paste a talent plan string or a talent calculator link (Ctrl+V) and click Save. You see what it holds before it is saved; nothing is learned."] = "Fügt einen Talentplan-String oder einen Talentrechner-Link ein (Strg+V) und klickt auf „Speichern“. Ihr seht, was er enthält, bevor er gespeichert wird; nichts wird erlernt.",
	["Paste a talent plan string someone shared."] = "Fügt einen Talentplan-String ein, den jemand geteilt hat.",
	["Paste a totem loadout string someone shared."] = "Fügt einen Totemzusammenstellungs-String ein, den jemand geteilt hat.",
	["Paste an EldoUI or a Pawn scale string. It becomes a new custom scale."] = "Fügt einen Skalen-String von EldoUI oder Pawn ein. Er wird zu einer neuen eigenen Skala.",
	["Paste an upgrade scale"] = "Verbesserungsskala einfügen",
	["Paste the That's My BiS CSV export (or its JSON) and click Save. Prio and wishlist rows are kept, received loot is left out."] = "Fügt den CSV-Export von That's My BiS (oder dessen JSON) ein und klickt auf „Speichern“. Prio- und Wunschlistenzeilen bleiben erhalten, erhaltene Beute wird ausgelassen.",
	["Paste the softres.it CSV export (or its JSON) and click Save. It replaces the soft reserves you imported before."] = "Fügt den CSV-Export von softres.it (oder dessen JSON) ein und klickt auf „Speichern“. Er ersetzt die Soft-Reserves, die Ihr zuvor importiert habt.",
	["Paste waypoints"] = "Wegpunkte einfügen",
	["Path"] = "Pfad",
	["Pause between two mail actions. Raise it if the server refuses some."] = "Pause zwischen zwei Postaktionen. Erhöht sie, wenn der Server einige ablehnt.",
	["Paused while RestedXP is loaded, because its guide handles quests. Hold the pause key to do a quest by hand."] = "Pausiert, solange RestedXP geladen ist, weil dessen Guide die Quests übernimmt. Haltet die Pausentaste gedrückt, um eine Quest von Hand zu erledigen.",
	["Pawn scale"] = "Pawn-Skala",
	["Payout"] = "Auszahlung",
	["Payout (share minus purchases)"] = "Auszahlung (Anteil minus Käufe)",
	["Payout is each player's share minus what they bought: negative means they pay in. You trade the gold yourself."] = "Die Auszahlung ist der Anteil jedes Spielers minus das, was er gekauft hat: Negativ heißt, er zahlt ein. Das Gold handelt Ihr selbst.",
	["Pending, accepted or declined summon."] = "Ausstehende, angenommene oder abgelehnte Beschwörung.",
	["Per mana"] = "Pro Mana",
	["Per mana and the share of your mana only, for long fights where mana runs out first."] = "Nur pro Mana und der Anteil an Eurem Mana, für lange Kämpfe, in denen zuerst das Mana ausgeht.",
	["Per row"] = "Pro Reihe",
	["Percent"] = "Prozent",
	["Percent (+7.5%)"] = "Prozent (+7,5 %)",
	["Percent of what you wear now, or the plain score difference. Empty slots always show the score. A simulated rating shows DPS instead."] = "Prozent dessen, was Ihr jetzt tragt, oder die reine Differenz der Wertung. Leere Plätze zeigen immer die Wertung. Eine simulierte Bewertung zeigt stattdessen DPS.",
	["Personal best"] = "Persönliche Bestzeit",
	["Pet %d"] = "Tier %d",
	["Pet Care"] = "Tierpflege",
	["Pet Target"] = "Begleiterziel",
	["Pet XP color"] = "Farbe der Tier-EP",
	["Pet abilities"] = "Tierfähigkeiten",
	["Pet cast bar"] = "Zauberleiste des Begleiters",
	["Pet experience"] = "Tiererfahrung",
	["Pet experience bar"] = "Erfahrungsleiste des Tiers",
	["Pet food is running low: %d left."] = "Das Tierfutter geht zur Neige: noch %d.",
	["Pet frame"] = "Begleiterrahmen",
	["Pet indicator"] = "Begleiteranzeige",
	["Pet level"] = "Tierstufe",
	["Pet on passive"] = "Begleiter auf passiv",
	["Pet spell damage numbers"] = "Schadenszahlen der Begleiterzauber",
	["Pet trainer"] = "Tierausbilder",
	["Pet training"] = "Tierausbildung",
	["Pets"] = "Begleiter",
	["Pets and guardians scale"] = "Skalierung von Begleitern und Wächtern",
	["Pick a button"] = "Schaltfläche wählen",
	["Pick a ledger, start a new one or delete one."] = "Wählt ein Kassenbuch, beginnt ein neues oder löscht eines.",
	["Pick a macro on the left."] = "Wählt links ein Makro.",
	["Pick a profession and a target skill. The plan needs EldoUI_LootData or recipes you saw in your profession window."] = "Wählt einen Beruf und eine Zielfertigkeit. Der Plan benötigt EldoUI_LootData oder Rezepte, die Ihr in Eurem Berufsfenster gesehen habt.",
	["Pick a repair mode first."] = "Wählt zuerst einen Reparaturmodus.",
	["Pick a setting in the list first."] = "Wählt zuerst eine Einstellung in der Liste.",
	["Pick a setting in the list to change it."] = "Wählt eine Einstellung in der Liste, um sie zu ändern.",
	["Pick an addon button to keep it on the map with its addon, or to gather it in the bin again. The list shows every addon button found since you logged in."] = "Wählt eine Addon-Schaltfläche, um sie mit ihrem Addon auf der Karte zu behalten oder wieder in der Ablage zu sammeln. Die Liste zeigt jede Addon-Schaltfläche, die seit dem Einloggen gefunden wurde.",
	["Pick another plan, start a new one, or start from the talents you have."] = "Wählt einen anderen Plan, beginnt einen neuen oder startet mit den Talenten, die Ihr habt.",
	["Pick food from the bags"] = "Futter aus den Taschen wählen",
	["Pick how to gather the addon buttons first."] = "Wählt zuerst, wie die Addon-Schaltflächen gesammelt werden.",
	["Pick one of the game's own graphics quality steps with the gear. Off keeps your own graphics settings."] = "Wählt mit dem Zahnrad eine der Grafikqualitätsstufen des Spiels. Aus behält Eure eigenen Grafikeinstellungen.",
	["Pick one of your spells to stop reminding about it."] = "Wählt einen Eurer Zauber, um nicht mehr an ihn zu erinnern.",
	["Pick order numbers"] = "Zahlen der Wahlreihenfolge",
	["Pick the extra text the rows below change."] = "Wählt den Zusatztext, den die Zeilen unten ändern.",
	["Pick this zone on the Routes tab"] = "Dieses Gebiet auf dem Reiter Routen wählen",
	["Pick which tooltips hide in combat first."] = "Wählt zuerst, welche Tooltips im Kampf ausgeblendet werden.",
	["Pickers open"] = "Auswahl öffnet nach",
	["Picks change out of combat."] = "Die Auswahl wird außerhalb des Kampfes geändert.",
	["Picks in the plan"] = { one = "Talent im Plan", other = "Talente im Plan" },
	["Picture settings the game's menu does not show. A row only appears when your game has that setting."] = "Grafikeinstellungen, die das Menü des Spiels nicht zeigt. Eine Zeile erscheint nur, wenn Euer Spiel diese Einstellung hat.",
	["Pin a recipe in your profession window, in the Loot Guide's Crafting page or with Alt-click in Alts > Professions."] = "Heftet ein Rezept in Eurem Berufsfenster, auf der Seite Handwerk des Loot Guide oder per Alt-Klick unter Twinks > Berufe an.",
	["Pin buttons"] = "Anheft-Schaltflächen",
	["Pin recipes for one shopping list with what you have on every character, recipe cooldowns across alts and a cheapest leveling plan from your saved prices."] = "Heftet Rezepte für eine Einkaufsliste an, mit dem, was Ihr auf jedem Charakter habt, Rezept-Abklingzeiten über Twinks hinweg und einem günstigsten Levelplan aus Euren gespeicherten Preisen.",
	["Pin recipes from the profession window, Loot Guide or Alts window; the Shopping List shows what they need. /eui plan has a leveling plan."] = "Heftet Rezepte aus dem Berufsfenster, dem Loot Guide oder dem Twink-Fenster an; die Einkaufsliste zeigt, was sie brauchen. /eui plan hat einen Levelplan.",
	["Pin recipes to see their reagents with what you have on all your characters. At the auction house, Send to Shopping fills a shopping list; you still search and buy yourself."] = "Heftet Rezepte an, um ihre Reagenzien mit dem zu sehen, was Ihr auf allen Charakteren habt. Im Auktionshaus füllt „An Einkaufsliste senden“ eine Einkaufsliste; suchen und kaufen müsst Ihr weiterhin selbst.",
	["Pin scale"] = "Skalierung der Markierungen",
	["Pin shape"] = "Form der Markierungen",
	["Pin size"] = "Markierungsgröße",
	["Pin this plan"] = "Diesen Plan anheften",
	["Pin to the shopping list"] = "An die Einkaufsliste heften",
	["Ping EldoUI cooldown icons"] = "EldoUI-Abklingzeitsymbole pingen",
	["Ping Feed"] = "Ping-Ticker",
	["Ping feed"] = "Ping-Ticker",
	["Ping key %d"] = "Ping-Taste %d",
	["Ping key %d (spell or item set in Alerts and Banners > Pings)"] = "Ping-Taste %d (Zauber oder Gegenstand festgelegt unter Hinweise und Banner > Pings)",
	["Ping keys"] = "Ping-Tasten",
	["Ping sound"] = "Ping-Ton",
	["Ping wheel scale"] = "Skalierung des Ping-Rads",
	["Pingable icons"] = "Pingbare Symbole",
	["Pings"] = "Pings",
	["Pinned recipes and every reagent with what you have."] = "Angeheftete Rezepte und jedes Reagenz mit dem, was Ihr habt.",
	["Pinned x%d"] = "Angeheftet x%d",
	["Pinned."] = "Angeheftet.",
	["Pins"] = "Markierungen",
	["Pins every recipe of the plan with its number of crafts, so the shopping list shows the reagents."] = "Heftet jedes Rezept des Plans mit seiner Anzahl an Herstellungen an, damit die Einkaufsliste die Reagenzien zeigt.",
	["Pins in the art style's look, on the world map and the minimap."] = "Markierungen in der Optik des Grafikstils, auf der Weltkarte und der Minikarte.",
	["Pins of the Gathering module. Its own settings decide which nodes it records."] = "Markierungen des Moduls Sammeln. Dessen eigene Einstellungen entscheiden, welche Vorkommen es erfasst.",
	["Pins of the Waypoints module. Its own settings decide which waypoints exist."] = "Markierungen des Moduls Wegpunkte. Dessen eigene Einstellungen entscheiden, welche Wegpunkte es gibt.",
	["Pins only"] = "Nur Markierungen",
	["Pins where you stood when you targeted or pointed at a rare creature outdoors. Kept for all your characters. Right-click a pin to forget it."] = "Markiert, wo Ihr standet, als Ihr einen raren Gegner im Freien anvisiert oder auf ihn gezeigt habt. Für alle Eure Charaktere gespeichert. Rechtsklickt auf eine Markierung, um sie zu vergessen.",
	["Place every spell, item, macro and equipment set back on its slot."] = "Jeden Zauber, Gegenstand, jedes Makro und Ausrüstungsset wieder auf seinen Platz legen.",
	["Placed"] = "Gesetzt",
	["Places Blizzard's minimap buttons in the map's corners. Needs \"Minimap buttons\" on in Blizzard UI (Move to place, Hide for \"Hidden\")."] = "Platziert Blizzards Minikartenschaltflächen in den Ecken der Karte. Benötigt „Minikartenschaltflächen“ unter Blizzard-UI (Verschieben zum Platzieren, Ausblenden für „Ausgeblendet“).",
	["Plain dark cells with thin dividers instead of Blizzard's parchment days. Event icons and today's glow stay."] = "Schlichte dunkle Zellen mit dünnen Trennlinien statt Blizzards Pergamenttagen. Ereignissymbole und das Leuchten des heutigen Tages bleiben.",
	["Plain names"] = "Schlichte Namen",
	["Plain, in the art style's color"] = "Schlicht, in der Farbe des Grafikstils",
	["Plan %d  You %d"] = "Plan %d  Ihr %d",
	["Plan %d/%d  Learned %d  Unspent %d"] = "Plan %d/%d  Erlernt %d  Offen %d",
	["Plan for"] = "Plan für",
	["Plan for your first talent group."] = "Plan für Eure erste Talentgruppe.",
	["Plan for your second talent group (dual talents). Each group keeps its own plans."] = "Plan für Eure zweite Talentgruppe (Dualspezialisierung). Jede Gruppe behält ihre eigenen Pläne.",
	["Plan levels"] = "Planstufen",
	["Plan who drops Mana Tide Totem and each resistance totem, and send it to your group. Shamans with EldoUI see their part on the Drop All tooltip."] = "Plant, wer Totem der Manaflut und jedes Widerstandstotem setzt, und sendet es an Eure Gruppe. Schamanen mit EldoUI sehen ihren Teil im Tooltip von „Alle setzen“.",
	["Plan with known recipes only"] = "Nur mit bekannten Rezepten planen",
	["Plan your own class again."] = "Wieder die eigene Klasse planen.",
	["Plan your own class, or another class for an alt or a friend. Plans for other classes are saved for your whole account and are never learned from here."] = "Plant Eure eigene Klasse oder eine andere für einen Twink oder einen Freund. Pläne für andere Klassen werden für Euren ganzen Account gespeichert und nie von hier aus erlernt.",
	["Plan your talents level by level, for your class or another. A talent is learned only when you click Learn, never on its own."] = "Plant Eure Talente Stufe für Stufe, für Eure Klasse oder eine andere. Ein Talent wird nur erlernt, wenn Ihr auf „Erlernen“ klickt, nie von selbst.",
	["Plan your talents level by level, see which point comes next and learn it with one click. EldoUI never spends a point unless you click."] = "Plant Eure Talente Stufe für Stufe, seht, welcher Punkt als Nächstes kommt, und erlernt ihn mit einem Klick. EldoUI gibt nie einen Punkt aus, ohne dass Ihr klickt.",
	["Plan your talents level by level. Your ranks are white. A planned talent shows what you have and the plan, like 2>5, in your accent color. Full talents are green with +, and ranks you have outside the plan orange with !. The ring marks the next point."] = "Plant Eure Talente Stufe für Stufe. Eure Ränge sind weiß. Ein geplantes Talent zeigt, was Ihr habt, und den Plan, etwa 2>5, in Eurer Akzentfarbe. Volle Talente sind grün mit +, Ränge außerhalb des Plans orange mit !. Der Ring markiert den nächsten Punkt.",
	["Planner and build buttons"] = "Planer- und Build-Schaltflächen",
	["Plans"] = "Pläne",
	["Plate distance"] = "Plakettenentfernung",
	["Plate distance in the game now: %d yards."] = { one = "Plakettenentfernung im Spiel derzeit: %d Meter.", other = "Plakettenentfernung im Spiel derzeit: %d Meter." },
	["Plate distance is a protected game setting: no addon can change it, but your own chat command can. Pick the yards, then copy the command."] = "Die Plakettenentfernung ist eine geschützte Spieleinstellung: Kein Addon kann sie ändern, aber Euer eigener Chatbefehl schon. Wählt die Meter und kopiert dann den Befehl.",
	["Plate height"] = "Plakettenhöhe",
	["Plate height in pixels for these plates. 0 keeps the type's height."] = "Plakettenhöhe in Pixeln für diese Plaketten. 0 behält die Höhe des Typs.",
	["Plate height in pixels while you are in combat."] = "Plakettenhöhe in Pixeln, solange Ihr im Kampf seid.",
	["Plate width"] = "Plakettenbreite",
	["Plate width in pixels for these plates. 0 keeps the type's width."] = "Plakettenbreite in Pixeln für diese Plaketten. 0 behält die Breite des Typs.",
	["Plate width in pixels while you are in combat."] = "Plakettenbreite in Pixeln, solange Ihr im Kampf seid.",
	["Plates for enemy pets, guardians and summons."] = "Plaketten für feindliche Begleiter, Wächter und Beschwörungen.",
	["Plates for friendly NPCs such as guards and vendors."] = "Plaketten für freundliche NSCs wie Wachen und Händler.",
	["Plates for friendly players' pets and guardians."] = "Plaketten für Begleiter und Wächter freundlicher Spieler.",
	["Play a pop-up sound"] = "Pop-up-Ton abspielen",
	["Play a sound once when a treasure, chest or event card shows."] = "Einmal einen Ton abspielen, wenn eine Karte für einen Schatz, eine Truhe oder ein Ereignis erscheint.",
	["Play a sound when a rare shows up. If a Fanfare trigger for rares has a sound, that one plays instead, so you hear one sound per rare."] = "Einen Ton abspielen, wenn ein rarer Gegner auftaucht. Hat ein Fanfare-Auslöser für rare Gegner einen Ton, spielt stattdessen dieser, sodass Ihr einen Ton pro rarem Gegner hört.",
	["Play it"] = "Abspielen",
	["Play the notable sound"] = "Den Ton für Bemerkenswertes abspielen",
	["Played time at the level-up."] = "Spielzeit beim Stufenaufstieg.",
	["Player Frame Power Bar"] = "Ressourcenleiste des Spielerrahmens",
	["Player Notes"] = "Spielernotizen",
	["Player Notes marks"] = "Markierungen der Spielernotizen",
	["Player Notes' group journal is off. Turn on Group journal under Player Notes to fill this list."] = "Das Gruppentagebuch der Spielernotizen ist aus. Schaltet „Gruppentagebuch“ unter Spielernotizen ein, um diese Liste zu füllen.",
	["Player item level"] = "Gegenstandsstufe des Spielers",
	["Player names in the scoreboard and results in their class color instead of the team color."] = "Spielernamen in der Punktetafel und den Ergebnissen in ihrer Klassenfarbe statt in der Teamfarbe.",
	["Player notes"] = "Spielernotizen",
	["Player raid warnings no longer show in the middle of the screen (they stay in chat). Boss emotes always show."] = "Schlachtzugswarnungen von Spielern erscheinen nicht mehr in der Bildschirmmitte (sie bleiben im Chat). Boss-Emotes erscheinen immer.",
	["Player, target, focus, pet, target-of-target, boss, party pet and party target frames, plus Blizzard's own unit frames and cast bar."] = "Rahmen für Spieler, Ziel, Fokus, Begleiter, Ziel des Ziels, Boss, Gruppenbegleiter und Gruppenziele, dazu Blizzards eigene Einheitenrahmen und Zauberleiste.",
	["Players in their class color, NPCs in their reaction color."] = "Spieler in ihrer Klassenfarbe, NSCs in ihrer Reaktionsfarbe.",
	["Players in their class color. NPCs use the color mode below."] = "Spieler in ihrer Klassenfarbe. NSCs nutzen den Farbmodus unten.",
	["Players or NPCs."] = "Spieler oder NSCs.",
