	["Recipe toasts"] = "Rezepthinweise",
	["Recipes, mounts, pets and toys you already have get a green icon at vendors (needs \"Improve (extra info)\" for the merchant window under Blizzard UI)."] = "Rezepte, Reittiere, Begleiter und Spielzeuge, die Ihr schon habt, erhalten bei Händlern ein grünes Symbol (benötigt „Verbessern (Zusatzinfos)“ für das Händlerfenster unter Blizzard-UI).",
	["Recommended build"] = "Empfohlener Build",
