	["Red Error Text"] = "Roter Fehlertext",
	["Red error text in the EldoUI font; size and time below."] = "Roter Fehlertext in EldoUI-Schrift; Größe und Dauer unten.",
	["Red for hostile through green for exalted, the game's standing colors."] = "Rot für feindselig bis Grün für ehrfürchtig, die Ruffarben des Spiels.",
	["Red lines stop the macro from working; orange words are only a warning (a spell you learn later is fine)."] = "Rote Zeilen verhindern, dass das Makro funktioniert; orange Wörter sind nur eine Warnung (ein Zauber, den Ihr später erlernt, ist in Ordnung).",
	["Red tint on unusable gear"] = "Rote Tönung auf unbenutzbarer Ausrüstung",
