	["Rows fade out after this time; 0 keeps them until newer pings push them out."] = "Zeilen verblassen nach dieser Zeit; 0 behält sie, bis neuere Pings sie verdrängen.",
	["Rows of addons that an EldoUI module steps aside for get a tag, and their tooltip names the modules."] = "Zeilen von Addons, für die ein EldoUI-Modul Platz macht, erhalten eine Markierung, und ihr Tooltip nennt die Module.",
	["Rows: a list as tall as the merchant window. Grid: tiles with icon, name and price, 2 to 6 across."] = "Zeilen: eine Liste so hoch wie das Händlerfenster. Raster: Kacheln mit Symbol, Name und Preis, 2 bis 6 nebeneinander.",
	["Rule"] = "Regel",
	["Rule %d"] = "Regel %d",
	["Rule on"] = "Regel an",
	["Rules"] = "Regeln",
