	["Save group chat"] = "Gruppenchat speichern",
	["Save plan"] = "Plan speichern",
	["Save your action bars, macros, key bindings and Edit Mode layout as they are now."] = "Speichert Eure Aktionsleisten, Makros, Tastenbelegungen und das Layout des Bearbeitungsmodus, wie sie jetzt sind.",
	["Save your action bars, macros, key bindings and Edit Mode layout, preview what a restore changes, and put them back with one click."] = "Speichert Eure Aktionsleisten, Makros, Tastenbelegungen und das Layout des Bearbeitungsmodus, zeigt vorab, was eine Wiederherstellung ändert, und stellt sie mit einem Klick zurück.",
	["Save your picks"] = "Auswahl speichern",
	["Save your picks as a loadout"] = "Auswahl als Zusammenstellung speichern",
	["Saved action bars, macros, key bindings and Edit Mode layouts of every character."] = "Gespeicherte Aktionsleisten, Makros, Tastenbelegungen und Bearbeitungsmodus-Layouts aller Charaktere.",
	["Saved conversation"] = "Gespeicherte Unterhaltung",
	["Saved for your %s characters."] = "Für Eure %s-Charaktere gespeichert.",
