	["Saved talent plan"] = "Gespeicherter Talentplan",
	["Saved the %s plan %s for later. It opens on your %s characters and under %s in the planner. Nothing was learned."] = "Der %s-Plan %s wurde für später gespeichert. Er öffnet sich auf Euren %s-Charakteren und unter %s im Planer. Nichts wurde erlernt.",
	["Saved the talent plan %s for this character. Nothing was learned."] = "Der Talentplan %s wurde für diesen Charakter gespeichert. Nichts wurde erlernt.",
	["Saved the talent plan %s. Nothing was learned."] = "Der Talentplan %s wurde gespeichert. Nichts wurde erlernt.",
	["Saved the talent plan %s. Nothing was learned.%s %s"] = "Der Talentplan %s wurde gespeichert. Nichts wurde erlernt.%s %s",
	["Saved the totem loadout %s."] = "Die Totemzusammenstellung %s wurde gespeichert.",
	["Saved when that character last opened its profession window."] = "Gespeichert, als dieser Charakter zuletzt sein Berufsfenster geöffnet hat.",
	["Saves every finished trade that moved gold: who, where, and how much each way. Shared by all your characters."] = "Speichert jeden abgeschlossenen Handel, bei dem Gold bewegt wurde: wer, wo und wie viel in jede Richtung. Von allen Euren Charakteren geteilt.",
	["Saves the four totems you picked now as a new loadout (up to 8)."] = "Speichert die vier jetzt gewählten Totems als neue Zusammenstellung (bis zu 8).",
	["Saves what vendors charge for items, so the Auction House module can show crafting costs for reagents bought from vendors."] = "Speichert, was Händler für Gegenstände verlangen, damit das Modul Auktionshaus Herstellungskosten für bei Händlern gekaufte Reagenzien zeigen kann.",
	["Saving"] = "Speichern",
	["Saving happens out of combat. Running a macro is always your own key press."] = "Gespeichert wird außerhalb des Kampfes. Ein Makro auszuführen ist immer Euer eigener Tastendruck.",
	["Say in chat what was declined"] = "Im Chat sagen, was abgelehnt wurde",
	["Say when your layer changes"] = "Melden, wenn sich Euer Layer ändert",
	["Say whether you already have each mount, pet, toy or appearance in the list."] = "Angeben, ob Ihr jedes Reittier, jeden Begleiter, jedes Spielzeug oder jede Vorlage in der Liste schon habt.",
