	["Show the active tracking"] = "Aktive Verfolgung anzeigen",
	["Show the arrival time"] = "Ankunftszeit anzeigen",
	["Show the arrow"] = "Pfeil anzeigen",
	["Show the button"] = "Schaltfläche anzeigen",
	["Show the cast target"] = "Zauberziel anzeigen",
	["Show the chosen snapshot as a string to copy to another character or a friend."] = "Den gewählten Schnappschuss als String zeigen, um ihn auf einen anderen Charakter oder zu einem Freund zu kopieren.",
	["Show the coordinate box"] = "Koordinatenfeld anzeigen",
	["Show the cost total"] = "Gesamtkosten anzeigen",
	["Show the creature's model. Off shows the rare icon."] = "Das Modell der Kreatur zeigen. Aus zeigt das Rar-Symbol.",
	["Show the distance"] = "Entfernung anzeigen",
	["Show the first unfinished objective count (for example 3/8) next to the quest icon, as the unit tooltip reports it."] = "Den Stand des ersten unerledigten Questziels (zum Beispiel 3/8) neben dem Questsymbol anzeigen, wie ihn der Einheiten-Tooltip meldet.",
	["Show the four compass directions around the large map."] = "Die vier Himmelsrichtungen um die große Karte anzeigen.",
	["Show the gain as"] = "Zugewinn anzeigen als",
	["Show the healer mana list in a party as well as a raid."] = "Die Manaliste der Heiler nicht nur im Schlachtzug, sondern auch in einer Gruppe anzeigen.",
	["Show the junk count and value at a vendor. One click sells up to 12 stacks, with the same item protection as automatic selling. Requires Merchant Improve."] = "Zeigt bei einem Händler Anzahl und Wert des Plunders. Ein Klick verkauft bis zu 12 Stapel, mit demselben Gegenstandsschutz wie der automatische Verkauf. Braucht den Schalter Verbessern für das Händlerfenster.",
	["Show the panel in a group"] = "Panel in einer Gruppe anzeigen",
	["Show the pins on the minimap too. Only outdoors: the game gives no position in dungeons and raids."] = "Die Markierungen auch auf der Minikarte anzeigen. Nur im Freien: In Dungeons und Schlachtzügen gibt das Spiel keine Position an.",
	["Show the pins on the world map."] = "Die Markierungen auf der Weltkarte anzeigen.",
	["Show the portrait without color all the time."] = "Das Porträt immer ohne Farbe anzeigen.",
	["Show the reputation bar only once you stop gaining XP."] = "Die Rufleiste erst anzeigen, wenn Ihr keine EP mehr erhaltet.",
	["Show the server's time instead of your computer's."] = "Die Serverzeit statt der Zeit Eures Computers anzeigen.",
	["Show the spell's icon."] = "Das Symbol des Zaubers anzeigen.",
	["Show the threat bar only while you are in a party or raid."] = "Die Bedrohungsleiste nur anzeigen, solange Ihr in einer Gruppe oder einem Schlachtzug seid.",
	["Show the time left on your PvP flag beside the badge and in its tooltip."] = "Die verbleibende Zeit Eurer PvP-Markierung neben dem Abzeichen und in seinem Tooltip anzeigen.",
	["Show the timer"] = "Timer anzeigen",
	["Show the title"] = "Titel anzeigen",
	["Show the toast once for the zone you are in, with the settings above."] = "Den Hinweis einmal für das Gebiet anzeigen, in dem Ihr seid, mit den Einstellungen oben.",
	["Show the tooltip when the mouse is over a zone on a continent map."] = "Den Tooltip anzeigen, wenn die Maus auf einer Kontinentkarte über einem Gebiet ist.",
	["Show the tracker"] = "Verfolgung anzeigen",
	["Show the unit's target"] = "Ziel der Einheit anzeigen",
	["Show the volume panel"] = "Lautstärkeregler anzeigen",
	["Show the zone's level range on the toast."] = "Den Stufenbereich des Gebiets im Hinweis anzeigen.",
	["Show the zone's name, level range and territory for a few seconds when you enter another zone. Place it with move mode (Zone Toast)."] = "Name, Stufenbereich und Territorium des Gebiets einige Sekunden lang anzeigen, wenn Ihr ein anderes Gebiet betretet. Platziert den Hinweis im Verschiebemodus (Gebietshinweis).",
	["Show them faded"] = "Verblasst anzeigen",
	["Show this text"] = "Diesen Text anzeigen",
	["Show this type's casts under the plate. Display only."] = "Zauber dieses Typs unter der Plakette anzeigen. Nur Anzeige.",
	["Show this unit's buffs. The game keeps them updated, in combat too."] = "Die Stärkungszauber dieser Einheit anzeigen. Das Spiel hält sie aktuell, auch im Kampf.",
	["Show this unit's casts. Timing comes from the game's duration objects."] = "Die Zauber dieser Einheit anzeigen. Die Zeiten stammen aus den Dauerobjekten des Spiels.",
	["Show this unit's debuffs. The game keeps them updated, in combat too."] = "Die Schwächungszauber dieser Einheit anzeigen. Das Spiel hält sie aktuell, auch im Kampf.",
	["Show timestamps"] = "Zeitstempel anzeigen",
	["Show unexplored areas"] = "Unerkundete Bereiche anzeigen",
	["Show volume panel"] = "Lautstärkeregler zeigen",
	["Show waypoints on the minimap; ones out of range sit on its edge."] = "Wegpunkte auf der Minikarte anzeigen; Wegpunkte außer Reichweite sitzen an ihrem Rand.",
	["Show waypoints on the world map. Hover for details, right-click for options."] = "Wegpunkte auf der Weltkarte anzeigen. Mauszeiger darauf für Details, Rechtsklick für Optionen.",
	["Show when the buff on you is a lower rank than one you know. Out of combat only."] = "Anzeigen, wenn der Stärkungszauber auf Euch einen niedrigeren Rang hat als einer, den Ihr kennt. Nur außerhalb des Kampfes.",
	["Show whispers only in the messenger"] = "Flüstern nur im Messenger anzeigen",
	["Show whose territory the zone is on the toast."] = "Im Hinweis anzeigen, wessen Territorium das Gebiet ist.",
	["Show your known interrupt's icon and cooldown while your target or focus casts."] = "Symbol und Abklingzeit Eurer bekannten Unterbrechung anzeigen, während Euer Ziel oder Fokus einen Zauber wirkt.",
	["Show your note and mark on the player's tooltip."] = "Eure Notiz und Markierung im Tooltip des Spielers anzeigen.",
	["Showcase"] = "Schaukasten",
	["Showing every family"] = "Zeigt alle Familien",
	["Showing now: Blizzard default plates."] = "Aktuell angezeigt: Blizzards Standardplaketten.",
	["Showing now: Blizzard plates with EldoUI's look."] = "Aktuell angezeigt: Blizzard-Plaketten mit der Optik von EldoUI.",
	["Showing now: Blizzard's plates (the Nameplates module is off)."] = "Aktuell angezeigt: Blizzards Plaketten (das Modul Namensplaketten ist aus).",
	["Showing now: EldoUI plates. Blizzard's plate is faded out under them."] = "Aktuell angezeigt: EldoUI-Plaketten. Blizzards Plakette ist darunter ausgeblendet.",
	["Showing what a %s can learn"] = "Zeigt, was die Familie %s lernen kann",
	["Shown normally"] = "Normal angezeigt",
	["Shown once you know it: remind me when this buff is missing, running out or a higher rank is known. Off by default."] = "Erscheint, sobald Ihr ihn kennt: erinnert Euch, wenn dieser Stärkungszauber fehlt, ausläuft oder ein höherer Rang bekannt ist. Standardmäßig aus.",
	["Shown under (or above) the window while the Blizzard UI switch \"Improve (extra info)\" is on for the trade window."] = "Erscheint unter (oder über) dem Fenster, solange der Blizzard-UI-Schalter „Verbessern (Zusatzinfos)“ für das Handelsfenster an ist.",
	["Shown while you rest in an inn or city."] = "Erscheint, solange Ihr in einem Gasthaus oder einer Stadt rastet.",
	["Shows a number for every auto-attack hit, not only for hits that do something special."] = "Zeigt eine Zahl für jeden Treffer eines automatischen Angriffs, nicht nur für Treffer mit besonderer Wirkung.",
	["Shows a sample battleground message (/eui notify test bg)."] = "Zeigt eine Beispielnachricht eines Schlachtfelds (/eui notify test bg).",
	["Shows a sample raid warning."] = "Zeigt eine Beispiel-Schlachtzugswarnung.",
	["Shows a sample red error."] = "Zeigt einen roten Beispielfehler.",
	["Shows a sample tooltip for 5 seconds. It updates as you change settings."] = "Zeigt 5 Sekunden lang einen Beispiel-Tooltip. Er passt sich an, während Ihr Einstellungen ändert.",
	["Shows each spell's icon in front of its name."] = "Zeigt das Symbol jedes Zaubers vor seinem Namen.",
	["Shows estimated skill-up thresholds for the selected recipe."] = "Zeigt geschätzte Schwellen für Fertigkeitsanstiege beim gewählten Rezept.",
	["Shows every item with its amount and the total cost before anything is bought. Strongly recommended."] = "Zeigt jeden Gegenstand mit seiner Menge und die Gesamtkosten, bevor etwas gekauft wird. Dringend empfohlen.",
	["Shows every point of your plan again."] = "Zeigt wieder jeden Punkt Eures Plans.",
	["Shows how many crafts fit your bags, bank, and saved character inventories, with a button to list missing reagents."] = "Zeigt, wie viele Herstellungen Eure Taschen, Eure Bank und die gespeicherten Inventare Eurer Charaktere hergeben, mit einer Schaltfläche, um fehlende Reagenzien aufzulisten.",
	["Shows how many times a player from the other faction has killed this character, when the game identified the killer."] = "Zeigt, wie oft ein Spieler der anderen Fraktion diesen Charakter getötet hat, sofern das Spiel den Täter erkannt hat.",
	["Shows imported soft reserves and That's My BiS lists on item tooltips and loot rolls, and keeps a GDKP ledger. You roll and trade yourself."] = "Zeigt importierte Soft-Reserves und That's-My-BiS-Listen in Gegenstandstooltips und bei Beutewürfen und führt ein GDKP-Kassenbuch. Würfeln und handeln müsst Ihr selbst.",
	["Shows listings whose leader or activity name has this text. The game keeps listing comments from addons, so they can't be searched."] = "Zeigt Einträge, deren Anführer- oder Aktivitätsname diesen Text enthält. Das Spiel hält Eintragskommentare vor Addons zurück, daher lassen sie sich nicht durchsuchen.",
	["Shows on EldoUI's minimap, which the Blizzard UI step turns on (Recommended, Only EldoUI's own frames or Everything)."] = "Erscheint auf der Minikarte von EldoUI, die der Schritt Blizzard-UI einschaltet (Empfohlen, Nur EldoUIs eigene Rahmen oder Alles).",
	["Shows or hides the panel now (/eui volume)."] = "Zeigt den Lautstärkeregler jetzt an oder blendet ihn aus (/eui volume).",
	["Shows payouts in whole gold, rounded down. The rest stays with the organizer."] = "Zeigt Auszahlungen in ganzem Gold, abgerundet. Der Rest bleibt beim Organisator.",
	["Shows percentages from the first corpse on."] = "Zeigt Prozentwerte schon ab der ersten Leiche.",
	["Shows reagent costs and possible auction or vendor profit from your saved prices. Missing prices stay marked."] = "Zeigt Reagenzienkosten und möglichen Gewinn im Auktionshaus oder beim Händler anhand Eurer gespeicherten Preise. Fehlende Preise bleiben markiert.",
	["Shows the That's My BiS line (TMB: names with their prio, or wish for a wishlist entry)."] = "Zeigt die That's-My-BiS-Zeile (TMB: Namen mit ihrer Prio oder Wunsch bei einem Wunschlisteneintrag).",
	["Shows the bar outside a group so you can place and try it. Also /eui raidtools."] = "Zeigt die Leiste auch außerhalb einer Gruppe, damit Ihr sie platzieren und ausprobieren könnt. Auch /eui raidtools.",
	["Shows the chat command for the distance above, selected for copying. Paste it in chat and press Enter."] = "Zeigt den Chatbefehl für die Entfernung oben, zum Kopieren markiert. Fügt ihn im Chat ein und drückt die Eingabetaste.",
	["Shows the linked main beside an alt's name in guild chat. Off by default."] = "Zeigt im Gildenchat den verknüpften Main neben dem Namen eines Twinks. Standardmäßig aus.",
	["Shows the listings you dismissed again."] = "Zeigt die Einträge, die Ihr verworfen habt, wieder an.",
	["Shows the loot method, the master looter and the threshold. The group leader clicks it to change them; for everyone else it only shows what the leader set."] = "Zeigt die Plündermethode, den Plündermeister und die Schwelle. Der Gruppenanführer klickt darauf, um sie zu ändern; allen anderen zeigt es nur, was der Anführer eingestellt hat.",
	["Shows the numbers on the experience bar without hovering (game setting; off puts your own value back)."] = "Zeigt die Zahlen auf der Erfahrungsleiste, ohne dass Ihr mit der Maus darauf zeigen müsst (Spieleinstellung; aus stellt Euren eigenen Wert wieder her).",
	["Shows the partner's name in their class color."] = "Zeigt den Namen des Handelspartners in seiner Klassenfarbe.",
	["Shows the path in the Talent Planner's Builds tab. Nothing changes until you copy it into a plan there."] = "Zeigt den Pfad im Reiter Builds des Talentplaners. Nichts ändert sich, bis Ihr ihn dort in einen Plan kopiert.",
	["Shows the planner window (also /eui talents, a key binding, the Spec block on the Info Bar with Shift-click, and the Menu block)."] = "Zeigt das Planerfenster (auch /eui talents, eine Tastenbelegung, der Block Spezialisierung auf der Infoleiste per Umschaltklick und der Block Menü).",
	["Shows the prompt for 15 seconds with test text, so you can see it and place it (/eui move: \"Summon and Resurrection Prompt\"). Its buttons only close it."] = "Zeigt die Anfrage 15 Sekunden lang mit Testtext, damit Ihr sie seht und platzieren könnt (/eui move: „Beschwörungs- und Wiederbelebungsanfrage“). Ihre Schaltflächen schließen sie nur.",
	["Shows the snapshot's Edit Mode layout as text for Edit Mode > Layouts > Import."] = "Zeigt das Layout des Bearbeitungsmodus aus dem Schnappschuss als Text für Bearbeitungsmodus > Layouts > Importieren.",
	["Shows the soft-reserve line (SR: names, with +N for a bonus)."] = "Zeigt die Soft-Reserve-Zeile (SR: Namen, mit +N für einen Bonus).",
	["Shows the window with what you can learn (also /eui training and the Training info bar block)."] = "Zeigt das Fenster mit dem, was Ihr erlernen könnt (auch /eui training und der Infoleisten-Block Training).",
	["Shows three sample toasts (/eui notify test lane)."] = "Zeigt drei Beispielhinweise (/eui notify test lane).",
	["Shows whether an item is on your Always sell or Never sell list, with the marking shortcut."] = "Zeigt, ob ein Gegenstand auf Eurer Liste Immer verkaufen oder Nie verkaufen steht, mit dem Tastenkürzel zum Markieren.",
	["Shows which rules match your current target (out of combat)."] = "Zeigt, welche Regeln auf Euer aktuelles Ziel zutreffen (außerhalb des Kampfes).",
	["Shows your plan as it should stand at your level now."] = "Zeigt Euren Plan so, wie er auf Eurer jetzigen Stufe stehen sollte.",
	["Shows your target's appearance on the preview model (players only)."] = "Zeigt das Aussehen Eures Ziels am Vorschaumodell (nur Spieler).",
	["Shrinks plates of minor (trivial) units. 100 keeps the size."] = "Verkleinert Plaketten unbedeutender (trivialer) Einheiten. 100 behält die Größe.",
	["Shrinks plates of pets, guardians and summons. 100 keeps the size."] = "Verkleinert Plaketten von Begleitern, Wächtern und Beschwörungen. 100 behält die Größe.",
	["Side"] = "Seite",
	["Silence emotes while resting"] = "Emotes beim Ausruhen stummschalten",
	["Simple plates for minor units"] = "Einfache Plaketten für unbedeutende Einheiten",
	["Sit next to the frame, or stack on the buffs so both blocks never overlap."] = "Neben dem Rahmen sitzen oder auf den Stärkungszaubern stapeln, damit sich beide Blöcke nie überlappen.",
	["Sit next to the frame, or stack on the debuffs so both blocks never overlap."] = "Neben dem Rahmen sitzen oder auf den Schwächungszaubern stapeln, damit sich beide Blöcke nie überlappen.",
	["Situation"] = "Situation",
	["Situations"] = "Situationen",
	["Size and click area"] = "Größe und Klickbereich",
	["Size and place (Move and scale)"] = "Größe und Ort (Verschieben und skalieren)",
	["Size as a share of the screen height."] = "Größe als Anteil der Bildschirmhöhe.",
	["Size of Blizzard's alerts in the lane."] = "Größe von Blizzards Warnungen in der Warnspalte.",
	["Size of a free icon. Auto makes it as tall as the bar."] = "Größe eines freien Symbols. Automatisch macht es so hoch wie die Leiste.",
	["Size of all zone text."] = "Größe aller Gebietstexte.",
	["Size of each addon button in the bin."] = "Größe jeder Addon-Schaltfläche im Knopfsammler.",
	["Size of each entry in pixels."] = "Größe jedes Eintrags in Pixeln.",
	["Size of each totem button."] = "Größe jeder Totemschaltfläche.",
	["Size of level-up toasts and the boss banner."] = "Größe der Stufenaufstiegshinweise und des Bossbanners.",
	["Size of names and health text."] = "Größe von Namen und Gesundheitstext.",
	["Size of names, levels, zones, ranks and notes."] = "Größe von Namen, Stufen, Gebieten, Rängen und Notizen.",
	["Size of quest and gossip text, from 8 up; titles are 4 points larger. Game keeps the game's size."] = "Größe von Quest- und Gesprächstext, ab 8; Titel sind 4 Punkte größer. Spiel behält die Größe des Spiels.",
	["Size of quest and objective lines in the EldoUI font. Game keeps Blizzard's size (Edit Mode setting)."] = "Größe der Quest- und Zielzeilen in der EldoUI-Schrift. Spiel behält Blizzards Größe (Einstellung im Bearbeitungsmodus).",
	["Size of raid warnings and boss emotes."] = "Größe von Schlachtzugswarnungen und Boss-Emotes.",
	["Size of the %s."] = "Größe: %s.",
	["Size of the PvP badge on player plates."] = "Größe des PvP-Abzeichens auf Spielerplaketten.",
	["Size of the arrow in pixels."] = "Größe des Pfeils in Pixeln.",
	["Size of the bag buttons in percent (100 = Blizzard's size)."] = "Größe der Taschenschaltflächen in Prozent (100 = Blizzards Größe).",
	["Size of the bar text."] = "Größe des Leistentexts.",
	["Size of the battlefield map."] = "Größe der Schlachtfeldkarte.",
	["Size of the battleground message text."] = "Größe des Texts von Schlachtfeldnachrichten.",
	["Size of the buff icons in pixels."] = "Größe der Stärkungszaubersymbole in Pixeln.",
	["Size of the buff icons."] = "Größe der Stärkungszaubersymbole.",
	["Size of the button in pixels."] = "Größe der Schaltfläche in Pixeln.",
	["Size of the button."] = "Größe der Schaltfläche.",
	["Size of the card."] = "Größe der Karte.",
	["Size of the class or role badge."] = "Größe des Klassen- oder Rollenabzeichens.",
	["Size of the combat icon. Same uses the icon size above."] = "Größe des Kampfsymbols. Bei 0 gilt die Symbolgröße oben.",
	["Size of the countdown numbers on plate auras. Auto grows them with the icon."] = "Größe der Countdown-Zahlen auf Plakettenauren. Bei Autom. wachsen sie mit dem Symbol.",
	["Size of the crowd control icon."] = "Größe des Symbols für Kontrolleffekte.",
	["Size of the damage and healing numbers over enemies and allies (game setting WorldTextScale)."] = "Größe der Schadens- und Heilungszahlen über Gegnern und Verbündeten (Spieleinstellung WorldTextScale).",
	["Size of the day numbers."] = "Größe der Tageszahlen.",
	["Size of the debuff icons."] = "Größe der Schwächungszaubersymbole.",
	["Size of the elite and rare icon."] = "Größe des Elite- und Rar-Symbols.",
	["Size of the encounter / alternate power bar (on the \"Encounter Bar\" mover)."] = "Größe der Begegnungsleiste bzw. alternativen Ressourcenleiste (auf dem Verschiebefeld „Begegnungsleiste“).",
	["Size of the error text."] = "Größe des Fehlertexts.",
	["Size of the figure while EldoUI moves it (switch \"Move and scale\")."] = "Größe der Figur, solange EldoUI sie verschiebt (Schalter „Verschieben und skalieren“).",
	["Size of the health text. Auto uses the plate text size, smaller on a thin bar so it stays inside."] = "Größe des Gesundheitstexts. Autom. nutzt die Textgröße der Plakette, auf einer dünnen Leiste kleiner, damit er in der Leiste bleibt.",
	["Size of the icon; the toast's height follows it."] = "Größe des Symbols; die Höhe des Hinweises richtet sich danach.",
	["Size of the item icon; the tile height follows."] = "Größe des Gegenstandssymbols; die Kachelhöhe richtet sich danach.",
	["Size of the labels on Ready, Roles, Pull and the group buttons. Auto follows the button size."] = "Größe der Beschriftungen auf Bereit, Rollen, Pull und den Gruppenschaltflächen. Automatisch folgt der Schaltflächengröße.",
	["Size of the level badge."] = "Größe des Stufenabzeichens.",
	["Size of the macro text and the check view."] = "Größe des Makrotexts und der Prüfansicht.",
	["Size of the map and minimap pins."] = "Größe der Markierungen auf Karte und Minikarte.",
	["Size of the messages in the communities chat, in the EldoUI font."] = "Größe der Nachrichten im Community-Chat, in der EldoUI-Schrift.",
	["Size of the micro buttons in percent (100 = Blizzard's size)."] = "Größe der Mikroschaltflächen in Prozent (100 = Blizzards Größe).",
	["Size of the minimap pins."] = "Größe der Markierungen auf der Minikarte.",
	["Size of the name and health text on every EldoUI unit frame (the power text is 3 points smaller)."] = "Größe von Namens- und Gesundheitstext auf jedem EldoUI-Einheitenrahmen (der Ressourcentext ist 3 Punkte kleiner).",
	["Size of the name line in each row."] = "Größe der Namenszeile in jeder Reihe.",
	["Size of the names and scores in the table."] = "Größe der Namen und Punktestände in der Tabelle.",
	["Size of the ping wheel (changed out of combat only)."] = "Größe des Ping-Rads (wird nur außerhalb des Kampfes geändert).",
	["Size of the power orb, ring included. It sits on its own mover, Player Frame Power Bar."] = "Größe der Ressourcenkugel, Ring eingeschlossen. Sie sitzt auf einem eigenen Verschiebefeld, Ressourcenleiste des Spielerrahmens.",
	["Size of the quest icon."] = "Größe des Questsymbols.",
	["Size of the quest titles; the member line is one size smaller."] = "Größe der Questtitel; die Mitgliederzeile ist eine Schriftgröße kleiner.",
	["Size of the raid marker in pixels."] = "Größe der Schlachtzugsmarkierung in Pixeln.",
	["Size of the ready check."] = "Größe des Bereitschaftschecks.",
	["Size of the resting icon. Same uses the icon size above."] = "Größe des Erholungssymbols. Bei 0 gilt die Symbolgröße oben.",
	["Size of the section and quest titles in the EldoUI font. Auto is two sizes larger than the lines."] = "Größe der Abschnitts- und Questtitel in der EldoUI-Schrift. Automatisch ist zwei Schriftgrößen größer als die Zeilen.",
	["Size of the spell icon."] = "Größe des Zaubersymbols.",
	["Size of the spell names; levels and costs are one size smaller."] = "Größe der Zaubernamen; Stufen und Kosten sind eine Schriftgröße kleiner.",
	["Size of the stack number on debuff, buff and crowd control icons. Auto grows it with the icon."] = "Größe der Stapelzahl auf Symbolen für Schwächungszauber, Stärkungszauber und Kontrolleffekte. Bei Autom. wächst sie mit dem Symbol.",
	["Size of the status icons."] = "Größe der Statussymbole.",
	["Size of the talking head."] = "Größe des sprechenden Kopfes.",
	["Size of the text in the group, activity and who lists."] = "Größe des Texts in den Gruppen-, Aktivitäts- und Wer-Listen.",
	["Size of the toast's main line."] = "Größe der Hauptzeile des Hinweises.",
	["Size of the top-center widgets (on the \"Top-center Widgets\" mover)."] = "Größe der Widgets oben in der Mitte (auf dem Verschiebefeld „Widgets oben in der Mitte“).",
	["Size of the totem icon."] = "Größe des Totemsymbols.",
	["Size of the tracker's text."] = "Größe des Texts der Verfolgung.",
	["Size of the transport pins."] = "Größe der Transportmarkierungen.",
	["Size of the travel button."] = "Größe der Reisetaste.",
	["Size of the weekday names above the grid."] = "Größe der Wochentagsnamen über dem Raster.",
	["Size of the whole menu in percent (100 = normal size)."] = "Größe des ganzen Menüs in Prozent (100 = normale Größe).",
	["Size of the whole tooltip."] = "Größe des gesamten Tooltips.",
	["Size of the whole tracker."] = "Größe der gesamten Verfolgung.",
	["Size of the widgets below the minimap."] = "Größe der Widgets unter der Minikarte.",
	["Size of the world map pins."] = "Größe der Markierungen auf der Weltkarte.",
	["Size of the zone / last online line."] = "Größe der Zeile Gebiet / zuletzt online.",
	["Size of the zone name; the details are a bit smaller."] = "Größe des Gebietsnamens; die Details sind etwas kleiner.",
	["Size of this frame's health text. Text size uses the size on the General tab."] = "Größe des Gesundheitstexts dieses Rahmens. Textgröße verwendet die Größe aus dem Reiter Allgemein.",
	["Size of this frame's name. Text size uses the size on the General tab, like the other texts."] = "Größe des Namens dieses Rahmens. Textgröße verwendet die Größe aus dem Reiter Allgemein, wie die anderen Texte.",
	["Size of this frame's power text. Auto is a little smaller than the text size, or the text size on orbs."] = "Größe des Ressourcentexts dieses Rahmens. Autom. ist etwas kleiner als die Textgröße, auf Kugeln gleich der Textgröße.",
	["Size, icon side and time format are set per plate type on the type tabs."] = "Größe, Symbolseite und Zeitformat werden pro Plakettentyp in den Typ-Reitern festgelegt.",
