	["Talking Head"] = "Sprechender Kopf",
	["Tall rows on a solid window for the ledger."] = "Hohe Zeilen in einem deckenden Fenster für das Kassenbuch.",
	["Taller rows give each player more space."] = "Höhere Zeilen geben jedem Spieler mehr Platz.",
	["Taller rows with one color for all names."] = "Höhere Zeilen mit einer Farbe für alle Namen.",
	["Tame a beast that knows it and let your pet use it: Beast Training keeps the rank for good."] = "Zähmt ein Wildtier, das ihn kennt, und lasst Euer Tier ihn benutzen: Die Wildtierausbildung behält den Rang dauerhaft.",
	["Tank plates: 186 x 15 (200 x 16 in combat), threat colors by role, a border that pulses when you lose aggro, another tank's mobs in a calm color, stacking on."] = "Tank-Plaketten: 186 x 15 (200 x 16 im Kampf), Bedrohungsfarben nach Rolle, ein Rand, der pulsiert, wenn Ihr die Aggro verliert, Gegner eines anderen Tanks in einer ruhigen Farbe, Stapelung an.",
	["Tank: lost threat glow"] = "Tank: Leuchten bei verlorener Bedrohung",
	["Tank: you have threat. Others: you don't."] = "Tank: Ihr habt die Bedrohung. Andere: Ihr habt sie nicht.",
	["Tank: you lost threat. Others: the mob is on you."] = "Tank: Ihr habt die Bedrohung verloren. Andere: Der Gegner greift Euch an.",
	["Tanks want threat, damage dealers and healers don't."] = "Tanks wollen Bedrohung, Schadensverursacher und Heiler nicht.",
	["Tapped by others"] = "Von anderen beansprucht",
	["Tapped, dead, ghost and offline units take their colors from the Colors page (Status), shared with the party and raid frames."] = "Beanspruchte und tote Einheiten, Geister und Offline-Einheiten nehmen ihre Farben von der Seite Farben (Status), gemeinsam mit den Gruppen- und Schlachtzugsrahmen.",
	["Target"] = "Ziel",
	["Target a player to see their appearance."] = "Nehmt einen Spieler ins Ziel, um sein Aussehen zu sehen.",
	["Target a rare nearby"] = "Einen raren Gegner in der Nähe ins Ziel nehmen",
	["Target and focus"] = "Ziel und Fokus",
	["Target and focus cast bars"] = "Zauberleisten von Ziel und Fokus",
	["Target highlight"] = "Zielhervorhebung",
	["Target icon"] = "Zielsymbol",
	["Target icon row"] = "Zielsymbolreihe",
	["Target in class color"] = "Ziel in Klassenfarbe",
	["Target must be in front of you, or you must be behind it."] = "Das Ziel muss vor Euch sein, oder Ihr müsst hinter ihm stehen.",
	["Target of Target"] = "Ziel des Ziels",
	["Target of target, focus target, pet target and party target frames have no cast bar."] = "Rahmen für Ziel des Ziels, Fokusziel, Begleiterziel und Gruppenziel haben keine Zauberleiste.",
	["Target of target, focus target, pet target and party target frames show no auras."] = "Rahmen für Ziel des Ziels, Fokusziel, Begleiterziel und Gruppenziel zeigen keine Auren.",
	["Target plate details"] = "Details der Zielplakette",
	["Target scale"] = "Zielskalierung",
	["Target skill"] = "Zielfertigkeit",
	["Targeted by"] = "Im Ziel von",
	["Targeted by (%d)"] = "Im Ziel von (%d)",
	["Targeting key"] = "Taste zum Anvisieren",
	["Taskbar flash"] = "Blinken in der Taskleiste",
	["Teach it to your pet in Beast Training."] = "Bringt ihn Eurem Tier in der Wildtierausbildung bei.",
	["Teaches you"] = "Lehrt Euch",
	["Teal tint"] = "Blaugrüne Tönung",
	["Teal titles and a \"New in Forever\" tag everywhere."] = "Blaugrüne Titel und überall eine Kennzeichnung „Neu in Forever“.",
	["Teal titles in the quest log, tracker, quest giver lists and on the map; the quest window and tooltips keep Blizzard's look."] = "Blaugrüne Titel im Questlog, in der Verfolgung, in den Listen der Questgeber und auf der Karte; das Questfenster und die Tooltips behalten Blizzards Optik.",
	["Teleports"] = "Teleporte",
	["Tell me when the loot changes"] = "Änderungen der Beuteverteilung melden",
	["Tells you when a rare creature, a treasure or an event shows up: a card and a sound. Reads only what the game shows (minimap markers, nameplates, your target)."] = "Meldet Euch, wenn ein rarer Gegner, ein Schatz oder ein Ereignis auftaucht: eine Karte und ein Ton. Liest nur, was das Spiel zeigt (Minikartenmarkierungen, Namensplaketten, Euer Ziel).",
	["Ten names per line, everyone on the lists."] = "Zehn Namen pro Zeile, alle auf den Listen.",
	["Territory"] = "Territorium",
	["Test"] = "Test",
	["Test achievement"] = "Testerfolg",
	["Test cast"] = "Testzauber",
	["Test frames"] = "Testrahmen",
	["Test frames can't be shown in combat."] = "Testrahmen können im Kampf nicht angezeigt werden.",
	["Test plate"] = "Testplakette",
	["Test plate type"] = "Typ der Testplakette",
	["Test prompt"] = "Anfrage testen",
	["Test the lane"] = "Warnspalte testen",
	["Test: someone wants to summon you to Ironforge."] = "Test: Jemand möchte Euch nach Eisenschmiede beschwören.",
	["Text %d"] = "Text %d",
	["Text %d (off)"] = "Text %d (aus)",
	["Text %d: %s"] = "Text %d: %s",
	["Text only, no background or icons, finished reagents hidden."] = "Nur Text, kein Hintergrund und keine Symbole, fertige Reagenzien ausgeblendet.",
	["Text size in the conversation windows."] = "Textgröße in den Unterhaltungsfenstern.",
	["Text size in the info strip."] = "Textgröße im Infostreifen.",
	["Text size in the sent log."] = "Textgröße im Versandprotokoll.",
	["Text size of names and prices."] = "Textgröße von Namen und Preisen.",
	["Text size of skinned window titles."] = "Textgröße der Titel von Fenstern mit Skin.",
	["Text size of the SR and TMB line under each roll."] = "Textgröße der SR- und TMB-Zeile unter jedem Wurf.",
	["Text size of the rows."] = "Textgröße der Zeilen.",
	["Text size on the card."] = "Textgröße auf der Karte.",
	["Text size, row height, icons, stripes, group title colors and see-through. Drag the window's corner grip to change its size; Ctrl+mouse wheel on the title bar zooms it."] = "Textgröße, Zeilenhöhe, Symbole, Streifen, Farben der Gruppentitel und Durchsichtigkeit. Zieht am Eckgriff des Fensters, um seine Größe zu ändern; Strg+Mausrad auf der Titelleiste zoomt es.",
	["Texture of the health, power and cast bars, also used on Blizzard's plates in Blizzard mode. Theme texture follows the General page."] = "Textur der Gesundheits-, Ressourcen- und Zauberleisten, im Blizzard-Modus auch auf Blizzards Plaketten verwendet. Themen-Textur folgt der Seite Allgemein.",
	["That Battle.net friend is not on your friends list right now."] = "Dieser Battle.net-Freund ist gerade nicht auf Eurer Freundesliste.",
	["That Pawn scale has no stats EldoUI can use."] = "Diese Pawn-Skala hat keine Werte, die EldoUI nutzen kann.",
	["That button is protected, so it stays where the game put it."] = "Diese Schaltfläche ist geschützt und bleibt daher, wo das Spiel sie hingesetzt hat.",
	["That frame is not a button."] = "Dieser Rahmen ist keine Schaltfläche.",
	["That is not a style filter string."] = "Das ist kein Stilfilter-String.",
	["That is not an EldoUI nameplate style filter string."] = "Das ist kein Stilfilter-String für EldoUI-Namensplaketten.",
	["That is one of the game's or EldoUI's own buttons."] = "Das ist eine der eigenen Schaltflächen des Spiels oder von EldoUI.",
	["That macro is gone. Pick it again."] = "Dieses Makro gibt es nicht mehr. Wählt es erneut.",
	["That macro list is full."] = "Diese Makroliste ist voll.",
	["That player could not be added to the bench."] = "Dieser Spieler konnte nicht auf die Ersatzbank gesetzt werden.",
	["That snapshot string holds no action bars."] = "Dieser Schnappschuss-String enthält keine Aktionsleisten.",
	["That snapshot string was changed or damaged (the checksum doesn't match). Copy it again in full."] = "Dieser Schnappschuss-String wurde verändert oder beschädigt (die Prüfsumme stimmt nicht). Kopiert ihn erneut vollständig.",
	["That snapshot was taken on another class; its spells were skipped."] = "Dieser Schnappschuss stammt von einer anderen Klasse; seine Zauber wurden übersprungen.",
	["That suggested path isn't available."] = "Dieser vorgeschlagene Pfad ist nicht verfügbar.",
	["That talent is already at its full rank in your plan."] = "Dieses Talent hat in Eurem Plan bereits seinen vollen Rang.",
	["That talent isn't in your class's tree."] = "Dieses Talent ist nicht im Baum Eurer Klasse.",
	["The \"...\" button that opens the addon button bin."] = "Die Schaltfläche „...“, die den Knopfsammler öffnet.",
	["The \"skip this cutscene?\" dialogs and the tutorial window in the EldoUI look."] = "Die Abfragen zum Überspringen von Zwischensequenzen und das Tutorialfenster in der EldoUI-Optik.",
	["The + and - buttons; Blizzard shows them while you point at the map."] = "Die Schaltflächen + und -; Blizzard zeigt sie, solange Ihr auf die Karte zeigt.",
	["The 36 px button hides in combat, like its list."] = "Die 36-px-Schaltfläche verschwindet im Kampf, wie ihre Liste.",
	["The Auction module is not loaded."] = "Das Modul Auktion ist nicht geladen.",
	["The Best of all total adds up the best times; it needs a time for every level before."] = "Die Summe von Beste von allen addiert die besten Zeiten; sie braucht eine Zeit für jede Stufe davor.",
	["The Copy button adds how long ago each trade was (\"3h ago\")."] = "Die Schaltfläche Kopieren fügt hinzu, wie lange jeder Handel her ist („vor 3 Std.“).",
	["The Copy button adds the zone or instance to each line."] = "Die Schaltfläche Kopieren fügt jeder Zeile das Gebiet oder die Instanz hinzu.",
	["The Copy button in the log adds the date and time to each line."] = "Die Schaltfläche Kopieren im Protokoll fügt jeder Zeile Datum und Uhrzeit hinzu.",
	["The EldoUI editor opens and closes together with Blizzard's macro window, and follows its selection. Off: open it with the Edit in EldoUI button."] = "Der EldoUI-Editor öffnet und schließt sich zusammen mit Blizzards Makrofenster und folgt dessen Auswahl. Aus: Öffnet ihn mit der Schaltfläche In EldoUI bearbeiten.",
	["The EldoUI look with see-through panels."] = "Die EldoUI-Optik mit durchscheinenden Panels.",
	["The EldoUI look with smaller group finder list text and Player Notes marks on listings."] = "Die EldoUI-Optik mit kleinerem Text in der Liste der Gruppensuche und Markierungen der Spielernotizen bei den Einträgen.",
	["The EldoUI look, following the mouse."] = "Die EldoUI-Optik, folgt der Maus.",
	["The EldoUI version of members who share it; an older one than yours shows orange."] = "Die EldoUI-Version von Mitgliedern, die sie teilen; eine ältere als Eure erscheint orange.",
	["The Enter Battle popup's skin and countdown bar are set under Messages > Ready check."] = "Skin und Countdown-Leiste des Pop-ups Schlacht betreten werden unter Nachrichten > Bereitschaftscheck eingestellt.",
	["The Herbalism, Mining or Skinning rank a node or corpse needs, colored by your own rank like the profession window (red: too low, gray: no more skill-ups)."] = "Der Rang in Kräuterkunde, Bergbau oder Kürschnerei, den ein Vorkommen oder eine Leiche verlangt, gefärbt nach Eurem eigenen Rang wie im Berufsfenster (rot: zu niedrig, grau: keine Fertigkeitspunkte mehr).",
	["The Loot Guide's dungeon and raid entrance pins on the world map."] = "Die Dungeon- und Schlachtzugseingänge des Loot Guide als Markierungen auf der Weltkarte.",
	["The NPC's title (Innkeeper, Flight Master) as the game shows it. Outside instances only."] = "Der Titel des NSC (Gastwirt, Flugmeister), wie das Spiel ihn zeigt. Nur außerhalb von Instanzen.",
	["The Party Quests panel shows while you are in a party. /eui party shows or hides it too. Place it in move mode (Party Quests)."] = "Das Panel Gruppenquests erscheint, solange Ihr in einer Gruppe seid. /eui party zeigt oder verbirgt es ebenfalls. Platziert es im Verschiebemodus (Gruppenquests).",
	["The Planner button and your plan on Blizzard's talent window need Blizzard UI > Spellbook and talents with Improve on."] = "Die Schaltfläche Planer und Euer Plan in Blizzards Talentfenster benötigen Blizzard-UI > Zauberbuch und Talente mit eingeschaltetem Verbessern.",
	["The Raid Loot window lets the game show through a little. How much: General > Panel opacity."] = "Das Fenster Schlachtzugsbeute lässt das Spiel etwas durchscheinen. Wie stark: Allgemein > Panel-Deckkraft.",
	["The Shaper's Terrace"] = "Die Terrasse des Formers",
	["The Shopping List tracker on screen while something is pinned. Move it in move mode (Shopping List)."] = "Die Verfolgung der Einkaufsliste auf dem Bildschirm, solange etwas angeheftet ist. Verschiebt sie im Verschiebemodus (Einkaufsliste).",
	["The Split Timer records no levels without it."] = "Ohne dieses Modul zeichnet der Split-Timer keine Stufen auf.",
	["The Trade log window, newest first (also /eui trades and the link in chat)."] = "Das Fenster Handelsprotokoll, neueste zuerst (auch /eui trades und der Link im Chat).",
	["The Training tab lists what your class trainer can teach you now and at later levels, with the cost. It only shows the list: you still learn at the trainer."] = "Der Reiter Training listet, was Euer Klassenlehrer Euch jetzt und auf späteren Stufen beibringen kann, mit den Kosten. Er zeigt nur die Liste: Erlernen müsst Ihr weiterhin beim Lehrer.",
	["The XP bar disappears at the level cap; the reputation bar takes its place."] = "Die EP-Leiste verschwindet auf der Höchststufe; die Rufleiste nimmt ihren Platz ein.",
	["The XP tooltip shows XP gained this session, XP per hour and the time to the next level."] = "Der EP-Tooltip zeigt die in dieser Sitzung erhaltenen EP, EP pro Stunde und die Zeit bis zur nächsten Stufe.",
	["The XP tooltip shows the XP still needed to reach the level cap and, with session statistics on, the time at this session's pace (rested XP and finished quests count as a head start)."] = "Der EP-Tooltip zeigt die bis zur Höchststufe noch fehlenden EP und, bei aktiver Sitzungsstatistik, die Zeit beim Tempo dieser Sitzung (Erholungsbonus und fertige Quests zählen als Vorsprung).",
	["The abilities each mob cast in front of you."] = "Die Fähigkeiten, die jeder Gegner vor Euch gewirkt hat.",
	["The ability log is empty again."] = "Das Fähigkeitenprotokoll ist wieder leer.",
	["The accept helper skips quests the game shows in gray (too low for your level). You can still take them yourself."] = "Der Annahmehelfer überspringt Quests, die das Spiel grau zeigt (zu niedrig für Eure Stufe). Ihr könnt sie weiterhin selbst annehmen.",
	["The air totem the air button drops."] = "Das Lufttotem, das die Luft-Schaltfläche aufstellt.",
	["The alternate power bar some encounters use."] = "Die alternative Ressourcenleiste, die manche Begegnungen nutzen.",
	["The armor figure that shows when your gear is damaged. Move, scale or hide it with its switches on the Blizzard UI page."] = "Die Rüstungsfigur, die erscheint, wenn Eure Ausrüstung beschädigt ist. Verschiebt, skaliert oder verbergt sie mit ihren Schaltern auf der Seite Blizzard-UI.",
	["The arrow points here."] = "Der Pfeil zeigt hierher.",
	["The art style's thin frame line around the tracker (bronze under WoW Forever)."] = "Die dünne Rahmenlinie des Grafikstils um die Verfolgung (Bronze unter WoW Forever).",
	["The bag buttons side by side."] = "Die Taschenschaltflächen nebeneinander.",
	["The bag buttons top to bottom."] = "Die Taschenschaltflächen von oben nach unten.",
	["The banner after a boss kill with its loot."] = "Das Banner nach einem Bosssieg mit seiner Beute.",
	["The bar fades from the high to the low health color as the unit loses health. Set both colors on the Colors page."] = "Die Leiste geht von der Farbe für hohe zur Farbe für niedrige Gesundheit über, während die Einheit Gesundheit verliert. Beide Farben stellt Ihr auf der Seite Farben ein.",
	["The bar starts with your role's spells, plus Totemic Recall, Reincarnation and Earth Shock. Your own ticks stay; unknown spells never show."] = "Die Leiste beginnt mit den Zaubern Eurer Rolle, dazu Totemruf, Reinkarnation und Erdschock. Eure eigenen Häkchen bleiben; unbekannte Zauber erscheinen nie.",
	["The bars already match"] = "Die Leisten stimmen bereits überein",
	["The bars stand upright side by side and fill from the bottom. Their text moves into the tooltip."] = "Die Leisten stehen aufrecht nebeneinander und füllen sich von unten. Ihr Text wandert in den Tooltip.",
	["The big level-up and new spell toast in the middle of the screen."] = "Der große Hinweis für Stufenaufstiege und neue Zauber in der Bildschirmmitte.",
	["The boss you just defeated."] = "Der Boss, den Ihr gerade besiegt habt.",
	["The bound key in the button's top corner."] = "Die belegte Taste in der oberen Ecke der Schaltfläche.",
	["The browse / listing / who tabs on the right as flat icon boxes with the accent on the open one."] = "Die Reiter Durchsuchen / Eintrag / Wer rechts als flache Symbolfelder, mit dem Akzent auf dem geöffneten.",
	["The browser also lists debug and GM settings and the ones the game locks or shows read-only (those stay read-only)."] = "Die Übersicht listet auch Debug- und GM-Einstellungen sowie jene, die das Spiel sperrt oder nur lesbar zeigt (diese bleiben schreibgeschützt).",
	["The browser lists only settings that differ from the game's default or that EldoUI set."] = "Die Übersicht listet nur Einstellungen, die vom Standard des Spiels abweichen oder die EldoUI gesetzt hat.",
	["The buff or item name under each icon."] = "Der Name des Stärkungszaubers oder Gegenstands unter jedem Symbol.",
	["The button glows for a few seconds when a new quest item lands on it (look under the Glows page)."] = "Die Schaltfläche leuchtet einige Sekunden lang, wenn ein neuer Questgegenstand darauf landet (die Optik steht auf der Seite „Leuchteffekte“).",
	["The camera distance is set after combat."] = "Die Kameraentfernung wird nach dem Kampf eingestellt.",
	["The camera distance where the whole offset applies."] = "Die Kameraentfernung, ab der der volle Versatz gilt.",
	["The camera looks a little down when zoomed out, for a wider view. An experimental game setting: the game may change or drop it."] = "Die Kamera blickt herausgezoomt etwas nach unten, für eine weitere Sicht. Eine experimentelle Spieleinstellung: Das Spiel kann sie ändern oder entfernen.",
	["The camera stops at the water surface instead of going under it."] = "Die Kamera hält an der Wasseroberfläche an, statt darunter zu tauchen.",
	["The camera tilts up a little as you zoom out, so you see more ahead of you."] = "Die Kamera neigt sich beim Herauszoomen etwas nach oben, damit Ihr mehr vor Euch seht.",
	["The camera tilts with the ground when you walk up or down a hill."] = "Die Kamera neigt sich mit dem Boden, wenn Ihr einen Hang hinauf- oder hinabgeht.",
	["The card closes a few seconds after the rare dies."] = "Die Karte schließt sich einige Sekunden nach dem Tod des raren Gegners.",
	["The card opens after combat."] = "Die Karte öffnet sich nach dem Kampf.",
	["The card, no sound"] = "Die Karte, kein Ton",
	["The card, no sound: the card shows; no sound, flash, chat line or vibration. Nothing: no card either, and it is not listed under This session."] = "Die Karte, kein Ton: Die Karte erscheint; kein Ton, kein Blinken, keine Chatzeile und keine Vibration. Nichts: auch keine Karte, und er wird nicht unter Diese Sitzung aufgeführt.",
	["The cast bar color when its color mode is Own color."] = "Die Farbe der Zauberleiste, wenn ihr Farbmodus Eigene Farbe ist.",
	["The cast time on the right of the bar."] = "Die Zauberzeit rechts auf der Leiste.",
	["The channels above no longer show in the main chat (needs the Blizzard UI switch Improve for chat windows)."] = "Die Kanäle oben erscheinen nicht mehr im Hauptchat (benötigt den Blizzard-UI-Schalter Verbessern für Chatfenster).",
	["The character to race. Without one, Personal best is used."] = "Der Charakter, gegen den Ihr antretet. Ohne einen wird Persönliche Bestzeit verwendet.",
	["The character whose splits you look at."] = "Der Charakter, dessen Zwischenzeiten Ihr anseht.",
	["The characters whose reagents and recipe cooldowns count. On Forever, this realm means everyone on the same ruleset."] = "Die Charaktere, deren Reagenzien und Rezeptabklingzeiten zählen. Auf Forever bedeutet dieser Realm alle mit demselben Regelwerk.",
	["The cheapest recipes to level a profession, from your saved prices."] = "Die günstigsten Rezepte, um einen Beruf zu leveln, aus Euren gespeicherten Preisen.",
	["The chip needs Improve switched on for the minimap in Blizzard UI."] = "Die Anzeige benötigt Verbessern für die Minikarte in Blizzard-UI.",
	["The class icon in place of the game icon while a friend plays a WoW character."] = "Das Klassensymbol statt des Spielsymbols, solange ein Freund einen WoW-Charakter spielt.",
	["The classic resting icon or a small zzz."] = "Das klassische Erholungssymbol oder ein kleines zzz.",
	["The click drawer stays open or closed the way you left it, also after a reload."] = "Die Klickschublade bleibt offen oder geschlossen, wie Ihr sie verlassen habt, auch nach einem Neuladen.",
	["The clock time you land, after the time left."] = "Die Uhrzeit Eurer Landung, nach der verbleibenden Zeit.",
	["The color of new quests and the tag."] = "Die Farbe neuer Quests und der Kennzeichnung.",
	["The color of the empty part of the health bar when its mode is Own color."] = "Die Farbe des leeren Teils der Gesundheitsleiste, wenn ihr Modus Eigene Farbe ist.",
	["The cursor"] = "Mauszeiger",
	["The cut and its gold, such as: Tank repairs 300"] = "Der Abzug und sein Gold, etwa: Tank-Reparaturen 300",
	["The debuffs picked by the Auras tab filter, above the plate."] = "Die vom Filter des Reiters Auren gewählten Schwächungszauber, über der Plakette.",
	["The dialogs' EldoUI panels let the game show through a little. How much: General > Panel opacity."] = "Die EldoUI-Panels der Dialoge lassen das Spiel etwas durchscheinen. Wie stark: Allgemein > Panel-Deckkraft.",
	["The earth totem button while you are feared and know Tremor Totem (Shaman Totems > Group)."] = "Die Erdtotem-Schaltfläche, während Ihr verängstigt seid und Totem des Erdstoßes kennt (Schamanentotems > Gruppe).",
	["The earth totem the earth button drops. Right-click a totem in the button's picker does the same."] = "Das Erdtotem, das die Erde-Schaltfläche aufstellt. Ein Rechtsklick auf ein Totem in der Auswahl der Schaltfläche bewirkt dasselbe.",
	["The edge of the map that holds the slim button rail. Buttons set to \"On the side rail\" sit on it one under the other, each with a tooltip naming it."] = "Der Kartenrand mit der schmalen Schaltflächenleiste. Schaltflächen mit „Auf der Seitenleiste“ sitzen dort untereinander, jede mit einem Tooltip, der sie benennt.",
	["The editor lets the game show through a little. How much: General > Panel opacity."] = "Der Editor lässt das Spiel etwas durchscheinen. Wie stark: Allgemein > Panel-Deckkraft.",
	["The elixirs, flasks, food and weapon enchants you picked on the Consumables tab."] = "Die Elixiere, Fläschchen, Speisen und Waffenverzauberungen, die Ihr im Reiter Verbrauchsgüter gewählt habt.",
	["The enemy's buffs picked on the Auras tab."] = "Die Stärkungszauber des Gegners, die im Reiter Auren gewählt sind.",
	["The expansion landing page button, if the game shows one."] = "Die Schaltfläche der Erweiterungsübersicht, falls das Spiel eine zeigt.",
	["The extra icons from the Indicators tab on this type."] = "Die zusätzlichen Symbole aus dem Reiter Indikatoren bei diesem Typ.",
	["The faction you watch (tick \"Show as experience bar\" in the reputation list)."] = "Die Fraktion, die Ihr beobachtet (hakt in der Rufliste „Als Erfahrungsbalken anzeigen“ an).",
	["The filters you chose are still on next time you log in. Off: they start cleared every session."] = "Die gewählten Filter sind beim nächsten Einloggen noch aktiv. Aus: Sie beginnen jede Sitzung leer.",
	["The fire totem the fire button drops."] = "Das Feuertotem, das die Feuer-Schaltfläche aufstellt.",
	["The first complete roster is the starting point for history."] = "Die erste vollständige Mitgliederliste ist der Ausgangspunkt für den Verlauf.",
	["The first line: item or unit name."] = "Die erste Zeile: Name des Gegenstands oder der Einheit.",
	["The fishing skill from which no fish get away in the zone."] = "Die Angelfertigkeit, ab der Euch in diesem Gebiet kein Fisch mehr entkommt.",
	["The flat tracking button shows the icon of the tracking you have on, such as Find Herbs, and is dimmed while nothing is tracked. It still opens the game's tracking menu."] = "Die flache Verfolgungsschaltfläche zeigt das Symbol der Verfolgung, die Ihr aktiv habt, etwa Kräutersuche, und ist abgedunkelt, solange nichts verfolgt wird. Sie öffnet weiterhin das Verfolgungsmenü des Spiels.",
	["The flight timer bar is part of Quality of Life."] = "Die Flugtimer-Leiste gehört zu den Komfortfunktionen.",
	["The flight view's panel with a sample flight, in your art style and accent."] = "Das Panel der Flugansicht mit einem Beispielflug, in Eurem Grafikstil und Akzent.",
	["The frame"] = "Rahmen",
	["The frame art of every EldoUI unit frame: portrait ring or frame, bar border and fill. It never changes positions, sizes, bars or what the portrait shows. Blizzard's own frames are not affected."] = "Die Rahmengrafik jedes EldoUI-Einheitenrahmens: Porträtring oder -rahmen, Leistenrand und Füllung. Sie ändert nie Positionen, Größen, Leisten oder was das Porträt zeigt. Blizzards eigene Rahmen sind nicht betroffen.",
	["The frame the tabs edit, with sample values, in its current size, colors and texts."] = "Der Rahmen, den die Reiter bearbeiten, mit Beispielwerten, in seiner aktuellen Größe, seinen Farben und Texten.",
	["The frame this tab changes. Every tab edits the same unit, so pick it once and walk through the tabs."] = "Der Rahmen, den dieser Reiter ändert. Jeder Reiter bearbeitet dieselbe Einheit, wählt sie also einmal und geht dann die Reiter durch.",
	["The friends, guild, calendar, group finder and PvP windows let the game show through a little. How much: General > Panel opacity."] = "Die Fenster für Freunde, Gilde, Kalender, Gruppensuche und PvP lassen das Spiel etwas durchscheinen. Wie stark: Allgemein > Panel-Deckkraft.",
	["The game called off the layer move."] = "Das Spiel hat den Layerwechsel abgebrochen.",
	["The game declines invites to chat channels for you, without asking."] = "Das Spiel lehnt Einladungen in Chatkanäle für Euch ab, ohne zu fragen.",
	["The game did not add %s."] = "Das Spiel hat %s nicht hinzugefügt.",
	["The game did not allow this right now."] = "Das Spiel hat das gerade nicht erlaubt.",
	["The game did not ignore %s."] = "Das Spiel hat %s nicht ignoriert.",
	["The game did not invite %s."] = "Das Spiel hat %s nicht eingeladen.",
	["The game did not save the macro."] = "Das Spiel hat das Makro nicht gespeichert.",
	["The game did not take that value."] = "Das Spiel hat diesen Wert nicht angenommen.",
	["The game did not take the sound."] = "Das Spiel hat den Ton nicht angenommen.",
	["The game didn't accept the change. Nothing was learned."] = "Das Spiel hat die Änderung nicht angenommen. Nichts wurde erlernt.",
	["The game does not let addons read this member's buffs right now."] = "Das Spiel lässt Addons die Stärkungszauber dieses Mitglieds gerade nicht lesen.",
	["The game doesn't give your position here."] = "Das Spiel gibt Eure Position hier nicht an.",
	["The game doesn't let you change talents right now."] = "Das Spiel lässt Euch Eure Talente gerade nicht ändern.",
	["The game doesn't list this class's talent tree right now. Try again in a moment."] = "Das Spiel listet den Talentbaum dieser Klasse gerade nicht. Versucht es gleich noch einmal.",
	["The game doesn't show the %s tree here, so the plan is checked when a %s opens it."] = "Das Spiel zeigt den Talentbaum der Klasse %s hier nicht, daher wird der Plan geprüft, wenn ein %s ihn öffnet.",
	["The game doesn't show the %s tree to this character, so the link can't be read here. Paste it on a %s."] = "Das Spiel zeigt diesem Charakter den Talentbaum der Klasse %s nicht, daher kann der Link hier nicht gelesen werden. Fügt ihn bei einem %s ein.",
	["The game doesn't show the %s tree to this character. Your %s plans are kept and open on a %s."] = "Das Spiel zeigt diesem Charakter den Talentbaum der Klasse %s nicht. Eure Pläne für %s bleiben erhalten und öffnen sich bei einem %s.",
	["The game flashes in the taskbar when a pop-up appears."] = "Das Spiel blinkt in der Taskleiste, wenn ein Pop-up erscheint.",
	["The game has no help text for this setting."] = "Das Spiel hat keinen Hilfetext für diese Einstellung.",
	["The game hasn't sent your talent tree yet. Open the planner again in a moment."] = "Das Spiel hat Euren Talentbaum noch nicht gesendet. Öffnet den Planer gleich noch einmal.",
	["The game hides which totem is down right now; the timer shows again when it tells."] = "Das Spiel verbirgt gerade, welches Totem steht; der Timer erscheint wieder, sobald es das mitteilt.",
	["The game limits how often you can change layer. Try again in a few minutes."] = "Das Spiel begrenzt, wie oft Ihr den Layer wechseln könnt. Versucht es in ein paar Minuten erneut.",
	["The game locks this setting."] = "Das Spiel sperrt diese Einstellung.",
	["The game marks the unit for one of your quests. Outside instances only."] = "Das Spiel markiert die Einheit für eine Eurer Quests. Nur außerhalb von Instanzen.",
	["The game may have reset your setup: %s."] = "Das Spiel hat Eure Einrichtung möglicherweise zurückgesetzt: %s.",
	["The game menu buttons are in the Menu block on the Info Bar now. To get the micro menu back, turn off \"Replace with EldoUI's frame\" for it on the Blizzard UI page in /eui."] = "Die Schaltflächen des Spielmenüs sind jetzt im Block Menü auf der Infoleiste. Um das Mikromenü zurückzubekommen, schaltet auf der Seite Blizzard-UI in /eui „Durch EldoUI-Rahmen ersetzen“ dafür aus.",
	["The game moves you in %s."] = "Das Spiel versetzt Euch in %s.",
	["The game moves you to the group's layer."] = "Das Spiel versetzt Euch auf den Layer der Gruppe.",
	["The game names no zone here."] = "Das Spiel nennt hier kein Gebiet.",
	["The game plays this sound the moment your shield leaves you, in combat too. Off by default."] = "Das Spiel spielt diesen Ton in dem Moment, in dem Euer Schild Euch verlässt, auch im Kampf. Standardmäßig aus.",
	["The game refused %s. Nothing was learned."] = "Das Spiel hat %s abgelehnt. Nichts wurde erlernt.",
	["The game replaces rude words in chat with symbols."] = "Das Spiel ersetzt unhöfliche Wörter im Chat durch Symbole.",
	["The game shows this setting but does not let it change."] = "Das Spiel zeigt diese Einstellung, lässt sie aber nicht ändern.",
	["The game uses it on its own; the number is how many you carry."] = "Das Spiel benutzt es von selbst; die Zahl gibt an, wie viele Ihr dabeihabt.",
	["The game version EldoUI checked the path on."] = "Die Spielversion, mit der EldoUI den Pfad geprüft hat.",
	["The game's classification (the dragon on the target frame)."] = "Die Einstufung des Spiels (der Drache am Zielrahmen).",
	["The game's countdown numbers on each running totem."] = "Die Countdown-Zahlen des Spiels auf jedem laufenden Totem.",
	["The game's default value."] = "Der Standardwert des Spiels.",
	["The game's flight master art and a shape per kind."] = "Die Flugmeister-Grafik des Spiels und eine Form je Art.",
	["The game's happy, content or unhappy face in the corner of every stabled pet."] = "Das glückliche, zufriedene oder unglückliche Gesicht des Spiels in der Ecke jedes Tiers im Stall.",
	["The game's link button during special events. It shows only while an event runs."] = "Die Link-Schaltfläche des Spiels bei besonderen Ereignissen. Sie erscheint nur, solange ein Ereignis läuft.",
	["The game's map pin"] = "Kartenmarkierung des Spiels",
	["The game's name for the setting. A dot marks a value that differs from the game's default."] = "Der Name der Einstellung im Spiel. Ein Punkt markiert einen Wert, der vom Standard des Spiels abweicht.",
	["The game's own micro menu, placed by Blizzard's Edit Mode. EldoUI stops moving it, and this box leaves move mode; \"Let EldoUI place the micro menu\" on its options page brings EldoUI's layout back."] = "Das eigene Mikromenü des Spiels, platziert durch Blizzards Bearbeitungsmodus. EldoUI verschiebt es nicht mehr, und dieses Feld verlässt den Verschiebemodus; „EldoUI das Mikromenü platzieren lassen“ auf seiner Optionsseite bringt das Layout von EldoUI zurück.",
	["The game's own rare and treasure map icons, whatever the art style."] = "Die eigenen Kartensymbole des Spiels für rare Gegner und Schätze, unabhängig vom Grafikstil.",
	["The game's own short help text, where it has one."] = "Der eigene kurze Hilfetext des Spiels, sofern es einen hat.",
	["The game's quality preset: 1 is fastest, 10 looks best. The detailed graphics settings follow the step, as in the game's own menu."] = "Die Qualitätsvorgabe des Spiels: 1 ist am schnellsten, 10 sieht am besten aus. Die detaillierten Grafikeinstellungen folgen der Stufe, wie im Menü des Spiels.",
	["The game's tutorial pop-ups (game setting showTutorials)."] = "Die Tutorial-Pop-ups des Spiels (Spieleinstellung showTutorials).",
	["The gem socketing window."] = "Das Fenster zum Sockeln von Edelsteinen.",
	["The glow a nameplate style filter rule puts on matching plates."] = "Das Leuchten, das eine Regel der Namensplaketten-Stilfilter auf passende Plaketten legt.",
	["The green mark means this item beats what you wear, rated by the stat weights of your scale. The Upgrades page picks the scale and how big a gain counts."] = "Die grüne Markierung bedeutet, dass dieser Gegenstand besser ist als das, was Ihr tragt, bewertet nach der Gewichtung Eurer Skala. Die Seite Verbesserungen wählt die Skala und wie groß ein Zugewinn sein muss.",
	["The grid in a solid panel that follows your art style (the bronze frame line under WoW Forever), 22 px rows."] = "Das Raster in einem deckenden Panel, das Eurem Grafikstil folgt (die bronzene Rahmenlinie unter WoW Forever), 22-px-Zeilen.",
	["The group journal on tooltips, no menu entries."] = "Das Gruppentagebuch in Tooltips, keine Menüeinträge.",
	["The group plan can be sent out of combat."] = "Der Gruppenplan kann außerhalb des Kampfes gesendet werden.",
	["The health bar color when the color mode is One color."] = "Die Farbe der Gesundheitsleiste, wenn der Farbmodus Eine Farbe ist.",
	["The health bar color while this filter matches."] = "Die Farbe der Gesundheitsleiste, solange dieser Filter zutrifft.",
	["The health percent \"In execute range\" starts at."] = "Der Gesundheitsprozentsatz, ab dem „Im Hinrichtungsbereich“ beginnt.",
	["The height of each row in the history."] = "Die Höhe jeder Zeile im Verlauf.",
	["The hop request could not be sent."] = "Die Wechselanfrage konnte nicht gesendet werden.",
	["The imbue the main-hand icon casts."] = "Die Waffenverzauberung, die das Waffenhand-Symbol wirkt.",
	["The imbue the off-hand icon casts (it then goes on the off-hand weapon)."] = "Die Waffenverzauberung, die das Schildhand-Symbol wirkt (sie kommt dann auf die Waffe in der Schildhand).",
	["The imbue this hand's reminder asks for and a click casts. Automatic: the one you cast last. Any imbue on the hand meets it."] = "Die Waffenverzauberung, die die Erinnerung dieser Hand verlangt und die ein Klick wirkt. Automatisch: die zuletzt gewirkte. Jede Waffenverzauberung auf der Hand erfüllt sie.",
	["The important cast glow, the interrupter's name and the important cast sound are on the Effects tab."] = "Das Leuchten für wichtige Zauber, der Name des Unterbrechers und der Ton für wichtige Zauber stehen im Reiter Effekte.",
	["The inspected player's average item level, under the level line."] = "Die durchschnittliche Gegenstandsstufe des betrachteten Spielers, unter der Stufenzeile.",
	["The item ID shows on Shift through the Tooltip page (Items and spells > Item ID)."] = "Die Gegenstands-ID erscheint mit Umschalt über die Seite Tooltip (Gegenstände und Zauber > Gegenstands-ID).",
	["The item level of each item the inspected player wears."] = "Die Gegenstandsstufe jedes Gegenstands, den der betrachtete Spieler trägt.",
	["The job in a group this path is made for."] = "Die Aufgabe in einer Gruppe, für die dieser Pfad gemacht ist.",
	["The key text turns red while the game says your target is out of the item's range."] = "Der Tastentext wird rot, solange das Spiel meldet, dass Euer Ziel außer Reichweite des Gegenstands ist.",
	["The kind of place you are in."] = "Die Art von Ort, an dem Ihr seid.",
	["The last 50 players from your group journal."] = "Die letzten 50 Spieler aus Eurem Gruppentagebuch.",
	["The layer you are on as a short code on the map, read from the creatures around you. Click it to hop to another layer. Hidden in instances."] = "Der Layer, auf dem Ihr seid, als kurzer Code auf der Karte, gelesen an den Kreaturen um Euch. Klickt darauf, um auf einen anderen Layer zu wechseln. In Instanzen ausgeblendet.",
	["The ledger as text: sales, pot, cuts and payouts."] = "Das Kassenbuch als Text: Verkäufe, Topf, Abzüge und Auszahlungen.",
	["The level in the game's difficulty color, with elite or rare added."] = "Die Stufe in der Schwierigkeitsfarbe des Spiels, mit Elite oder Rar ergänzt.",
	["The level range of the zone under the cursor (or of the map shown), from the game's map data."] = "Der Stufenbereich des Gebiets unter dem Mauszeiger (oder der gezeigten Karte), aus den Kartendaten des Spiels.",
	["The level that took the least played time."] = "Die Stufe mit der kürzesten Spielzeit.",
	["The level that took the most played time."] = "Die Stufe mit der längsten Spielzeit.",
	["The level this point is for: one point per level from 10."] = "Die Stufe, für die dieser Punkt gedacht ist: ein Punkt pro Stufe ab 10.",
	["The level time in your accent color (warm sand under the WoW Forever art style)."] = "Die Stufenzeit in Eurer Akzentfarbe (warmer Sand im Grafikstil von WoW Forever).",
	["The level-up toast lists the spells and ranks your class trainer teaches from your new level that you don't know yet. Needs the Training module."] = "Der Hinweis beim Stufenaufstieg listet die Zauber und Ränge, die Euer Klassenlehrer ab Eurer neuen Stufe lehrt und die Ihr noch nicht kennt. Benötigt das Modul Training.",
	["The leveling plan uses only recipes you already know. Off: it also lists recipes you can still learn, marked Learn."] = "Der Levelplan nutzt nur Rezepte, die Ihr schon kennt. Aus: Er listet auch Rezepte, die Ihr noch erlernen könnt, markiert mit Erlernen.",
	["The line comes when the profession is five points from the cap too, so you can plan the trip to the trainer."] = "Die Zeile kommt auch, wenn der Beruf fünf Punkte vor der Obergrenze steht, damit Ihr den Weg zum Lehrer planen könnt.",
	["The link asks for %d ranks of %s, more than it has. It was made for other trees."] = { one = "Der Link verlangt %d Rang von %s, mehr als das Talent hat. Er wurde für andere Bäume erstellt.", other = "Der Link verlangt %d Ränge von %s, mehr als das Talent hat. Er wurde für andere Bäume erstellt." },
	["The link has %d points, more than a plan holds. The rest are left out."] = { one = "Der Link enthält %d Punkt, mehr als ein Plan fasst. Der Rest wird weggelassen.", other = "Der Link enthält %d Punkte, mehr als ein Plan fasst. Der Rest wird weggelassen." },
	["The link has %d talent trees, more than WoW: Forever's %s has."] = { one = "Der Link enthält %d Talentbaum, mehr als die Klasse %s in WoW: Forever hat.", other = "Der Link enthält %d Talentbäume, mehr als die Klasse %s in WoW: Forever hat." },
	["The link has no talent points in it."] = "Der Link enthält keine Talentpunkte.",
	["The link keeps only the final ranks: the plan takes lower rows first. Reorder it in the planner."] = "Der Link behält nur die endgültigen Ränge: Der Plan nimmt niedrigere Reihen zuerst. Ordnet ihn im Planer neu.",
	["The link lists %d talents in %s, more than WoW: Forever's tree has. It was made for other trees."] = { one = "Der Link listet %d Talent in %s auf, mehr als der Baum in WoW: Forever hat. Er wurde für andere Bäume erstellt.", other = "Der Link listet %d Talente in %s auf, mehr als der Baum in WoW: Forever hat. Er wurde für andere Bäume erstellt." },
	["The link names a talent %s doesn't have. It was made for other trees."] = "Der Link nennt ein Talent, das %s nicht hat. Er wurde für andere Bäume erstellt.",
	["The link's buying order isn't read: the plan takes lower rows first. Reorder it in the planner."] = "Die Kaufreihenfolge des Links wird nicht gelesen: Der Plan nimmt niedrigere Reihen zuerst. Ordnet ihn im Planer neu.",
	["The liquid in the orbs swirls slowly. Off keeps it still. It is also still while Animations is off on the General page."] = "Die Flüssigkeit in den Kugeln wirbelt langsam. Aus hält sie still. Sie bleibt auch still, solange der Schalter Animationen auf der Seite Allgemein aus ist.",
	["The list closes once you click a spell in it."] = "Die Liste schließt sich, sobald Ihr darin auf einen Zauber klickt.",
	["The list is full (%d aliases)."] = "Die Liste ist voll (%d Aliasnamen).",
	["The loadout %s switches when combat ends."] = "Zur Zusammenstellung %s wird gewechselt, sobald der Kampf endet.",
	["The loadout in battlegrounds and arenas."] = "Die Zusammenstellung in Schlachtfeldern und Arenen.",
	["The loadout in dungeons."] = "Die Zusammenstellung in Dungeons.",
	["The loadout in raids."] = "Die Zusammenstellung in Schlachtzügen.",
	["The loadout outside instances."] = "Die Zusammenstellung außerhalb von Instanzen.",
	["The look only: no extra lines, counts or buttons."] = "Nur die Optik: keine zusätzlichen Zeilen, Zähler oder Schaltflächen.",
	["The lowest item durability of you and of members who share it."] = "Die niedrigste Gegenstandshaltbarkeit bei Euch und bei Mitgliedern, die sie teilen.",
	["The macro %s already exists. Find it under Macros (/macro), Character tab."] = "Das Makro %s existiert bereits. Ihr findet es unter Makros (/macro) bei den charakterspezifischen Makros.",
	["The macro names a lower rank of a spell you know at a higher rank. Changes only the rank number to the highest rank you know (out of combat). Undo puts the old text back."] = "Das Makro nennt einen niedrigeren Rang eines Zaubers, den Ihr in einem höheren Rang kennt. Ändert nur die Rangnummer auf den höchsten Rang, den Ihr kennt (außerhalb des Kampfes). Rückgängig stellt den alten Text wieder her.",
	["The macro needs a name."] = "Das Makro braucht einen Namen.",
	["The macro's name (up to 16 letters)."] = "Der Name des Makros (bis zu 16 Buchstaben).",
	["The main must be one distinct guild member with no main link."] = "Der Main muss genau ein anderes Gildenmitglied ohne eigene Main-Verknüpfung sein.",
	["The mana cost as a percent of your maximum mana."] = "Die Manakosten in Prozent Eures maximalen Manas.",
	["The map areas your characters have explored, so the others' maps can show them dimmed."] = "Die Kartenbereiche, die Eure Charaktere erkundet haben, damit die Karten der anderen sie abgedunkelt zeigen können.",
	["The map fades to 30% while you move and stays solid under the mouse."] = "Die Karte blendet beim Bewegen auf 30 % ab und bleibt unter der Maus voll sichtbar.",
	["The map note has changes that aren't saved."] = "Die Kartennotiz hat ungespeicherte Änderungen.",
	["The map there does not take pins."] = "Die Karte dort nimmt keine Markierungen an.",
	["The micro menu and the bag bar show when you point at their spot."] = "Mikromenü und Taschenleiste erscheinen, wenn Ihr auf ihre Stelle zeigt.",
	["The micro menu is Blizzard's again, placed by the game's Edit Mode. %s on its options page brings EldoUI's layout back."] = "Das Mikromenü gehört wieder Blizzard und wird vom Bearbeitungsmodus des Spiels platziert. %s auf seiner Optionsseite holt das Layout von EldoUI zurück.",
	["The micro menu is now the %s block on the Info Bar."] = "Das Mikromenü ist jetzt der Block %s auf der Infoleiste.",
	["The micro menu shows when you point at its spot."] = "Das Mikromenü erscheint, wenn Ihr auf seine Stelle zeigt.",
	["The minimap is off."] = "Die Minikarte ist aus.",
	["The most buffs shown at once."] = "Höchstzahl gleichzeitig angezeigter Stärkungszauber.",
	["The most debuffs shown at once."] = "Höchstzahl gleichzeitig angezeigter Schwächungszauber.",
	["The mount a player rides, whether you have it, and where it comes from (Mount Journal text). Out of combat only."] = "Das Reittier eines Spielers, ob Ihr es habt und woher es stammt (Text aus der Reittiersammlung). Nur außerhalb des Kampfes.",
	["The mouse is over the unit."] = "Die Maus ist über der Einheit.",
	["The mouse wheel scrolls chat windows up and down."] = "Das Mausrad scrollt Chatfenster nach oben und unten.",
	["The name color while this filter matches."] = "Die Namensfarbe, solange dieser Filter zutrifft.",
	["The name line of a player's tooltip and the Target and Targeted by lines."] = "Die Namenszeile im Tooltip eines Spielers sowie die Zeilen Ziel und Im Ziel von.",
	["The name of each entry under its icon."] = "Der Name jedes Eintrags unter seinem Symbol.",
	["The name of the next stop on the way, above the track."] = "Der Name des nächsten Halts auf der Strecke, über der Spur.",
	["The name of the spell's target under the cast bar."] = "Der Name des Ziels des Zaubers unter der Zauberleiste.",
	["The new-mail icon."] = "Das Symbol für neue Post.",
	["The note editor opens after combat."] = "Der Notizeditor öffnet sich nach dem Kampf.",
	["The note shows below this much mana."] = "Die Notiz erscheint, sobald Euer Mana unter diesen Wert fällt.",
	["The off-hand imbue, while your off hand holds a weapon."] = "Die Waffenverzauberung der Schildhand, solange Eure Schildhand eine Waffe hält.",
	["The offset grows as you zoom out and is gone up close, so the character stays in the middle when you zoom in."] = "Der Versatz wächst beim Herauszoomen und verschwindet aus der Nähe, damit der Charakter beim Hineinzoomen in der Mitte bleibt.",
	["The oldest entries drop off after this many."] = "Die ältesten Einträge fallen nach so vielen weg.",
	["The one switch: off hides every EldoUI pin on the world map and the minimap. The map button, /eui mapnote and the key binding flip it too."] = "Der eine Schalter: Aus blendet jede EldoUI-Markierung auf Weltkarte und Minikarte aus. Die Kartenschaltfläche, /eui mapnote und die Tastenbelegung schalten ihn ebenfalls um.",
	["The one you keep up. Right-click its reminder to change it."] = "Der Stein, den Ihr aufrechterhaltet. Rechtsklickt auf seine Erinnerung, um ihn zu ändern.",
	["The organizer's percent and other cuts (a fixed gold amount each)."] = "Der Prozentsatz des Organisators und weitere Abzüge (jeweils ein fester Goldbetrag).",
	["The organizer's share of the pot for new ledgers. Each ledger keeps its own cuts."] = "Der Anteil des Organisators am Topf für neue Kassenbücher. Jedes Kassenbuch behält seine eigenen Abzüge.",
	["The original frames' shape: thin bars beside a round portrait, the name above them. With the Vanilla Original skin they wear the game's own frame art."] = "Die Form der ursprünglichen Rahmen: dünne Leisten neben einem runden Porträt, der Name darüber. Mit dem Skin Vanilla Original tragen sie die eigene Rahmengrafik des Spiels.",
	["The panels let the game show through a little. How much: General > Panel opacity."] = "Die Panels lassen das Spiel etwas durchscheinen. Wie stark: Allgemein > Panel-Deckkraft.",
	["The part of the frame the position below refers to (Info panel needs the info panel on, General tab)."] = "Der Teil des Rahmens, auf den sich die Position unten bezieht (Infopanel braucht das eingeschaltete Infopanel, Reiter Allgemein).",
	["The pet trainer in the capital cities teaches it to you; then teach it to your pet in Beast Training."] = "Der Tierausbilder in den Hauptstädten lehrt es Euch; bringt es dann in der Wildtierausbildung Eurem Tier bei.",
	["The plan names no class EldoUI knows."] = "Der Plan nennt keine Klasse, die EldoUI kennt.",
	["The plan stays saved. Pick your class in the planner to find it."] = "Der Plan bleibt gespeichert. Wählt Eure Klasse im Planer, um ihn zu finden.",
	["The plate belongs to your focus."] = "Die Plakette gehört zu Eurem Fokus.",
	["The plate belongs to your target."] = "Die Plakette gehört zu Eurem Ziel.",
	["The plate border color while this filter matches."] = "Die Randfarbe der Plakette, solange dieser Filter zutrifft.",
	["The plate's opacity. Normal keeps the usual opacity (and the non-target fade)."] = "Die Deckkraft der Plakette. Normal behält die übliche Deckkraft (und das Verblassen von Nicht-Zielen).",
	["The player's class icon left of the bar."] = "Das Klassensymbol des Spielers links neben der Leiste.",
	["The player's class icon, or the role picked in the group finder."] = "Das Klassensymbol des Spielers oder die in der Gruppensuche gewählte Rolle.",
	["The portrait"] = "Das Porträt",
	["The portrait loses its color while the unit is dead, a ghost or offline. Needs Dead and offline look on the Effects tab."] = "Das Porträt verliert seine Farbe, solange die Einheit tot, ein Geist oder offline ist. Benötigt Optik für tot und offline auf dem Reiter Effekte.",
	["The power bar shows only while you are in combat."] = "Die Ressourcenleiste erscheint nur, solange Ihr im Kampf seid.",
	["The profession to plan. Your own professions show their skill."] = "Der zu planende Beruf. Eure eigenen Berufe zeigen ihre Fertigkeit.",
	["The pull countdown needs a group."] = "Der Pull-Countdown braucht eine Gruppe.",
	["The pulsing glow round your target's plate when the target highlight is \"Pulse glow\"."] = "Das pulsierende Leuchten um die Plakette Eures Ziels, wenn die Zielhervorhebung „Pulsierendes Leuchten“ ist.",
	["The quest helpers skip repeatable quests, such as reputation hand-ins, so a stack is never handed in at once."] = "Die Questhelfer überspringen wiederholbare Quests wie Rufabgaben, damit nie ein ganzer Stapel auf einmal abgegeben wird.",
	["The quest item button glows for a few seconds when a new quest item lands on it."] = "Die Schaltfläche für Questgegenstände leuchtet einige Sekunden lang, wenn ein neuer Questgegenstand darauf landet.",
	["The quest list beside the map gets flat scroll bars, search box and buttons."] = "Die Questliste neben der Karte erhält flache Bildlaufleisten, Suchfeld und Schaltflächen.",
	["The quests you share with your party, each member's progress, and one-click Share and Ask buttons. Shares your quest progress with group members who run EldoUI, as addon messages only, never in chat."] = "Die Quests, die Ihr mit Eurer Gruppe teilt, der Fortschritt jedes Mitglieds und die Schaltflächen Teilen und Fragen für einen Klick. Teilt Euren Questfortschritt mit Gruppenmitgliedern, die EldoUI nutzen, nur als Addon-Nachrichten, nie im Chat.",
	["The raid marker your click puts on the rare."] = "Die Schlachtzugsmarkierung, die Euer Klick auf den raren Gegner setzt.",
	["The raid target marker on this unit."] = "Die Schlachtzugszielmarkierung auf dieser Einheit.",
	["The rail holds the buttons. Pick another way to gather them first."] = "Die Seitenleiste hält die Schaltflächen. Wählt zuerst eine andere Art, sie zu sammeln.",
	["The rank a click casts: the highest you know, or a lower one you keep on purpose (to save mana, for example)."] = "Der Rang, den ein Klick wirkt: der höchste, den Ihr kennt, oder ein niedrigerer, den Ihr bewusst behaltet (etwa um Mana zu sparen).",
	["The rank after the guild name, in gray."] = "Der Rang hinter dem Gildennamen, in Grau.",
	["The rares you've met also show on continent maps."] = "Die raren Gegner, denen Ihr begegnet seid, erscheinen auch auf Kontinentkarten.",
	["The ready check on its own mover; ping wheel scale."] = "Der Bereitschaftscheck auf eigenem Verschiebefeld; Skalierung des Ping-Rads.",
	["The reagent line in item tooltips is the Shopping list section on the Tooltip page."] = "Die Reagenzienzeile in Gegenstandstooltips ist der Abschnitt Einkaufsliste auf der Seite Tooltip.",
	["The real clickable plate height Blizzard uses, in pixels. Width and height both need a value. Applied out of combat."] = "Die echte anklickbare Plakettenhöhe, die Blizzard nutzt, in Pixeln. Breite und Höhe brauchen beide einen Wert. Wird außerhalb des Kampfes übernommen.",
	["The real clickable plate size Blizzard uses, in pixels. Also the room plates take when they stack. 0 keeps the game's. Applied out of combat."] = "Die echte anklickbare Plakettengröße, die Blizzard nutzt, in Pixeln. Auch der Platz, den Plaketten beim Stapeln einnehmen. 0 behält den Wert des Spiels. Wird außerhalb des Kampfes übernommen.",
	["The report panel lets the game show through a little. How much: General > Panel opacity."] = "Das Berichtspanel lässt das Spiel etwas durchscheinen. Wie stark: Allgemein > Panel-Deckkraft.",
	["The restock list is already empty."] = "Die Auffüllliste ist schon leer.",
	["The restock list is empty."] = "Die Auffüllliste ist leer.",
	["The reward alert after a dungeon, scenario or world quest."] = "Der Belohnungshinweis nach einem Dungeon, einem Szenario oder einer Weltquest.",
	["The roll line on a panel in your art style, bronze under WoW Forever."] = "Die Wurfzeile auf einem Panel in Eurem Grafikstil, unter WoW Forever bronzen.",
	["The route fades in at take-off and out on landing. Off shows and hides it at once."] = "Die Route blendet beim Abflug ein und bei der Landung aus. Aus zeigt und verbirgt sie sofort.",
	["The row of conditions under the text ([@mouseover], [mod:shift], [nocombat] and more). A click puts one at the cursor, into the bracket you are in."] = "Die Reihe der Bedingungen unter dem Text ([@mouseover], [mod:shift], [nocombat] und mehr). Ein Klick setzt eine an der Schreibmarke ein, in die Klammer, in der Ihr gerade seid.",
	["The rule the rows below change. Rules higher in the list win."] = "Die Regel, die die Zeilen unten ändern. Regeln weiter oben in der Liste haben Vorrang.",
	["The rule's border color and glow show while the unit casts a spell the game marks as important. The game decides, even where the flag is secret."] = "Randfarbe und Leuchten der Regel erscheinen, solange die Einheit einen Zauber wirkt, den das Spiel als wichtig markiert. Das Spiel entscheidet, auch wo die Markierung geheim ist.",
	["The rule's border color and glow show while the unit's health is under the percent below."] = "Randfarbe und Leuchten der Regel erscheinen, solange die Gesundheit der Einheit unter dem Prozentwert unten liegt.",
	["The same for the second character or the Best of all ghost."] = "Dasselbe für den zweiten Charakter oder den Geist Beste von allen.",
	["The same lines without a panel."] = "Dieselben Zeilen ohne Panel.",
	["The same prompt for resurrections. You still click Accept."] = "Dieselbe Abfrage für Wiederbelebungen. Auf Annehmen klickt Ihr weiterhin selbst.",
	["The same settings you could type with /console. EldoUI remembers your own value the first time it changes one, so Restore puts it back."] = "Dieselben Einstellungen, die Ihr mit /console eingeben könntet. EldoUI merkt sich Euren eigenen Wert, wenn es einen zum ersten Mal ändert, damit Wiederherstellen ihn zurückholt.",
	["The same tooltip on the focus frame's cast bar."] = "Derselbe Tooltip auf der Zauberleiste des Fokusrahmens.",
	["The scale as plain text (Strength=1, Agility=0.5 ...) to share."] = "Die Skala als reiner Text (Strength=1, Agility=0.5 ...) zum Teilen.",
	["The scale in Pawn's format, ( Pawn: v1: \"Name\": ... ), for Pawn users and scale websites."] = "Die Skala im Format von Pawn, ( Pawn: v1: \"Name\": ... ), für Pawn-Nutzer und Skalen-Webseiten.",
	["The scale used for this class. Each class remembers its own."] = "Die Skala für diese Klasse. Jede Klasse merkt sich ihre eigene.",
	["The score on every gear tooltip, upgrade or not."] = "Die Wertung in jedem Ausrüstungstooltip, ob Verbesserung oder nicht.",
	["The second line: where the friend is, or when they were last online."] = "Die zweite Zeile: wo der Freund ist oder wann er zuletzt online war.",
	["The sender name of new chat lines. Needs the Chat module's message extras. Whisper, Reply and the right-click menu keep working."] = "Der Absendername neuer Chatzeilen. Benötigt die Nachrichtenextras des Chatmoduls. Flüstern, Antworten und das Rechtsklickmenü funktionieren weiterhin.",
	["The shaman in your group who drops it."] = "Der Schamane Eurer Gruppe, der es aufstellt.",
	["The shape of waypoint pins on the world map and minimap."] = "Die Form der Wegpunktmarkierungen auf Weltkarte und Minikarte.",
	["The shared line ends with the game's map pin link to the place. Sharing moves your own map pin there."] = "Die geteilte Zeile endet mit dem Kartenmarkierungslink des Spiels zu dem Ort. Teilen setzt Eure eigene Kartenmarkierung dorthin.",
	["The shield or imbue icon of the shaman cooldown bar while it is missing (out of combat)."] = "Das Schild- oder Waffenverzauberungssymbol der Schamanen-Abklingzeitleiste, solange es fehlt (außerhalb des Kampfes).",
	["The shield the icon casts."] = "Der Schild, den das Symbol wirkt.",
	["The shop, help, report and GM windows always keep the game's own look and place."] = "Shop-, Hilfe-, Melde- und GM-Fenster behalten immer die eigene Optik und Position des Spiels.",
	["The shopping list is already empty."] = "Die Einkaufsliste ist schon leer.",
	["The side each element's picker opens toward when you point at its button."] = "Die Seite, zu der sich die Auswahl jedes Elements öffnet, wenn Ihr auf seine Schaltfläche zeigt.",
	["The skill range of the herbs and ore veins in the zone."] = "Der Fertigkeitsbereich der Kräuter und Erzadern im Gebiet.",
	["The skill to reach. The plan starts at your skill (or 1 when you don't have the profession)."] = "Die zu erreichende Fertigkeit. Der Plan beginnt bei Eurer Fertigkeit (oder bei 1, wenn Ihr den Beruf nicht habt).",
	["The skinning skill the zone's beasts ask for, from its level range."] = "Die Kürschnerfertigkeit, die die Wildtiere des Gebiets verlangen, abgeleitet aus seinem Stufenbereich.",
	["The small timer on screen. Move it with /eui move."] = "Der kleine Timer auf dem Bildschirm. Verschiebt ihn mit /eui move.",
	["The small zone map (Shift+M). These follow Blizzard UI > Battlefield (zone) map."] = "Die kleine Gebietskarte (Umschalt+M). Diese folgen Blizzard-UI > Schlachtfeldkarte (Gebiet).",
	["The snapshot the buttons below use; the newest is first."] = "Der Schnappschuss, den die Schaltflächen unten verwenden; der neueste steht oben.",
	["The sound each toast plays. The default is the game's epic loot sound."] = "Der Ton, den jeder Hinweis abspielt. Standard ist der Ton des Spiels für epische Beute.",
	["The sound for a dropped shield."] = "Der Ton, wenn ein Schild abfällt.",
	["The sound for a new ping."] = "Der Ton für einen neuen Ping.",
	["The sound for a rare with a mount, pet, toy or set piece you don't own."] = "Der Ton für einen raren Gegner mit einem Reittier, Begleiter, Spielzeug oder Setteil, das Ihr nicht besitzt.",
	["The sound for the ready check, role poll, battleground and dungeon ready pop-ups. The default is the game's ready check sound."] = "Der Ton für Bereitschaftscheck, Rollenabfrage sowie die Bereitschaftsfenster für Schlachtfelder und Dungeons. Standard ist der Bereitschaftscheck-Ton des Spiels.",
	["The sound for treasures, chests and events."] = "Der Ton für Schätze, Truhen und Ereignisse.",
	["The sound that plays with the unhappy pet warning. None for silence."] = "Der Ton zur Warnung bei unglücklichem Tier. Keiner für Stille.",
	["The sound when a summon or resurrection prompt appears. None for silence."] = "Der Ton, wenn eine Beschwörungs- oder Wiederbelebungsabfrage erscheint. Keiner für Stille.",
	["The spell this reminder asks for and a click casts; only it (or its group version) meets the reminder. Automatic: the one you cast last."] = "Der Zauber, den diese Erinnerung verlangt und den ein Klick wirkt; nur er (oder seine Gruppenversion) erfüllt die Erinnerung. Automatisch: der, den Ihr zuletzt gewirkt habt.",
	["The spell tooltip on the target and focus cast bars, a list of the abilities each mob cast in front of you, and reputation info on reputation tokens."] = "Der Zaubertooltip auf den Zauberleisten von Ziel und Fokus, eine Liste der Fähigkeiten, die jeder Gegner vor Euren Augen gewirkt hat, und Rufinfos auf Rufmarken.",
	["The spell's name on the bar."] = "Der Name des Zaubers auf der Leiste.",
	["The strip grows with the font size; this is its smallest height."] = "Der Streifen wächst mit der Schriftgröße; dies ist seine kleinste Höhe.",
	["The strip lets the game show through a little. How much: General > Panel opacity."] = "Der Streifen lässt das Spiel etwas durchscheinen. Wie stark: Allgemein > Panel-Deckkraft.",
	["The strip sits above the window like a title bar, with an accent border."] = "Der Streifen sitzt wie eine Titelleiste über dem Fenster, mit einem Akzentrand.",
	["The switch controls HandyNotes"] = "Der Schalter steuert HandyNotes",
	["The tab above the map (right-click for Blizzard's options) in the EldoUI look."] = "Der Reiter über der Karte (Rechtsklick für Blizzards Optionen) in der EldoUI-Optik.",
	["The talent loadout asks for %d ranks of %s, more than it has. Make the string again on the calculator site."] = { one = "Die Talentkonfiguration verlangt %d Rang von %s, mehr als das Talent hat. Erstellt den String auf der Rechner-Seite neu.", other = "Die Talentkonfiguration verlangt %d Ränge von %s, mehr als das Talent hat. Erstellt den String auf der Rechner-Seite neu." },
	["The talent part of this Wowhead link isn't in a form EldoUI reads."] = "Der Talentteil dieses Wowhead-Links liegt nicht in einer Form vor, die EldoUI liest.",
	["The text in the middle of the screen after a screenshot."] = "Der Text in der Bildschirmmitte nach einem Screenshot.",
	["The text of the tag in the quest window and in quest tooltips, e.g. New or New in Forever."] = "Der Text des Tags im Questfenster und in Questtooltips, z. B. Neu oder Neu in Forever.",
	["The theme font for tooltip text. Off keeps the game font."] = "Die Themenschrift für Tooltiptext. Aus behält die Spielschrift.",
	["The theme font, colors and line numbers."] = "Themenschrift, Farben und Zeilennummern.",
	["The threat border on these plates, in the game's threat color. As on the Effects tab keeps your normal setting."] = "Der Bedrohungsrand auf diesen Plaketten, in der Bedrohungsfarbe des Spiels. Wie im Reiter Effekte behält Eure normale Einstellung.",
	["The ticks already follow the role set."] = "Die Häkchen folgen bereits dem Rollensatz.",
	["The time before each line."] = "Die Uhrzeit vor jeder Zeile.",
	["The timer turns green when you are ahead of your reference and red when behind. Times come from /played, recorded by the Alts module."] = "Der Timer wird grün, wenn Ihr vor Eurer Referenz liegt, und rot, wenn Ihr zurückliegt. Die Zeiten stammen aus /played und werden vom Modul Twinks aufgezeichnet.",
	["The toast in a thin frame line that matches the WoW Forever art style."] = "Der Hinweis in einer dünnen Rahmenlinie passend zum Grafikstil von WoW Forever.",
	["The toast's background; Panel follows your art style."] = "Der Hintergrund des Hinweises; Panel folgt Eurem Grafikstil.",
	["The tooltip border turns green when the item is an upgrade."] = "Der Tooltiprand wird grün, wenn der Gegenstand eine Verbesserung ist.",
	["The totem buffs a shaman's totems give you. The group dims a step for each shaman in your party who is out of range, and fully when all of them are."] = "Die Totemeffekte, die Euch die Totems eines Schamanen geben. Die Gruppe wird für jeden Schamanen Eurer Gruppe, der außer Reichweite ist, eine Stufe dunkler und ganz, wenn alle es sind.",
	["The totem's picture on totem plates."] = "Das Bild des Totems auf Totemplaketten.",
	["The totems each shaman carries and their Ankh count. Yours comes from your bags; another shaman's when they click Share mine."] = "Die Totems, die jeder Schamane dabeihat, und seine Ankh-Anzahl. Eure stammen aus Euren Taschen, die eines anderen Schamanen, sobald er auf Meine teilen klickt.",
	["The totems each shaman carries, their Ankh count, shield, weapon imbues and mana in the Ready Check Report. Yours is read out of combat; Share mine sends yours along."] = "Die Totems, die jeder Schamane dabeihat, seine Ankh-Anzahl, Schild, Waffenverzauberungen und Mana im Bereitschaftsbericht. Eure werden außerhalb des Kampfes gelesen; Meine teilen schickt sie mit.",
	["The tracker is hidden (Hide switch or its box in move mode), so these rules apply once it shows again."] = "Die Zielverfolgung ist ausgeblendet (Schalter Ausblenden oder ihr Feld im Verschiebemodus), daher gelten diese Regeln erst, wenn sie wieder erscheint.",
	["The tracker shows at most this many lines; the planner window shows them all."] = "Die Verfolgung zeigt höchstens so viele Zeilen; das Planerfenster zeigt alle.",
	["The tracker turns see-through or invisible but is never hidden, so quest item buttons keep working in combat. Hover it to see it fully."] = "Die Zielverfolgung wird durchscheinend oder unsichtbar, aber nie ausgeblendet, damit Schaltflächen für Questgegenstände im Kampf weiter funktionieren. Zeigt mit der Maus darauf, um sie ganz zu sehen.",
	["The tracker's background: a full panel in your art style, a see-through one, or text only."] = "Der Hintergrund der Verfolgung: ein volles Panel in Eurem Grafikstil, ein durchscheinendes oder nur Text.",
	["The trade window. Its size (mouse wheel on the title bar), dragging and the resets are on the Move windows page, with every other Blizzard window; where it opens is its mover in move mode (/eui move)."] = "Das Handelsfenster. Seine Größe (Mausrad auf der Titelleiste), das Ziehen und die Zurücksetzungen liegen mit allen anderen Blizzard-Fenstern auf der Seite Fenster verschieben; wo es aufgeht, bestimmt sein Verschiebefeld im Verschiebemodus (/eui move).",
	["The travel list opens when combat ends."] = "Die Reiseliste öffnet sich, wenn der Kampf endet.",
	["The trees, the next point and the Learn buttons follow this plan."] = "Die Bäume, der nächste Punkt und die Erlernen-Schaltflächen folgen diesem Plan.",
	["The unit is behind your camera."] = "Die Einheit ist hinter Eurer Kamera.",
	["The unit is casting or channeling a spell right now."] = "Die Einheit wirkt oder kanalisiert gerade einen Zauber.",
	["The unit's combat state, when the game shows it."] = "Der Kampfzustand der Einheit, wenn das Spiel ihn zeigt.",
	["The unit's crowd control effect (stun, fear, sheep ...) left of the plate, picked by Blizzard's filter."] = "Der Kontrolleffekt auf der Einheit (Betäubung, Furcht, Schaf ...) links neben der Plakette, ausgewählt durch Blizzards Filter.",
	["The unit's level in a small badge, colored by how hard it is for you."] = "Die Stufe der Einheit in einem kleinen Abzeichen, gefärbt danach, wie schwer sie für Euch ist.",
	["The unit's portrait left of the bar."] = "Das Porträt der Einheit links neben der Leiste.",
	["The unit's raid marker (skull, cross ...) in front of the spell name."] = "Die Schlachtzugsmarkierung der Einheit (Totenschädel, Kreuz ...) vor dem Zaubernamen.",
	["The vendor price in the corner of each reward; the most valuable choice in your accent color, unless Upgrades already marks quest rewards. You still pick."] = "Der Händlerpreis in der Ecke jeder Belohnung; die wertvollste Wahl in Eurer Akzentfarbe, sofern Verbesserungen Questbelohnungen nicht schon markiert. Wählen müsst Ihr weiterhin selbst.",
	["The view, create, holiday, raid and picker windows next to the calendar get the EldoUI look too."] = "Die Fenster zum Ansehen, Erstellen, für Feiertage, Schlachtzüge und die Auswahl neben dem Kalender erhalten ebenfalls die EldoUI-Optik.",
	["The water totem the water button drops."] = "Das Wassertotem, das die Wasser-Schaltfläche aufstellt.",
	["The way the buttons fill the bin, then the way the next row goes. The bin opens on that side of its button. Automatic fills rows to the right and follows Bin side."] = "Die Richtung, in der die Schaltflächen den Sammler füllen, dann die Richtung der nächsten Reihe. Der Sammler öffnet sich zu dieser Seite seiner Schaltfläche. Automatisch füllt Reihen nach rechts und folgt Seite des Sammlers.",
	["The waypoint's title under the arrow."] = "Der Titel des Wegpunkts unter dem Pfeil.",
	["The whole frame"] = "Der ganze Rahmen",
	["The window lets the game show through a little. How much: General > Panel opacity."] = "Das Fenster lässt das Spiel etwas durchscheinen. Wie stark: Allgemein > Panel-Deckkraft.",
	["The world map's top right button shows or hides EldoUI's pins: click for groups, Shift-click for all. Alt-right-click the map to add a note."] = "Die Schaltfläche oben rechts auf der Weltkarte zeigt oder verbirgt die Markierungen von EldoUI: Klick für Gruppen, Umschaltklick für alle. Alt-Rechtsklick auf die Karte fügt eine Notiz hinzu.",
	["The world map, flight map and taxi window go back to Blizzard's place."] = "Weltkarte, Flugkarte und Flugmeisterfenster kehren an Blizzards Platz zurück.",
	["The x on a listing dismisses it (by its leader). Bring back on the filter bar shows them again at any time."] = "Das x an einem Eintrag verwirft ihn (nach seinem Anführer). Zurückholen auf der Filterleiste zeigt sie jederzeit wieder an.",
	["The yellow help tips that point at buttons (game setting, where the client has it)."] = "Die gelben Hilfetipps, die auf Schaltflächen zeigen (Spieleinstellung, wo der Client sie hat).",
	["The zone's level range: red is too high for you, yellow is right, green and gray are below you."] = "Der Stufenbereich des Gebiets: Rot ist zu hoch für Euch, Gelb passt, Grün und Grau liegen unter Euch.",
	["Their class"] = "Ihre Klasse",
	["Their class (Priest, Priest 2)"] = "Ihre Klasse (Priester, Priester 2)",
	["Their role (Healer, Tank)"] = "Ihre Rolle (Heiler, Tank)",
	["Their whispers and chat stop reaching you. The game's Ignore list takes them off again."] = "Ihr Flüstern und ihre Chatnachrichten erreichen Euch nicht mehr. In der Ignorierliste des Spiels entfernt Ihr sie wieder.",
	["Theme"] = "Thema",
	["Theme accent"] = "Themenakzent",
	["Theme follows the layout, whispers only in the messenger, a new whisper opens its window (after the fight in combat)."] = "Thema folgt dem Layout, Flüstern nur im Messenger, ein neues Flüstern öffnet sein Fenster (im Kampf erst danach).",
	["Theme texture"] = "Thementextur",
	["Then point at the closest"] = "Dann auf den nächsten zeigen",
	["Theorycrafter"] = "Theorycrafter",
	["There is no Details profile of yours to switch back to."] = "Es gibt kein Details-Profil von Euch, zu dem zurückgewechselt werden kann.",
	["There is no macro rank update to undo."] = "Es gibt keine Rangaktualisierung von Makros, die rückgängig gemacht werden kann.",
	["There is nothing to clear."] = "Es gibt nichts zu leeren.",
	["These change Blizzard's merchant window. Switch them on under Blizzard UI > Items, NPCs and economy > Merchant window."] = "Diese ändern Blizzards Händlerfenster. Schaltet sie unter Blizzard-UI > Gegenstände, NPCs und Wirtschaft > Händlerfenster ein.",
	["These decline a popup for you, so they are off by default. Friends (and, if you like, guild members) are never blocked."] = "Diese lehnen ein Popup für Euch ab, daher sind sie standardmäßig aus. Freunde (und auf Wunsch Gildenmitglieder) werden nie blockiert.",
	["These follow Blizzard UI > Flight map and taxi window."] = "Diese folgen Blizzard-UI > Flugkarte und Flugmeisterfenster.",
	["These follow Blizzard UI > World map and quest log. Each group needs one of its switches."] = "Diese folgen Blizzard-UI > Weltkarte und Questlog. Jede Gruppe braucht einen ihrer Schalter.",
	["These icons show what you are missing or about to lose, such as a class buff, your pet or a consumable you keep up. Each one goes away once it is done. Point at an icon to see why it shows; /eui reminders chooses what is checked."] = "Diese Symbole zeigen, was Euch fehlt oder was Ihr bald verliert, etwa einen Klassenstärkungszauber, Euren Begleiter oder ein Verbrauchsgut, das Ihr aufrechterhaltet. Jedes verschwindet, sobald es erledigt ist. Zeigt auf ein Symbol, um zu sehen, warum es erscheint; /eui reminders wählt, was geprüft wird.",
	["These settings show when Questie is loaded."] = "Diese Einstellungen erscheinen, wenn Questie geladen ist.",
	["These styles shape EldoUI's minimap, not the game's own."] = "Diese Stile formen die Minikarte von EldoUI, nicht die des Spiels.",
	["These use only the game's own flags: whether the cast can be interrupted and whether it is a channel. EldoUI keeps no spell lists."] = "Diese nutzen nur die eigenen Markierungen des Spiels: ob der Zauber unterbrochen werden kann und ob er kanalisiert wird. EldoUI führt keine Zauberlisten.",
	["These work while \"%s\" is on in Blizzard UI; each one names the switch it needs there."] = "Diese wirken, solange \"%s\" in Blizzard-UI an ist; jede nennt den Schalter, den sie dort braucht.",
	["These work while Blizzard UI > Objective / quest tracker is on. Each group below follows one of its switches."] = "Diese wirken, solange Blizzard-UI > Ziel-/Questverfolgung an ist. Jede Gruppe unten folgt einem ihrer Schalter.",
	["They hang under EldoUI's minimap wherever you move it."] = "Sie hängen unter der Minikarte von EldoUI, wohin Ihr sie auch verschiebt.",
	["Thickness of each bar in pixels."] = "Dicke jeder Leiste in Pixeln.",
	["Thickness of the health bar."] = "Dicke der Gesundheitsleiste.",
	["Thin 100 x 5 lines with small text and few icons, smaller minor units and pets. Good in big pulls. Effects: Off."] = "Dünne Linien mit 100 x 5, kleinem Text und wenigen Symbolen, kleinere Nebeneinheiten und Begleiter. Gut bei großen Pulls. Effekte: Aus.",
	["Thin accent lines on each section header instead of Blizzard's header art."] = "Dünne Akzentlinien an jeder Abschnittsüberschrift statt Blizzards Überschriftengrafik.",
	["Thin bars with a slim power bar, health in percent."] = "Dünne Leisten mit schmaler Ressourcenleiste, Gesundheit in Prozent.",
	["Thin frame line"] = "Dünne Rahmenlinie",
	["Thin line"] = "Dünne Linie",
	["Thin lines that cut each bar into equal parts. 19 gives Blizzard's classic 20 blocks."] = "Dünne Linien, die jede Leiste in gleiche Teile teilen. 19 ergibt Blizzards klassische 20 Blöcke.",
	["Thin see-through panels across the top and bottom edge with an accent line, and the volume panel."] = "Dünne durchscheinende Panels am oberen und unteren Rand mit einer Akzentlinie sowie das Lautstärkepanel.",
	["This Wowhead link holds no talent build. Copy the link from the talent calculator after you pick your talents."] = "Dieser Wowhead-Link enthält keinen Talentbuild. Kopiert den Link aus dem Talentrechner, nachdem Ihr Eure Talente gewählt habt.",
	["This Wowhead link is for another game version, whose talent trees differ from WoW: Forever's."] = "Dieser Wowhead-Link gehört zu einer anderen Spielversion, deren Talentbäume sich von denen in WoW: Forever unterscheiden.",
	["This character (%d)"] = "Dieser Charakter (%d)",
	["This character is not a shaman, so the bars stay hidden. The \"Totem buffs on you\" example in Aura Groups works for every class."] = "Dieser Charakter ist kein Schamane, daher bleiben die Leisten ausgeblendet. Das Beispiel „Totemeffekte auf Euch“ in Aurengruppen funktioniert für jede Klasse.",
	["This client does not list its game settings for addons."] = "Dieser Client listet seine Spieleinstellungen nicht für Addons auf.",
	["This is your other talent group. Switch to it in Blizzard's talent window first."] = "Das ist Eure andere Talentgruppe. Wechselt zuerst in Blizzards Talentfenster zu ihr.",
	["This line has no /command, so it is said in chat."] = "Diese Zeile hat keinen /Befehl, daher wird sie im Chat gesagt.",
	["This link is for a class WoW: Forever doesn't have."] = "Dieser Link gehört zu einer Klasse, die es in WoW: Forever nicht gibt.",
	["This loadout holds no totems."] = "Diese Zusammenstellung enthält keine Totems.",
