	["Turns on the Blizzard UI switch for the bag bar with Move and scale."] = "Schaltet den Blizzard-UI-Schalter für die Taschenleiste mit Verschieben und skalieren ein.",
	["Turns on the Blizzard UI switch for the micro menu with Move and scale."] = "Schaltet den Blizzard-UI-Schalter für das Mikromenü mit Verschieben und skalieren ein.",
	["Turns on the Blizzard UI switch for the minimap buttons with Move."] = "Schaltet den Blizzard-UI-Schalter für die Minikartenschaltflächen mit Verschieben ein.",
	["Turns on the Blizzard UI switch for the minimap with Replace."] = "Schaltet den Blizzard-UI-Schalter für die Minikarte mit Ersetzen ein.",
	["Turns on the Blizzard UI switch for this element with Replace, so only EldoUI's bars show."] = "Schaltet den Blizzard-UI-Schalter für dieses Element mit Ersetzen ein, damit nur die Leisten von EldoUI erscheinen.",
	["Turns the ring: 0 puts the first entry (or the middle of an arc) at the top, clockwise."] = "Dreht den Ring: 0 setzt den ersten Eintrag (oder die Mitte eines Bogens) nach oben, im Uhrzeigersinn.",
	["Turns your party into a raid, or a raid of five or fewer back into a party."] = "Macht aus Eurer Gruppe einen Schlachtzug oder aus einem Schlachtzug mit fünf oder weniger Mitgliedern wieder eine Gruppe.",
	["Turns your party into a raid, or a small raid back into a party (group leader)."] = "Macht aus Eurer Gruppe einen Schlachtzug oder aus einem kleinen Schlachtzug wieder eine Gruppe (Gruppenanführer).",
	["Tutorials and help tips off (game settings; Blizzard default puts yours back)."] = "Tutorials und Hilfetipps aus (Spieleinstellungen; Blizzard-Standard stellt Eure wieder her).",
	["Tutorials off"] = "Tutorials aus",
	["Twilight slim"] = "Zwielicht schmal",
	["Two"] = "Zwei",
	["Two buttons on the preview: take everything off the model, or show your target's look. Blizzard's Reset button stays."] = "Zwei Schaltflächen in der Vorschau: alles vom Modell ausziehen oder das Aussehen Eures Ziels zeigen. Blizzards Schaltfläche Zurücksetzen bleibt.",
	["Two characters level by level: time per level, total played at each level-up and the difference."] = "Zwei Charaktere Stufe für Stufe: Zeit pro Stufe, Gesamtspielzeit bei jedem Stufenaufstieg und die Differenz.",
	["Two columns"] = "Zwei Spalten",
	["Two columns of rows, for vendors with long lists."] = "Zwei Spalten mit Zeilen, für Händler mit langen Listen.",
	["Two rows"] = "Zwei Reihen",
