	["Two-handed leveling"] = "Leveln mit Zweihänder",
	["Type /eui pull, /eui pull 8 or /eui pull cancel."] = "Gebt /eui pull, /eui pull 8 oder /eui pull cancel ein.",
	["Type a character name first, for example Name-Realm."] = "Gebt zuerst einen Charakternamen ein, zum Beispiel Name-Realm.",
	["Type a name, press Enter, then click Rename."] = "Gebt einen Namen ein, drückt die Eingabetaste und klickt dann auf Umbenennen.",
	["Type a spell ID and press Enter."] = "Gebt eine Zauber-ID ein und drückt die Eingabetaste.",
	["Type a spell or item name. Empty shows every icon the game offers."] = "Gebt einen Zauber- oder Gegenstandsnamen ein. Leer zeigt jedes Symbol, das das Spiel anbietet.",
	["Type a value and press Enter or Set. The game checks it; a value it refuses is not kept."] = "Gebt einen Wert ein und drückt die Eingabetaste oder klickt auf Festlegen. Das Spiel prüft ihn; einen abgelehnten Wert behält es nicht.",
	["Type coordinates"] = "Koordinaten eingeben",
	["Type coordinates, like 45.2 63.8 or Elwynn Forest 41 65 Inn."] = "Gebt Koordinaten ein, etwa 45.2 63.8 oder Wald von Elwynn 41 65 Gasthaus.",
	["Type part of a name or help text and press Enter."] = "Gebt einen Teil eines Namens oder Hilfetexts ein und drückt die Eingabetaste.",
	["Type the frame name of an addon button the bin does not find by itself, then press Enter. The game's own buttons and protected buttons stay where they are."] = "Gebt den Rahmennamen einer Addon-Schaltfläche ein, die der Sammler nicht selbst findet, und drückt dann die Eingabetaste. Die eigenen Schaltflächen des Spiels und geschützte Schaltflächen bleiben, wo sie sind.",
	["Typical node types"] = "Typische Arten von Vorkommen",
