	["Uncommon or better"] = "Selten oder besser",
	["Under each reagent: how many more wait in your bank."] = "Unter jedem Reagenz: wie viele weitere in Eurer Bank warten.",
	["Under loot rolls"] = "Unter Beutewürfen",
	["Under the 'delete this item' pop-up: which quest the item belongs to or starts, and whether you are on it. Text only; you still decide."] = "Unter dem Pop-up „Diesen Gegenstand löschen“: zu welcher Quest der Gegenstand gehört oder welche er startet und ob Ihr sie habt. Nur Text; Ihr entscheidet weiterhin selbst.",
	["Under the Cooldown Manager"] = "Unter dem Abklingzeitenmanager",
	["Under the bars"] = "Unter den Leisten",
