	["Under the health bar"] = "Unter der Gesundheitsleiste",
	["Under the health bar, a smaller bar on the frame's bottom edge, or (player) a separate bar with its own mover, Player Frame Power Bar."] = "Unter der Gesundheitsleiste, eine kleinere Leiste am unteren Rand des Rahmens oder (Spieler) eine eigene Leiste mit eigenem Verschiebefeld, Ressourcenleiste des Spielerrahmens.",
	["Under the icon"] = "Unter dem Symbol",
	["Under the mouse"] = "Unter der Maus",
	["Under the name"] = "Unter dem Namen",
	["Under the name: level, race and class, zone, and whether the contact is a friend or in your guild. The level shows once the game has seen the player."] = "Unter dem Namen: Stufe, Volk und Klasse, Gebiet und ob der Kontakt ein Freund oder in Eurer Gilde ist. Die Stufe erscheint, sobald das Spiel den Spieler gesehen hat.",
	["Underline"] = "Unterstrich",
	["Undo rank update"] = "Rangaktualisierung rückgängig",
	["Undress"] = "Ausziehen",
	["Undress and Target buttons"] = "Schaltflächen Ausziehen und Ziel",
	["Unexplored areas (Improve)"] = "Unerforschte Gebiete (Verbessern)",
	["Unexplored areas show dimmed, in every zone from your first login. Also works on the battlefield map when you let EldoUI change that map."] = "Unerforschte Bereiche erscheinen abgedunkelt, in jedem Gebiet ab Eurem ersten Login. Funktioniert auch auf der Schlachtfeldkarte, wenn Ihr EldoUI diese Karte ändern lasst.",
	["Unhappy pet warning"] = "Warnung bei unglücklichem Tier",
	["Unit"] = "Einheit",
	["Unit frames: your target"] = "Einheitenrahmen: Euer Ziel",
	["Unit in combat"] = "Einheit im Kampf",
	["Unit names or NPC IDs, separated by commas. Only outside instances: inside, the game keeps who a unit is secret, so the rule doesn't match there."] = "Einheitennamen oder NSC-IDs, durch Kommas getrennt. Nur außerhalb von Instanzen: In Instanzen hält das Spiel geheim, wer eine Einheit ist, daher greift die Regel dort nicht.",
	["Unit tooltips"] = "Einheitentooltips",
	["Units"] = "Einheiten",
	["Unknown"] = "Unbekannt",
	["Unknown command /%s."] = "Unbekannter Befehl /%s.",
	["Unknown condition %s."] = "Unbekannte Bedingung %s.",
	["Unknown line #%s: only #show and #showtooltip are read."] = "Unbekannte Zeile #%s: Nur #show und #showtooltip werden gelesen.",
	["Unknown option. Try /eui help talents."] = "Unbekannte Option. Versucht /eui help talents.",
	["Unknown player"] = "Unbekannter Spieler",
	["Unknown talent"] = "Unbekanntes Talent",
	["Unknown zone"] = "Unbekanntes Gebiet",
	["Unlock EldoUI frames to drag the Rare History window."] = "Entsperrt die EldoUI-Rahmen, um das Fenster Rar-Verlauf zu ziehen.",
	["Unlock EldoUI frames to drag the bar. Show for a minute (top of the page) makes it visible outside a group."] = "Entsperrt die EldoUI-Rahmen, um die Leiste zu ziehen. Eine Minute lang anzeigen (oben auf der Seite) macht sie außerhalb einer Gruppe sichtbar.",
	["Unlock EldoUI frames to drag the card."] = "Entsperrt die EldoUI-Rahmen, um die Karte zu ziehen.",
	["Unlock EldoUI frames to drag the reminders (mover \"Reminders\")."] = "Entsperrt die EldoUI-Rahmen, um die Erinnerungen zu ziehen (Verschiebefeld „Erinnerungen“).",
	["Unlock EldoUI frames to drag the travel button (mover \"Mage Travel\")."] = "Entsperrt die EldoUI-Rahmen, um die Reiseschaltfläche zu ziehen (Verschiebefeld „Magierreisen“).",
	["Unpin all"] = "Alle lösen",
	["Unpinned."] = "Gelöst.",
	["Unread senders in the accent color"] = "Ungelesene Absender in der Akzentfarbe",
	["Unread senders in the game's gold, no stripes."] = "Ungelesene Absender im Gold des Spiels, keine Streifen.",
	["Until /reload"] = "Bis /reload",
	["Untrack"] = "Nicht mehr verfolgen",
	["Untrack all quests"] = "Alle Quests nicht mehr verfolgen",
	["Up"] = "Nach oben",
	["Up to %d menus."] = "Bis zu %d Menüs.",
	["Up, then left"] = "Nach oben, dann links",
	["Up, then right"] = "Nach oben, dann rechts",
	["Upcoming"] = "Demnächst",
	["Upcoming always lists what opens within this many levels; with All later levels on it lists the rest too."] = "Demnächst listet immer, was innerhalb so vieler Stufen freigeschaltet wird; mit Alle späteren Stufen listet es auch den Rest.",
	["Upcoming lists everything you learn at later levels, up to the level cap. Off keeps it to the next few levels."] = "Demnächst listet alles, was Ihr auf späteren Stufen erlernt, bis zur Höchststufe. Aus beschränkt es auf die nächsten paar Stufen.",
	["Update spell ranks"] = "Zauberränge aktualisieren",
	["Update to %s"] = "Auf %s aktualisieren",
	["Upgrade"] = "Verbesserung",
	["Upgrade arrows come from Upgrades, sell values from Quality of Life. Quest helpers are in Quality of Life > Quests, off by default."] = "Verbesserungspfeile kommen von Verbesserungen, Verkaufswerte von Komfortfunktionen. Questhelfer liegen unter Komfortfunktionen > Quests, standardmäßig aus.",
	["Upgrade arrows from a stat-weight scale: tooltips, bags, merchants, loot rolls and quest rewards."] = "Verbesserungspfeile nach einer Skala mit Wertgewichtungen: Tooltips, Taschen, Händler, Beutewürfe und Questbelohnungen.",
	["Upgrade row and green border in tooltips, arrows on icons and quest rewards."] = "Verbesserungszeile und grüner Rand in Tooltips, Pfeile auf Symbolen und Questbelohnungen.",
	["Upgrade row in tooltips"] = "Verbesserungszeile in Tooltips",
	["Upgrade scale"] = "Verbesserungsskala",
	["Upgrades"] = "Verbesserungen",
	["Upgrades settings"] = "Einstellungen für Verbesserungen",
	["Upright bars"] = "Senkrechte Leisten",
	["Upright bars show their percent in a small tag beside the stack, at the height the fill reaches, with a pointer in the bar's color. The tag moves up as the bar fills."] = "Senkrechte Leisten zeigen ihren Prozentwert in einer kleinen Wertanzeige neben dem Stapel, auf der Höhe, die die Füllung erreicht, mit einem Zeiger in der Farbe der Leiste. Die Anzeige wandert nach oben, während sich die Leiste füllt.",
	["Upwards"] = "Aufwärts",
	["Usable only"] = "Nur benutzbare",
	["Usage: /eui cutscenes forget"] = "Verwendung: /eui cutscenes forget",
	["Usage: /eui notify test [lane|errors|warning|bg|pings]"] = "Verwendung: /eui notify test [lane|errors|warning|bg|pings]",
	["Usage: /eui raidloot clear [sr | tmb]"] = "Verwendung: /eui raidloot clear [sr | tmb]",
	["Usage: /eui raidloot post <item link or ID>"] = "Verwendung: /eui raidloot post <item link or ID>",
	["Usage: /eui streamer [on | off | toggle]"] = "Verwendung: /eui streamer [on | off | toggle]",
	["Usage: /eui testframes [on | off | toggle]"] = "Verwendung: /eui testframes [on | off | toggle]",
	["Usage: /eui tracker on | off | toggle"] = "Verwendung: /eui tracker on | off | toggle",
	["Usage: /eui training [spells | weapons | config | on | off]"] = "Verwendung: /eui training [spells | weapons | config | on | off]",
	["Use Blizzard plates"] = "Blizzard-Plaketten verwenden",
	["Use EldoUI plates"] = "EldoUI-Plaketten verwenden",
	["Use EldoUI's bars instead of Blizzard's"] = "Leisten von EldoUI statt Blizzards verwenden",
	["Use Players > Fill from your group, or add players by name."] = "Nutzt Spieler > Aus Eurer Gruppe füllen oder fügt Spieler per Name hinzu.",
	["Use a group plan"] = "Gruppenplan verwenden",
	["Use an entry by"] = "Eintrag benutzen durch",
	["Use compact stat names and amounts for recognized item effects, including comparison tooltips."] = "Kompakte Wertenamen und -zahlen für erkannte Gegenstandseffekte verwenden, auch in Vergleichstooltips.",
	["Use it"] = "Verwenden",
	["Use one {main} placeholder. For example, alt of {main} matches a full note containing that main name."] = "Verwendet einen einzigen Platzhalter {main}. Zum Beispiel erkennt Twink von {main} eine vollständige Notiz, die diesen Main-Namen enthält.",
	["Use only the members you choose. Otherwise priests, druids, paladins and shamans are included."] = "Nur die Mitglieder verwenden, die Ihr auswählt. Sonst werden Priester, Druiden, Paladine und Schamanen einbezogen.",
	["Use style filters"] = "Stilfilter verwenden",
	["Use the EldoUI accent color for the target highlight."] = "Die EldoUI-Akzentfarbe für die Zielhervorhebung verwenden.",
	["Use the EldoUI font"] = "EldoUI-Schrift verwenden",
	["Use the EldoUI minimap"] = "EldoUI-Minikarte verwenden",
	["Use the game's map pin"] = "Kartenmarkierung des Spiels verwenden",
	["Use the largest distance"] = "Größte Entfernung verwenden",
	["Use the role set again"] = "Rollensatz wieder verwenden",
	["Use the suggested style"] = "Vorgeschlagenen Stil verwenden",
	["Use this plan"] = "Diesen Plan verwenden",
	["Use this rule."] = "Diese Regel verwenden.",
	["Use your own color behind the bar."] = "Eure eigene Farbe hinter der Leiste verwenden.",
	["Used when \"Color by standing\" is off."] = "Wird verwendet, wenn „Nach Rufstufe färben“ aus ist.",
	["Used when the accent color is off."] = "Wird verwendet, wenn die Akzentfarbe aus ist.",
	["Used while \"Color by standing\" is off."] = "Wird verwendet, solange „Nach Rufstufe färben“ aus ist.",
	["Used while \"Threat status color\" is off."] = "Wird verwendet, solange „Farbe nach Bedrohungsstatus“ aus ist.",
	["Uses %s with your picks."] = "Nutzt %s mit Eurer Auswahl.",
	["Uses the game's classification (the dragon on the target frame)."] = "Nutzt die Einstufung des Spiels (der Drache am Zielrahmen).",
	["Uses the game's own threat state. If the game hides it, the plate keeps its normal color."] = "Nutzt den eigenen Bedrohungszustand des Spiels. Verbirgt das Spiel ihn, behält die Plakette ihre normale Farbe.",
