	["Vibration strength"] = "Vibrationsstärke",
	["Visibility"] = "Sichtbarkeit",
	["Visibility of healer rows outside the game's group range."] = "Sichtbarkeit der Heilerzeilen außerhalb der Gruppenreichweite des Spiels.",
	["Visibility on the Micro Menu and Bag Bar page changes it again."] = "Sichtbarkeit auf der Seite Mikromenü und Taschenleiste ändert es wieder.",
	["Visibility rules need the EldoUI minimap (Replace in Blizzard UI)."] = "Sichtbarkeitsregeln brauchen die EldoUI-Minikarte (Ersetzen in Blizzard-UI).",
	["Volume"] = "Lautstärke",
