	["Wait for the full roster or clear the filters."] = "Wartet auf die vollständige Mitgliederliste oder setzt die Filter zurück.",
	["Wait until combat ends"] = "Bis Kampfende warten",
	["Waiting"] = "Wartet",
	["Waiting for %s to invite you."] = "Wartet darauf, dass %s Euch einlädt.",
